                      <td className="px-6 py-4 text-slate-600 text-xs print:px-2 print:py-2">
                        {vehicle.foreman}
                      </td>
                      <td className="px-6 py-4 print:hidden">
                        <div className="flex justify-center gap-2 opacity-70 group-hover:opacity-100 transition-opacity">
