ALTER TABLE refueling_logs ADD COLUMN IF NOT EXISTS "municipalitySnapshot" text;
ALTER TABLE refueling_logs ADD COLUMN IF NOT EXISTS "time" text;
ALTER TABLE refueling_logs ADD COLUMN IF NOT EXISTS "invoiceNumber" text;
ALTER TABLE refueling_logs ADD COLUMN IF NOT EXISTS "requisitionNumber" text;

-- Colunas para Veículos
ALTER TABLE vehicles ADD COLUMN IF NOT EXISTS "model" text;
ALTER TABLE vehicles ADD COLUMN IF NOT EXISTS "year" text;
ALTER TABLE vehicles ADD COLUMN IF NOT EXISTS "foreman" text;

-- 2. REINICIAR PERMISSÕES (LIBERAÇÃO TOTAL)
-- Removemos as políticas antigas para evitar conflitos de "authenticated" vs "anon".

DROP POLICY IF EXISTS "Permitir tudo para autenticados" ON vehicles;
DROP POLICY IF EXISTS "Permitir tudo para autenticados" ON daily_logs;
DROP POLICY IF EXISTS "Permitir tudo para autenticados" ON gas_stations;
DROP POLICY IF EXISTS "Permitir tudo para autenticados" ON refueling_logs;
DROP POLICY IF EXISTS "Permitir tudo para autenticados" ON requisitions;
DROP POLICY IF EXISTS "Permitir tudo para autenticados" ON user_vehicles;
DROP POLICY IF EXISTS "Permitir tudo para autenticados" ON user_roles;
DROP POLICY IF EXISTS "Acesso Total" ON vehicles;
DROP POLICY IF EXISTS "Acesso Total" ON daily_logs;
DROP POLICY IF EXISTS "Acesso Total" ON gas_stations;
DROP POLICY IF EXISTS "Acesso Total" ON refueling_logs;
DROP POLICY IF EXISTS "Acesso Total" ON requisitions;
DROP POLICY IF EXISTS "Acesso Total" ON user_vehicles;
DROP POLICY IF EXISTS "Acesso Total" ON user_roles;

-- Cria políticas universais (Leitura e Escrita para todos)
CREATE POLICY "Acesso Total" ON vehicles FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Acesso Total" ON daily_logs FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Acesso Total" ON gas_stations FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Acesso Total" ON refueling_logs FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Acesso Total" ON requisitions FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Acesso Total" ON user_vehicles FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Acesso Total" ON user_roles FOR ALL USING (true) WITH CHECK (true);
```

**Passo 2: Atualização de Segurança no Código**
Vou aplicar uma pequena correção no `Reports.tsx` para garantir que, se um registro vier com data inválida (por erro anterior), ele não quebre a lista inteira.

