                          <button onClick={() => confirmDelete(log.id)} className="p-1.5 text-red-500 hover:bg-red-50 rounded transition-colors" title="Excluir"><Trash2 size={18} /></button>
                        </div>
                      </td>
                     )}
                   </tr>
                 )})
               )}
             </tbody>
           </table>
         </div>

         {/* Pagination Controls */}
         {totalPages > 1 && (
             <div className="flex items-center justify-between border-t border-slate-200 bg-white px-4 py-3 sm:px-6 print:hidden">
                 <div className="flex flex-1 justify-between sm:hidden">
                     <button
                         onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                         disabled={currentPage === 1}
                         className="relative inline-flex items-center rounded-md border border-slate-300 bg-white px-4 py-2 text-sm font-medium text-slate-700 hover:bg-slate-50 disabled:opacity-50"
                     >
                         Anterior
                     </button>
                     <button
                         onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                         disabled={currentPage === totalPages}
                         className="relative ml-3 inline-flex items-center rounded-md border border-slate-300 bg-white px-4 py-2 text-sm font-medium text-slate-700 hover:bg-slate-50 disabled:opacity-50"
                     >
                         Próximo
                     </button>
                 </div>
                 <div className="hidden sm:flex sm:flex-1 sm:items-center sm:justify-between">
                     <div>
                         <p className="text-sm text-slate-700">
                             Mostrando <span className="font-bold">{(currentPage - 1) * itemsPerPage + 1}</span> até <span className="font-bold">{Math.min(currentPage * itemsPerPage, filteredLogs.length)}</span> de <span className="font-bold">{filteredLogs.length}</span> resultados
                         </p>
                     </div>
                     <div>
                         <nav className="isolate inline-flex -space-x-px rounded-md shadow-sm" aria-label="Pagination">
                             <button
                                 onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                                 disabled={currentPage === 1}
                                 className="relative inline-flex items-center rounded-l-md px-2 py-2 text-slate-400 ring-1 ring-inset ring-slate-300 hover:bg-slate-50 focus:z-20 focus:outline-offset-0 disabled:opacity-50"
                             >
                                 <span className="sr-only">Anterior</span>
                                 <ChevronLeft className="h-5 w-5" aria-hidden="true" />
                             </button>
                             {/* Simplified Pagination Numbers */}
                             <span className="relative inline-flex items-center px-4 py-2 text-sm font-semibold text-slate-700 ring-1 ring-inset ring-slate-300 focus:outline-offset-0">
                                 Página {currentPage} de {totalPages}
                             </span>
                             <button
                                 onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                                 disabled={currentPage === totalPages}
                                 className="relative inline-flex items-center rounded-r-md px-2 py-2 text-slate-400 ring-1 ring-inset ring-slate-300 hover:bg-slate-50 focus:z-20 focus:outline-offset-0 disabled:opacity-50"
                             >
                                 <span className="sr-only">Próximo</span>
                                 <ChevronRight className="h-5 w-5" aria-hidden="true" />
                             </button>
                         </nav>
                     </div>
                 </div>
             </div>
         )}
      </div>
    </div>
  );
};

export default Reports;

payload.text:
Para resolver definitivamente o problema de **"Salva mas não aparece"**, o erro está quase certamente em duas frentes:
1.  **Colunas faltando no banco:** O aplicativo envia dados (como `nonOperatingReason` ou `historicalDriver`), o banco não tem essas colunas e descarta o registro silenciosamente ou corrompe a gravação.
2.  **Permissões (RLS):** O banco permite gravar (INSERT), mas bloqueia a leitura (SELECT) para o usuário.

Aqui está a **Solução Definitiva em SQL**. Copie e cole todo o bloco abaixo no **SQL Editor** do Supabase e clique em **RUN**. Isso vai reparar a estrutura de todas as tabelas e liberar o acesso total para o aplicativo funcionar sem bloqueios.

### SQL Definitivo (Execute no Supabase)

```sql
-- PARTE 1: GARANTIR QUE TODAS AS COLUNAS EXISTAM (SCHEMA FIX)
-- Isso impede que dados sejam descartados por falta de coluna

-- Tabela daily_logs
CREATE TABLE IF NOT EXISTS daily_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid());
ALTER TABLE daily_logs ADD COLUMN IF NOT EXISTS "date" text;
ALTER TABLE daily_logs ADD COLUMN IF NOT EXISTS "vehicleId" text;
ALTER TABLE daily_logs ADD COLUMN IF NOT EXISTS "firstIgnition" text;
ALTER TABLE daily_logs ADD COLUMN IF NOT EXISTS "startTime" text;
ALTER TABLE daily_logs ADD COLUMN IF NOT EXISTS "endTime" text;
ALTER TABLE daily_logs ADD COLUMN IF NOT EXISTS "lunchStart" text;
ALTER TABLE daily_logs ADD COLUMN IF NOT EXISTS "lunchEnd" text;
ALTER TABLE daily_logs ADD COLUMN IF NOT EXISTS "extraTimeStart" text;
ALTER TABLE daily_logs ADD COLUMN IF NOT EXISTS "extraTimeEnd" text;
ALTER TABLE daily_logs ADD COLUMN IF NOT EXISTS "kmDriven" numeric;
ALTER TABLE daily_logs ADD COLUMN IF NOT EXISTS "maxSpeed" numeric;
ALTER TABLE daily_logs ADD COLUMN IF NOT EXISTS "speedingCount" numeric;
ALTER TABLE daily_logs ADD COLUMN IF NOT EXISTS "observations" text;
ALTER TABLE daily_logs ADD COLUMN IF NOT EXISTS "nonOperatingReason" text;
ALTER TABLE daily_logs ADD COLUMN IF NOT EXISTS "kmBeforeRefueling" numeric;
-- Snapshots Históricos (Essenciais para o relatório não quebrar se o veículo for apagado)
ALTER TABLE daily_logs ADD COLUMN IF NOT EXISTS "historicalPlate" text;
ALTER TABLE daily_logs ADD COLUMN IF NOT EXISTS "historicalModel" text;
ALTER TABLE daily_logs ADD COLUMN IF NOT EXISTS "historicalDriver" text;
ALTER TABLE daily_logs ADD COLUMN IF NOT EXISTS "historicalMunicipality" text;
ALTER TABLE daily_logs ADD COLUMN IF NOT EXISTS "historicalContract" text;

-- Tabela refueling_logs
CREATE TABLE IF NOT EXISTS refueling_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid());
ALTER TABLE refueling_logs ADD COLUMN IF NOT EXISTS "date" text;
ALTER TABLE refueling_logs ADD COLUMN IF NOT EXISTS "time" text;
ALTER TABLE refueling_logs ADD COLUMN IF NOT EXISTS "vehicleId" text;
ALTER TABLE refueling_logs ADD COLUMN IF NOT EXISTS "gasStationId" text;
ALTER TABLE refueling_logs ADD COLUMN IF NOT EXISTS "fuelType" text;
ALTER TABLE refueling_logs ADD COLUMN IF NOT EXISTS "liters" numeric;
ALTER TABLE refueling_logs ADD COLUMN IF NOT EXISTS "totalCost" numeric;
ALTER TABLE refueling_logs ADD COLUMN IF NOT EXISTS "invoiceNumber" text;
ALTER TABLE refueling_logs ADD COLUMN IF NOT EXISTS "requisitionNumber" text;
ALTER TABLE refueling_logs ADD COLUMN IF NOT EXISTS "observation" text;
-- Snapshots Abastecimento
ALTER TABLE refueling_logs ADD COLUMN IF NOT EXISTS "plateSnapshot" text;
ALTER TABLE refueling_logs ADD COLUMN IF NOT EXISTS "modelSnapshot" text;
ALTER TABLE refueling_logs ADD COLUMN IF NOT EXISTS "foremanSnapshot" text;
ALTER TABLE refueling_logs ADD COLUMN IF NOT EXISTS "contractSnapshot" text;
ALTER TABLE refueling_logs ADD COLUMN IF NOT EXISTS "municipalitySnapshot" text;

-- Tabela vehicles
CREATE TABLE IF NOT EXISTS vehicles (id text PRIMARY KEY); -- ID manual é usado aqui
ALTER TABLE vehicles ADD COLUMN IF NOT EXISTS "plate" text;
ALTER TABLE vehicles ADD COLUMN IF NOT EXISTS "contract" text;
ALTER TABLE vehicles ADD COLUMN IF NOT EXISTS "driverName" text;
ALTER TABLE vehicles ADD COLUMN IF NOT EXISTS "municipality" text;
ALTER TABLE vehicles ADD COLUMN IF NOT EXISTS "type" text;
ALTER TABLE vehicles ADD COLUMN IF NOT EXISTS "status" text;
ALTER TABLE vehicles ADD COLUMN IF NOT EXISTS "model" text;
ALTER TABLE vehicles ADD COLUMN IF NOT EXISTS "year" text;
ALTER TABLE vehicles ADD COLUMN IF NOT EXISTS "foreman" text;

-- Outras Tabelas
CREATE TABLE IF NOT EXISTS gas_stations (id uuid PRIMARY KEY DEFAULT gen_random_uuid());
ALTER TABLE gas_stations ADD COLUMN IF NOT EXISTS "name" text;
ALTER TABLE gas_stations ADD COLUMN IF NOT EXISTS "municipality" text;

CREATE TABLE IF NOT EXISTS requisitions (id uuid PRIMARY KEY DEFAULT gen_random_uuid());
ALTER TABLE requisitions ADD COLUMN IF NOT EXISTS "internalId" numeric;
ALTER TABLE requisitions ADD COLUMN IF NOT EXISTS "status" text;

-- PARTE 2: LIBERAÇÃO TOTAL DE PERMISSÕES (RLS FIX)
-- Removemos políticas antigas que causam conflito e criamos uma política "Permitir Tudo"

-- Habilitar RLS (Necessário para aplicar políticas)
ALTER TABLE vehicles ENABLE ROW LEVEL SECURITY;
ALTER TABLE daily_logs ENABLE ROW LEVEL SECURITY;
ALTER TABLE gas_stations ENABLE ROW LEVEL SECURITY;
ALTER TABLE refueling_logs ENABLE ROW LEVEL SECURITY;
ALTER TABLE requisitions ENABLE ROW LEVEL SECURITY;
ALTER TABLE user_vehicles ENABLE ROW LEVEL SECURITY;
ALTER TABLE user_roles ENABLE ROW LEVEL SECURITY;

-- Limpar políticas antigas
DROP POLICY IF EXISTS "Public Access" ON vehicles;
DROP POLICY IF EXISTS "Public Access" ON daily_logs;
DROP POLICY IF EXISTS "Public Access" ON gas_stations;
DROP POLICY IF EXISTS "Public Access" ON refueling_logs;
DROP POLICY IF EXISTS "Public Access" ON requisitions;
DROP POLICY IF EXISTS "Public Access" ON user_vehicles;
DROP POLICY IF EXISTS "Public Access" ON user_roles;

DROP POLICY IF EXISTS "Permitir tudo para autenticados" ON vehicles;
DROP POLICY IF EXISTS "Permitir tudo para autenticados" ON daily_logs;
-- (Repita drop se tiver outros nomes, mas o CREATE abaixo sobrescreve se o nome for diferente ou erro se igual)

-- CRIAR POLÍTICA UNIVERSAL (LEITURA E ESCRITA PARA TODOS OS LOGADOS E ANÔNIMOS)
-- Isso resolve o problema de "salvou mas não apareceu"
CREATE POLICY "Universal Access" ON vehicles FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Universal Access" ON daily_logs FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Universal Access" ON gas_stations FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Universal Access" ON refueling_logs FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Universal Access" ON requisitions FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Universal Access" ON user_vehicles FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Universal Access" ON user_roles FOR ALL USING (true) WITH CHECK (true);
```

### Pequena correção no código React

Para garantir que, ao carregar os dados, eles venham ordenados do mais recente para o mais antigo (evitando que o registro novo fique escondido na última página ou no final da lista), atualizei o arquivo `services/storage.ts`.

