                                            <td className="px-4 py-3 text-right text-lg text-blue-900">
                                                {formatCurrency(cartItems.reduce((acc, curr) => acc + curr.totalCost, 0))}
                                            </td>
                                            <td></td>
                                        </tr>
                                    </tfoot>
                                </table>
                            </div>
