                    <div className="mb-6 flex items-center p-3 bg-blue-50 border border-blue-200 rounded-lg">
                        <label className="relative inline-flex items-center cursor-pointer">
                        <input type="checkbox" className="sr-only peer" checked={isExternal} onChange={(e) => { setIsExternal(e.target.checked); setRefuelingHeader({ ...refuelingHeader, vehicleId: '' }); }} />
                        <div className="w-11 h-6 bg-gray-300 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-blue-300 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-blue-600"></div>
                        <span className="ml-3 text-sm font-bold text-slate-700 flex items-center gap-2">
                            <Fuel size={16} />
                            Abastecimento de Equipamento Externo / Não Cadastrado
                        </span>
                        </label>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8 pb-6 border-b border-slate-100">
                        <div className="col-span-full mb-2">
                            <span className="text-[10px] font-black text-blue-900 uppercase tracking-widest">Informações Gerais do Abastecimento</span>
                        </div>
                        <div>
                            <label className="block text-xs font-bold uppercase text-slate-500 mb-1">Data</label>
                            <input type="date" required value={refuelingHeader.date} onChange={e => setRefuelingHeader({...refuelingHeader, date: e.target.value})} className={inputClass} />
                        </div>
                        <div>
                            <label className="block text-xs font-bold uppercase text-slate-500 mb-1">Hora</label>
                            <div className="relative">
                                <input type="time" required value={refuelingHeader.time} onChange={e => setRefuelingHeader({...refuelingHeader, time: e.target.value})} className={inputClass} />
                                <Clock size={16} className="absolute right-3 top-3 text-slate-400 pointer-events-none" />
                            </div>
                        </div>

                        {isExternal ? (
                            <>
                                <div>
                                    <label className="block text-xs font-bold uppercase text-slate-500 mb-1">Identificação</label>
                                    <select required value={externalData.identifier} onChange={e => setExternalData({...externalData, identifier: e.target.value})} className={`${inputClass} font-bold border-blue-300 bg-blue-50`}>
                                        <option value="">Selecione o tipo...</option>
                                        {EXTERNAL_EQUIPMENT_TYPES.map(type => (<option key={type} value={type}>{type}</option>))}
                                    </select>
                                </div>
                                <div>
                                    <label className="block text-xs font-bold uppercase text-slate-500 mb-1">Contrato</label>
                                    <select required value={externalData.contract} onChange={e => setExternalData({...externalData, contract: e.target.value})} className={inputClass}>
                                        <option value="">Selecione...</option>
                                        {Object.values(ContractType).map(c => (<option key={c} value={c}>{c}</option>))}
                                    </select>
                                </div>
                                <div>
                                    <label className="block text-xs font-bold uppercase text-slate-500 mb-1">Município</label>
                                    <input type="text" required value={externalData.municipality} onChange={e => setExternalData({...externalData, municipality: e.target.value.toUpperCase()})} className={inputClass} />
                                </div>
                                <div>
                                    <label className="block text-xs font-bold uppercase text-slate-500 mb-1">Descrição / Obs.</label>
                                    <input type="text" placeholder="Detalhes (Opcional)" value={externalData.description} onChange={e => setExternalData({...externalData, description: e.target.value.toUpperCase()})} className={inputClass} />
                                </div>
                            </>
                        ) : (
                            <div className="lg:col-span-2 relative">
                                <SelectWithSearch 
                                    label="VEÍCULO CADASTRADO"
                                    options={vehicleOptions}
                                    value={refuelingHeader.vehicleId || ''}
                                    onChange={handleVehicleChange}
                                    required
                                    placeholder="Selecione ou digite..."
                                />
                            </div>
                        )}

                        <div>
                            <label className="block text-xs font-bold uppercase text-slate-500 mb-1">Equipe</label>
                            <select value={refuelingHeader.foremanSnapshot || ''} onChange={e => setRefuelingHeader({...refuelingHeader, foremanSnapshot: e.target.value})} className={inputClass}>
                                <option value="">Selecione...</option>
                                {uniqueForemen.map(f => (<option key={f} value={f}>{f}</option>))}
                            </select>
                        </div>

                        <div className="relative">
                            <SelectWithSearch 
                                label="POSTO"
                                options={stationSelectOptions}
                                value={refuelingHeader.gasStationId || ''}
                                onChange={(val) => setRefuelingHeader({...refuelingHeader, gasStationId: val})}
                                required
                                placeholder="Selecione o posto..."
                            />
                        </div>

                        <div>
                            <label className="block text-xs font-bold uppercase text-slate-500 mb-1">Nota Fiscal</label>
                            <input type="text" placeholder="Nº da Nota" value={refuelingHeader.invoiceNumber || ''} onChange={e => setRefuelingHeader({...refuelingHeader, invoiceNumber: e.target.value.toUpperCase()})} className={inputClass} />
                        </div>
                        <div>
                            <label className="block text-xs font-bold uppercase text-slate-500 mb-1">Requisição</label>
                            <input type="text" placeholder="Nº da Requisição" value={refuelingHeader.requisitionNumber || ''} onChange={e => setRefuelingHeader({...refuelingHeader, requisitionNumber: e.target.value.toUpperCase()})} className={inputClass} />
                        </div>
                    </div>

                    {/* ADD ITEM SECTION */}
                    <div className="bg-slate-50 p-4 rounded-xl border border-slate-200 mb-8">
                        <div className="flex items-center gap-2 mb-4 text-blue-700 font-bold">
                            <Package size={18} />
                            Adicionar Itens ao Abastecimento
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
                            <div className="md:col-span-1">
                                <label className="block text-[10px] font-bold uppercase text-slate-500 mb-1">Item / Produto</label>
                                <select value={currentItem.fuelType || ''} onChange={e => setCurrentItem({...currentItem, fuelType: e.target.value as FuelType})} className={selectClass}>
                                    <option value="">Selecione...</option>
                                    <optgroup label="COMBUSTÍVEIS">
                                        {FUEL_TYPES_LIST.map(f => (<option key={f} value={f}>{f}</option>))}
                                    </optgroup>
                                    <optgroup label="INSUMOS">
                                        {SUPPLY_TYPES_LIST.map(f => (<option key={f} value={f}>{f}</option>))}
                                    </optgroup>
                                </select>
                            </div>
                            <div>
                                <label className="block text-[10px] font-bold uppercase text-slate-500 mb-1">Quantidade</label>
                                <input type="number" step="0.01" value={currentItem.liters || ''} onChange={e => setCurrentItem({...currentItem, liters: Number(e.target.value)})} className={inputClass} />
                            </div>
                            <div>
                                <label className="block text-[10px] font-bold uppercase text-slate-500 mb-1">Valor Total (R$)</label>
                                <input type="number" step="0.01" value={currentItem.totalCost || ''} onChange={e => setCurrentItem({...currentItem, totalCost: Number(e.target.value)})} className={inputClass} />
                            </div>
                            <button 
                                type="button" 
                                onClick={handleAddItemToCart}
                                className="bg-slate-800 text-white px-4 py-2.5 rounded-lg font-bold hover:bg-slate-900 transition-colors flex items-center justify-center gap-2 shadow-sm h-[44px]"
                            >
                                <Plus size={18} /> Incluir Item
                            </button>
                        </div>
                    </div>

                    {/* CART LIST */}
                    <div className="mb-8">
                        <div className="flex items-center gap-2 mb-3 text-slate-700 font-bold">
                            <ShoppingCart size={18} />
                            Lista de Itens Lançados ({cartItems.length})
                        </div>
                        {cartItems.length === 0 ? (
                            <div className="text-center p-6 border-2 border-dashed border-slate-200 rounded-lg text-slate-400 bg-slate-50/50">
                                Nenhum item adicionado ainda.
                            </div>
                        ) : (
                            <div className="border border-slate-200 rounded-xl overflow-hidden shadow-sm">
                                <table className="w-full text-sm">
                                    <thead className="bg-slate-100 text-slate-600 font-bold uppercase text-[10px]">
                                        <tr>
                                            <th className="px-4 py-2 text-left">Item</th>
                                            <th className="px-4 py-2 text-center w-32">Quantidade</th>
                                            <th className="px-4 py-2 text-right w-40">Valor Total</th>
                                            <th className="px-4 py-2 text-center w-16">Ações</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-slate-100 bg-white">
                                        {cartItems.map((item, idx) => (
                                            <tr key={item.id} className="hover:bg-slate-50">
                                                <td className="px-4 py-3">
                                                    <span className={`text-xs font-bold px-2 py-0.5 rounded border ${getFuelColor(item.fuelType)}`}>
                                                        {item.fuelType}
                                                    </span>
                                                </td>
                                                <td className="px-4 py-3 text-center">
                                                    <input 
                                                        type="number" 
                                                        step="0.01" 
                                                        value={item.liters} 
                                                        onChange={(e) => handleUpdateCartItem(item.id, 'liters', e.target.value)}
                                                        className="w-full text-center font-mono font-bold text-slate-700 bg-slate-50 border border-slate-200 rounded p-1 focus:ring-1 focus:ring-blue-500 outline-none"
                                                    />
                                                </td>
                                                <td className="px-4 py-3 text-right">
                                                    <div className="relative">
                                                        <span className="absolute left-1 top-1.5 text-[10px] text-slate-400">R$</span>
                                                        <input 
                                                            type="number" 
                                                            step="0.01" 
                                                            value={item.totalCost} 
                                                            onChange={(e) => handleUpdateCartItem(item.id, 'totalCost', e.target.value)}
                                                            className="w-full text-right font-mono font-bold text-green-700 bg-slate-50 border border-slate-200 rounded p-1 pl-6 focus:ring-1 focus:ring-blue-500 outline-none"
                                                        />
                                                    </div>
                                                </td>
                                                <td className="px-4 py-3 text-center">
                                                    <button onClick={() => handleRemoveItemFromCart(item.id)} className="text-red-500 hover:bg-red-50 p-1.5 rounded transition-colors"><Trash2 size={16} /></button>
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                    <tfoot className="bg-slate-50 font-bold text-slate-800 border-t border-slate-200">
                                        <tr>
                                            <td className="px-4 py-3 text-right" colSpan={2}>Soma Total:</td>
                                            <td className="px-4 py-3 text-right text-lg text-blue-900">
                                                {formatCurrency(cartItems.reduce((acc, curr) => acc + Number(curr.totalCost || 0), 0))}
                                            </td>
                                            <td></td>
                                        </tr>
                                    </tfoot>
                                </table>
                            </div>
                        )}
                    </div>

                    <div className="flex justify-end gap-3 pt-6 border-t border-slate-100">
                        <button type="button" onClick={resetForms} className="px-6 py-2.5 text-slate-600 hover:bg-slate-100 rounded-lg font-medium transition-colors">Cancelar</button>
                        <button 
                            onClick={handleSaveRefueling} 
                            disabled={loading || cartItems.length === 0} 
                            className="bg-blue-800 text-white px-8 py-2.5 rounded-lg font-bold hover:bg-blue-900 transition-all flex items-center gap-2 shadow-lg disabled:opacity-50 transform active:scale-95"
                        >
                            {loading ? <Loader2 className="animate-spin"/> : <Save size={18} />}
                            Salvar Abastecimento Completo
                        </button>
                    </div>
                </div>
