                    <p className="text-lg md:text-xl font-bold text-blue-800">{totalLitersCalculated.toFixed(2)} L</p>
                </div>
                <div className="bg-green-50 p-2 md:p-3 rounded-lg shadow-sm border border-green-100">
                    <p className="text-[10px] md:text-xs font-bold text-green-600 uppercase">Total Valor (Geral)</p>
                    <p className="text-lg md:text-xl font-bold text-blue-800">{formatCurrency(totalCostCalculated)}</p>
                </div>
