                                <label className="block text-xs font-bold text-slate-500 mb-1">Data Início</label>
                                <div className="relative">
                                    <input type="date" className={selectClass} value={filterDateStart} onChange={(e) => setFilterDateStart(e.target.value)} />
                                    <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none"><Calendar size={16} className="text-slate-400" /></div>
                                </div>
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-slate-500 mb-1">Data Final</label>
                                <div className="relative">
                                    <input type="date" className={selectClass} value={filterDateEnd} onChange={(e) => setFilterDateEnd(e.target.value)} />
                                    <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none"><Calendar size={16} className="text-slate-400" /></div>
                                </div>
                            </div>

                            <div className="relative"><MultiSelect label="Placa / Identificação" options={plateOptions} selected={filterPlate} onChange={setFilterPlate} placeholder="Todas" /></div>
                            <div className="relative"><MultiSelect label="Equipe" options={foremanOptions} selected={filterForeman} onChange={setFilterForeman} placeholder="Todos" /></div>
                            <div className="relative"><MultiSelect label="Posto" options={stationOptions} selected={filterStation} onChange={setFilterStation} placeholder="Todos" /></div>
                            <div className="relative"><MultiSelect label="Contrato" options={contractOptions} selected={filterContract} onChange={setFilterContract} placeholder="Todos" /></div>
                            <div className="relative"><MultiSelect label="Município" options={municipalityOptions} selected={filterMunicipality} onChange={setFilterMunicipality} placeholder="Todos" /></div>
                            <div className="relative"><MultiSelect label="Combustível" options={fuelOptions} selected={filterFuel} onChange={setFilterFuel} placeholder="Todos" /></div>
                        </div>
                    </div>
                )}
            </div>

            {showForm && !isReadOnly && (
                <div className="bg-white rounded-xl shadow-lg border border-slate-200 p-6 animate-in fade-in slide-in-from-top-2 print:hidden">
