                            <div className="relative"><MultiSelect label="Equipe" options={foremanOptions} selected={filterForeman} onChange={setFilterForeman} placeholder="Todos" /></div>
                            <div className="relative"><MultiSelect label="Posto" options={stationOptions} selected={filterStation} onChange={setFilterStation} placeholder="Todos" /></div>
                            <div className="relative"><MultiSelect label="Contrato" options={contractOptions} selected={filterContract} onChange={setFilterContract} placeholder="Todos" /></div>
                            <div className="relative"><MultiSelect label="Município" options={municipalityOptions} selected={filterMunicipality} onChange={setFilterMunicipality} placeholder="Todos" /></div>
                            <div className="relative"><MultiSelect label="Combustível" options={fuelOptions} selected={filterFuel} onChange={setFilterFuel} placeholder="Todos" /></div>
                        </div>
                    </div>
                )}
            </div>

            {showForm && !isReadOnly && (
                <div className="bg-white rounded-xl shadow-lg border border-slate-200 p-6 animate-in fade-in slide-in-from-top-2 print:hidden">
                    <h3 className="font-bold text-lg text-slate-800 mb-4 flex items-center gap-2">
                        <Droplet className="text-blue-500" />
                        {isEditing ? 'Editar Abastecimento' : 'Registrar Novo Abastecimento'}
                    </h3>

                    <div className="mb-6 flex items-center p-3 bg-blue-50 border border-blue-200 rounded-lg">
                        <label className="relative inline-flex items-center cursor-pointer">
                        <input type="checkbox" className="sr-only peer" checked={isExternal} onChange={(e) => { setIsExternal(e.target.checked); setRefuelingHeader({ ...refuelingHeader, vehicleId: '' }); }} />
                        <div className="w-11 h-6 bg-gray-300 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-blue-300 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-blue-600"></div>
                        <span className="ml-3 text-sm font-bold text-slate-700 flex items-center gap-2">
                            <Fuel size={16} />
                            Abastecimento de Equipamento Externo / Não Cadastrado
                        </span>
                        </label>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8 pb-6 border-b border-slate-100">
