                            <label className="block text-xs font-bold uppercase text-slate-500 mb-1">Nota Fiscal</label>
                            <input type="text" placeholder="Nº da Nota" value={refuelingHeader.invoiceNumber || ''} onChange={e => setRefuelingHeader({...refuelingHeader, invoiceNumber: e.target.value.toUpperCase()})} className={inputClass} />
