                        <div>
                            <label className="block text-xs font-bold uppercase text-slate-500 mb-1">Requisição</label>
                            <input type="text" placeholder="Nº da Requisição" value={refuelingHeader.requisitionNumber || ''} onChange={e => setRefuelingHeader({...refuelingHeader, requisitionNumber: e.target.value.toUpperCase()})} className={inputClass} />
