                                <label className="block text-[10px] font-bold uppercase text-slate-500 mb-1">Valor Total (R$)</label>
                                <input type="number" step="0.01" value={currentItem.totalCost || ''} onChange={e => setCurrentItem({...currentItem, totalCost: Number(e.target.value)})} className={inputClass} />
