                                        <tr>
                                            <th className="px-4 py-2 text-left">Item</th>
                                            <th className="px-4 py-2 text-center w-32">Quantidade</th>
                                            <th className="px-4 py-2 text-right w-40">Valor Total</th>
                                            <th className="px-4 py-2 text-center w-16">Ações</th>
                                        </tr>
