    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const getCurrentTime = () => {
    const now = new Date();
    return now.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
  };

  const [refuelingHeader, setRefuelingHeader] = useState({
      date: getTodayLocal(),
      time: getCurrentTime(),
      vehicleId: '',
      gasStationId: '',
      foremanSnapshot: '',
      invoiceNumber: '',
      requisitionNumber: ''
  });

  const [cartItems, setCartItems] = useState<RefuelingCartItem[]>([]);
  const [currentItem, setCurrentItem] = useState<Partial<RefuelingCartItem>>({
      fuelType: '' as any,
      liters: 0,
      totalCost: 0
  });

  const [isExternal, setIsExternal] = useState(false);
  const [externalData, setExternalData] = useState({
    identifier: '', 
    model: '',
    contract: '',
    municipality: '',
    description: ''
  });

  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);

  useEffect(() => {
    loadData();
  }, []);

  useEffect(() => {
    setCurrentPage(1);
  }, [filterDateStart, filterDateEnd, filterPlate, filterStation, filterContract, filterMunicipality, filterFuel, filterForeman]);

  const loadData = async () => {
    setLoading(true);
    try {
      const [sData, rData, vData] = await Promise.all([
          storageService.getGasStations(),
          storageService.getRefuelings(),
          storageService.getVehicles()
      ]);

      setStations(sData);
      setRefuelings(rData);
      setVehicles(vData);

      const plates = Array.from(new Set(rData.map(r => r.plateSnapshot))).sort();
      const contracts = Array.from(new Set(rData.map(r => r.contractSnapshot))).sort();
      const cities = Array.from(new Set(rData.map(r => r.municipalitySnapshot))).sort();
      const vehicleTeams = Array.from(new Set(vData.map(v => v.foreman).filter(f => f && f.trim() !== ''))).sort();

      setUniquePlates(plates);
      setUniqueContracts(contracts);
      setUniqueMunicipalities(cities);
      setUniqueForemen(vehicleTeams);
    } catch (e) {
        console.error(e);
    } finally {
        setLoading(false);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const getFuelColor = (fuelType: string) => {
    if (fuelType === FuelType.OUTROS || fuelType.includes('DIVERSOS')) return 'bg-purple-100 text-purple-800 border-purple-200';
    switch (fuelType) {
      case FuelType.GASOLINA: return 'bg-orange-100 text-orange-800 border-orange-200'; 
      case FuelType.ETANOL: return 'bg-green-100 text-green-800 border-green-200';
      case FuelType.DIESEL: return 'bg-yellow-100 text-yellow-800 border-yellow-200';
      case FuelType.DIESEL_S10: return 'bg-slate-100 text-slate-800 border-slate-200';
      default: return 'bg-gray-100 text-gray-800 border-gray-200';
    }
  };

  const handleAddItemToCart = () => {
      if (!currentItem.fuelType) {
          alert("Selecione o item/combustível.");
          return;
      }

      const qty = Math.max(0, Number(currentItem.liters || 0));
      const cost = Math.max(0, Number(currentItem.totalCost || 0));

      if (qty <= 0 && cost <= 0) {
          alert("Informe a quantidade ou o valor.");
          return;
      }

      const newItem: RefuelingCartItem = {
          id: crypto.randomUUID(),
          fuelType: currentItem.fuelType as FuelType,
          liters: qty,
          totalCost: cost
      };

      setCartItems(prev => [...prev, newItem]);
      setCurrentItem({ fuelType: '' as any, liters: 0, totalCost: 0 });
  };

  const handleUpdateCartItem = (id: string, field: 'liters' | 'totalCost', value: string) => {
      const numValue = value === '' ? 0 : Math.max(0, Number(value));
      setCartItems(prev => prev.map(item => 
          item.id === id ? { ...item, [field]: numValue } : item
      ));
  };

  const handleRemoveItemFromCart = (id: string) => {
      setCartItems(prev => prev.filter(item => item.id !== id));
  };

  const handleSaveStation = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly) return;
    if (!currentStation.name || !currentStation.municipality) return;

    const newStation: GasStation = {
      id: currentStation.id || crypto.randomUUID(),
      name: currentStation.name.toUpperCase(),
      cnpj: currentStation.cnpj ? currentStation.cnpj.toUpperCase() : '',
      municipality: currentStation.municipality.toUpperCase(),
      phone: currentStation.phone || '',
      address: currentStation.address ? currentStation.address.toUpperCase() : ''
    };

    setLoading(true);
    try {
        await storageService.saveGasStation(newStation);
        await loadData();
        resetForms();
    } catch (err: any) {
        console.error(err);
        alert(`Erro ao salvar posto: ${err.message}`);
    } finally {
        setLoading(false);
    }
  };

  const handleEditStation = (station: GasStation) => {
    if (isReadOnly) return;
    setCurrentStation(station);
    setIsEditing(true);
    setShowForm(true);
    setActiveTab('STATIONS');
  };

  const deleteStation = async (id: string) => {
    if (isReadOnly) return;
    const hasUsage = refuelings.some(r => r.gasStationId === id);
    if(hasUsage) {
        alert("Não é possível excluir este posto pois existem abastecimentos vinculados a ele.");
        return;
    }
    setLoading(true);
    try {
        await storageService.deleteGasStation(id);
        await loadData();
        setShowDeleteModal(false);
        setItemToDelete(null);
    } catch (err: any) {
        console.error(err);
        alert(`Erro ao excluir posto: ${err.message}`);
    } finally {
        setLoading(false);
    }
  };

  const getTicketItems = (log: RefuelingLog): RefuelingItem[] => {
      if (log.items && log.items.length > 0) return log.items;
      return [{ fuelType: log.fuelType, liters: log.liters, totalCost: log.totalCost }];
  };

  const handleSaveRefueling = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly) return;

    // 1. Validação de Posto
    if (!refuelingHeader.gasStationId) {
        alert("Por favor, selecione o posto conveniado.");
        return;
    }

    // 2. Validação de Itens
    if (cartItems.length === 0) {
        alert("A lista de itens está vazia. Adicione pelo menos um produto (combustível ou insumo).");
        return;
    }

    let snapshotData = {
        plate: '',
        model: '',
        contract: '',
        municipality: '',
        foreman: refuelingHeader.foremanSnapshot || ''
    };

    let vehicleIdToSave = '';

    if (isExternal) {
        if (!externalData.identifier || !externalData.contract || !externalData.municipality) {
            alert("Para equipamentos externos, preencha Identificação, Contrato e Município.");
            return;
        }
        snapshotData.plate = externalData.identifier.toUpperCase();
        snapshotData.model = externalData.model ? externalData.model.toUpperCase() : '';
        snapshotData.contract = externalData.contract;
        snapshotData.municipality = externalData.municipality.toUpperCase();
        vehicleIdToSave = 'EXTERNAL';
    } else {
        if (!refuelingHeader.vehicleId) {
            alert("Por favor, selecione um veículo cadastrado.");
            return;
        }

        const vehicle = vehicles.find(v => v.id === refuelingHeader.vehicleId);
        if (!vehicle) {
            alert("Veículo não encontrado. Tente selecionar novamente.");
            return;
        }

        snapshotData.plate = vehicle.plate;
        snapshotData.model = vehicle.model || '';
        snapshotData.contract = vehicle.contract;
        snapshotData.municipality = vehicle.municipality;
        if (!snapshotData.foreman) snapshotData.foreman = vehicle.foreman;

        vehicleIdToSave = refuelingHeader.vehicleId;
    }

    setLoading(true);
    try {
        // --- CONSOLIDAÇÃO DOS DADOS ---
        const totalLiters = cartItems.reduce((acc, curr) => acc + Number(curr.liters || 0), 0);
        const totalCost = cartItems.reduce((acc, curr) => acc + Number(curr.totalCost || 0), 0);

        const isMultiple = cartItems.length > 1;
        const dbFuelType = isMultiple ? FuelType.OUTROS : cartItems[0].fuelType;

        // Gerar breakdown para observação (útil para auditoria)
        const itemsBreakdown = cartItems.map(i => `${i.fuelType}: ${Number(i.liters).toFixed(2)}L (R$ ${Number(i.totalCost).toFixed(2)})`).join(' | ');
        const customObs = isExternal && externalData.description ? externalData.description.toUpperCase() : '';
        const finalObs = `[ITENS: ${itemsBreakdown}] ${customObs}`.trim().substring(0, 490); // Segurança contra limite de coluna

        const newRefueling: RefuelingLog = {
            id: (isEditing && editingRecordId) ? editingRecordId : crypto.randomUUID(),
            date: refuelingHeader.date,
            vehicleId: vehicleIdToSave,
            gasStationId: refuelingHeader.gasStationId,
            fuelType: dbFuelType, 
            liters: Number(totalLiters.toFixed(2)), 
            totalCost: Number(totalCost.toFixed(2)), 
            items: cartItems.map(i => ({ fuelType: i.fuelType, liters: Number(i.liters), totalCost: Number(i.totalCost) })),
            invoiceNumber: refuelingHeader.invoiceNumber ? refuelingHeader.invoiceNumber.toUpperCase().trim() : '',
            requisitionNumber: refuelingHeader.requisitionNumber ? refuelingHeader.requisitionNumber.toUpperCase().trim() : '',
            time: refuelingHeader.time || '', // Envia vazio ou valor. Se o DB for estrito, trocar para null.

            plateSnapshot: snapshotData.plate,
            modelSnapshot: snapshotData.model,
            foremanSnapshot: snapshotData.foreman, 
            contractSnapshot: snapshotData.contract,
            municipalitySnapshot: snapshotData.municipality,
            observation: finalObs
        };

        // Persistência no Storage (Supabase)
        await storageService.saveRefueling(newRefueling);

        // Atualização de UI
        await loadData();
        resetForms();
        alert("Abastecimento registrado com sucesso!");
    } catch (err: any) {
        console.error("Erro crítico ao salvar abastecimento:", err);
        alert(`Falha ao salvar no banco de dados: ${err.message || 'Verifique sua conexão ou se todos os campos obrigatórios foram preenchidos corretamente.'}`);
    } finally {
        setLoading(false);
    }
  };

  const handleEditRefueling = (refueling: RefuelingLog) => {
    if (isReadOnly) return;

    setRefuelingHeader({
        date: refueling.date,
        time: refueling.time || '',
        vehicleId: refueling.vehicleId,
        gasStationId: refueling.gasStationId,
        foremanSnapshot: refueling.foremanSnapshot || '',
        invoiceNumber: refueling.invoiceNumber || '',
        requisitionNumber: refueling.requisitionNumber || ''
    });

    setEditingRecordId(refueling.id);

    // Carregar itens salvos
    const savedItems: RefuelingCartItem[] = (refueling.items && refueling.items.length > 0)
        ? refueling.items.map(i => ({ ...i, id: crypto.randomUUID() }))
        : [{ id: crypto.randomUUID(), fuelType: refueling.fuelType, liters: refueling.liters, totalCost: refueling.totalCost }];

    setCartItems(savedItems);

    const vehicleExists = vehicles.find(v => v.id === refueling.vehicleId);

    if (!vehicleExists || refueling.vehicleId === 'EXTERNAL') {
        setIsExternal(true);
        setExternalData({
            identifier: refueling.plateSnapshot,
            model: refueling.modelSnapshot,
            contract: refueling.contractSnapshot,
            municipality: refueling.municipalitySnapshot,
            description: refueling.observation?.split('] ')[1] || refueling.observation || ''
        });
    } else {
        setIsExternal(false);
        setExternalData({ identifier: '', model: '', contract: '', municipality: '', description: '' });
    }

    setIsEditing(true);
    setShowForm(true);
    setActiveTab('REFUELING');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const deleteRefueling = async (id: string) => {
    if (isReadOnly) return;
    setLoading(true);
    try {
        await storageService.deleteRefueling(id);
        await loadData();
        setShowDeleteModal(false);
        setItemToDelete(null);
    } catch (err: any) {
        console.error(err);
        alert(`Erro ao excluir: ${err.message}`);
    } finally {
        setLoading(false);
    }
  };

  const resetForms = () => {
    setShowForm(false);
    setIsEditing(false);
    setEditingRecordId(null);
    setCurrentStation({});
    setRefuelingHeader({
      date: getTodayLocal(),
      time: getCurrentTime(),
      vehicleId: '',
      gasStationId: '',
      foremanSnapshot: '',
      invoiceNumber: '',
      requisitionNumber: ''
    });
    setCartItems([]);
    setCurrentItem({ fuelType: '' as any, liters: 0, totalCost: 0 });
    setIsExternal(false);
    setExternalData({ identifier: '', model: '', contract: '', municipality: '', description: '' });
  };

  const resetFilters = () => {
    setFilterDateStart('');
    setFilterDateEnd('');
    setFilterPlate([]);
    setFilterStation([]);
    setFilterContract([]);
    setFilterMunicipality([]);
    setFilterFuel([]);
    setFilterForeman([]);
  };

  const confirmDelete = (id: string) => {
    if (isReadOnly) return;
    setItemToDelete(id);
    setShowDeleteModal(true);
  };

  const executeDelete = () => {
    if (itemToDelete) {
      if (activeTab === 'STATIONS') {
        deleteStation(itemToDelete);
      } else {
        deleteRefueling(itemToDelete);
      }
    }
  };

  const handleVehicleChange = (vehicleId: string) => {
    const vehicle = vehicles.find(v => v.id === vehicleId);
    if (vehicle) {
        setRefuelingHeader(prev => ({
            ...prev,
            vehicleId: vehicleId,
            foremanSnapshot: vehicle.foreman || ''
        }));
    } else {
        setRefuelingHeader(prev => ({ ...prev, vehicleId: vehicleId, foremanSnapshot: '' }));
    }
  };

  const formatDate = (dateStr: string) => {
    if (!dateStr) return '-';
    const [y, m, d] = dateStr.split('-');
    return `${d}/${m}/${y}`;
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val || 0);
  };

  const filteredRefuelings = refuelings.filter(r => {
      const rDate = new Date(r.date).getTime();
      const start = filterDateStart ? new Date(filterDateStart).getTime() : null;
      const end = filterDateEnd ? new Date(filterDateEnd).getTime() : null;
      const matchesDate = (!start || rDate >= start) && (!end || rDate <= end);

      const matchesPlate = filterPlate.length === 0 || filterPlate.includes(r.plateSnapshot);
      const matchesStation = filterStation.length === 0 || filterStation.includes(r.gasStationId);
      const matchesContract = filterContract.length === 0 || filterContract.includes(r.contractSnapshot);
      const matchesCity = filterMunicipality.length === 0 || filterMunicipality.includes(r.municipalitySnapshot);

      const matchesFuel = filterFuel.length === 0 || 
                         filterFuel.includes(r.fuelType) || 
                         (r.items && r.items.some(i => filterFuel.includes(i.fuelType)));

      const matchesForeman = filterForeman.length === 0 || (r.foremanSnapshot && filterForeman.includes(r.foremanSnapshot));

      return matchesDate && matchesPlate && matchesStation && matchesContract && matchesCity && matchesFuel && matchesForeman;
  }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  const totalPages = Math.ceil(filteredRefuelings.length / ITEMS_PER_PAGE);
  const paginatedRefuelings = filteredRefuelings.slice(
    (currentPage - 1) * ITEMS_PER_PAGE,
    currentPage * ITEMS_PER_PAGE
  );

  const totalLitersCalculated = filteredRefuelings.reduce((acc, curr) => acc + (curr.liters || 0), 0);
  const totalCostCalculated = filteredRefuelings.reduce((acc, curr) => acc + (curr.totalCost || 0), 0);

  const activeFiltersCount = [
    filterDateStart, filterDateEnd, 
    filterPlate.length, filterStation.length, 
    filterContract.length, filterMunicipality.length, filterFuel.length, filterForeman.length
  ].filter(Boolean).reduce((a, b) => a + (typeof b === 'number' ? b : 1), 0);

  const inputClass = "w-full rounded-lg border border-slate-300 bg-slate-50 p-2.5 text-slate-800 focus:border-blue-600 focus:bg-white focus:ring-2 focus:ring-blue-100 outline-none transition-all";
  const selectClass = "w-full rounded-lg border border-slate-300 bg-white p-2 text-slate-700 focus:border-blue-600 focus:ring-2 focus:ring-blue-100 outline-none h-[42px] shadow-sm";

  const plateOptions: MultiSelectOption[] = uniquePlates.map(p => ({ value: p, label: p }));
  const stationOptions: MultiSelectOption[] = stations.map(s => ({ value: s.id, label: s.name }));
  const contractOptions: MultiSelectOption[] = uniqueContracts.map(c => ({ value: c, label: c }));
  const municipalityOptions: MultiSelectOption[] = uniqueMunicipalities.map(m => ({ value: m, label: m }));
  const foremanOptions: MultiSelectOption[] = uniqueForemen.map(f => ({ value: f, label: f }));
  const fuelOptions: MultiSelectOption[] = Object.values(FuelType).map(f => ({ value: f, label: f }));

  const vehicleOptions = vehicles.map(v => ({
      value: v.id,
      label: `${v.plate} - ${v.driverName} (${v.type})`
  }));

  const stationSelectOptions = stations.map(s => ({
      value: s.id,
      label: `${s.name} - ${s.municipality}`
  }));

  if (loading && activeTab === 'REFUELING' && refuelings.length === 0) {
      return <div className="flex justify-center items-center h-64"><Loader2 className="animate-spin text-blue-600" size={48} /></div>;
  }

  return (
    <div className="space-y-6">

      <PrintHeader 
        title="Relatório de Abastecimentos"
        subtitle="Consolidado de Consumo"
        details={
            <>
                <span>Registros: {filteredRefuelings.length}</span>
                <span>Total Litros: {totalLitersCalculated.toFixed(2)} L</span>
                <span>Total Valor: {formatCurrency(totalCostCalculated)}</span>
            </>
        }
      />

       <div className="print:hidden">
        <PasswordModal
            isOpen={showDeleteModal}
            onClose={() => setShowDeleteModal(false)}
            onConfirm={executeDelete}
            title={activeTab === 'STATIONS' ? "Excluir Posto" : "Excluir Abastecimento"}
        />
      </div>

      {selectedTicket && (
        <div className="fixed inset-0 bg-black/70 backdrop-blur-sm z-[999] flex items-center justify-center p-4 print:hidden">
            <div className="bg-white rounded-xl shadow-2xl max-w-sm w-full overflow-hidden animate-in zoom-in-95 duration-200">
                <div className="bg-slate-900 p-4 text-white flex justify-between items-center">
                    <h3 className="font-bold flex items-center gap-2"><Receipt size={20} /> Bilhete de Lançamento</h3>
                    <button onClick={() => setSelectedTicket(null)} className="p-1 hover:bg-slate-800 rounded transition-colors"><X size={20}/></button>
                </div>

                <div className="p-6 bg-white font-mono text-xs text-slate-700 space-y-4" id="refueling-ticket-print">
                    <div className="flex flex-col items-center border-b border-dashed border-slate-300 pb-4">
                        <ParisLogo variant="dark" size="normal" />
                        <h4 className="mt-4 font-black text-sm text-slate-900">COMPROVANTE DE ABASTECIMENTO</h4>
                        <p className="mt-1">PARIS ENGENHARIA LTDA</p>
                    </div>

                    <div className="space-y-1.5 border-b border-dashed border-slate-300 pb-4">
                        <div className="flex justify-between"><span>DATA:</span><span className="font-bold">{formatDate(selectedTicket.date)}</span></div>
                        <div className="flex justify-between"><span>HORA:</span><span className="font-bold">{selectedTicket.time || '--:--'}</span></div>
                        <div className="flex justify-between"><span>VEÍCULO:</span><span className="font-bold">{selectedTicket.plateSnapshot}</span></div>
                        <div className="flex justify-between"><span>EQUIPE:</span><span className="font-bold truncate ml-4">{selectedTicket.foremanSnapshot || '-'}</span></div>
                        <div className="flex justify-between"><span>CONTRATO:</span><span className="font-bold">{selectedTicket.contractSnapshot}</span></div>
                    </div>

                    <div className="space-y-1.5 border-b border-dashed border-slate-300 pb-4">
                        <div className="text-[10px] font-bold text-slate-400 mb-1">LOCAL DE ABASTECIMENTO</div>
                        <p className="font-bold text-slate-900">{stations.find(s => s.id === selectedTicket?.gasStationId)?.name || 'POSTO CONVENIADO'}</p>
                        <p className="text-[10px]">{selectedTicket.municipalitySnapshot}</p>
                        {selectedTicket.invoiceNumber && <div className="flex justify-between mt-2"><span>Nº NOTA:</span><span className="font-bold">{selectedTicket.invoiceNumber}</span></div>}
                        {selectedTicket.requisitionNumber && <div className="flex justify-between"><span>Nº REQUISIÇÃO:</span><span className="font-bold">{selectedTicket.requisitionNumber}</span></div>}
                    </div>

                    <div className="space-y-2">
                        <div className="flex justify-between font-bold text-slate-900 border-b border-slate-100 pb-1">
                            <span>ITEM / QTD</span>
                            <span>SUBTOTAL</span>
                        </div>
                        {getTicketItems(selectedTicket).map((it, idx) => (
                            <div key={idx} className="flex justify-between py-0.5">
                                <span className="truncate mr-4">{it.fuelType} x {it.liters.toFixed(2)}</span>
                                <span className="font-bold">{formatCurrency(it.totalCost)}</span>
                            </div>
                        ))}
                    </div>

                    <div className="pt-4 border-t-2 border-slate-900 mt-4">
                        <div className="flex justify-between items-baseline">
                            <span className="font-black text-sm">TOTAL GERAL</span>
                            <span className="font-black text-lg text-slate-900">
                                {formatCurrency(selectedTicket.totalCost)}
                            </span>
                        </div>
                    </div>

                    <div className="pt-8 space-y-8 text-center opacity-40">
                        <div className="border-t border-slate-400 pt-1">Assinatura do Responsável</div>
                    </div>
                </div>

                <div className="p-4 bg-slate-50 border-t flex flex-col gap-2">
                    <button 
                        onClick={() => window.print()}
                        className="bg-slate-900 text-white w-full py-3 rounded-lg font-bold flex items-center justify-center gap-2 shadow-lg hover:bg-slate-800 transition-colors"
                    >
                        <Printer size={18} /> Imprimir Bilhete
                    </button>
                    <button 
                        onClick={() => setSelectedTicket(null)}
                        className="bg-white border border-slate-300 text-slate-600 w-full py-2 rounded-lg font-bold text-xs"
                    >
                        FECHAR
                    </button>
                </div>
            </div>
        </div>
      )}

      <div className="flex flex-col md:flex-row md:items-start justify-between gap-4 print:hidden">
        <div>
          <h1 className="text-3xl font-bold text-slate-900 flex items-center gap-3">
            <Fuel className="text-blue-600" size={32} />
            Abastecimento
          </h1>
          <p className="text-slate-500">Controle consolidado de combustível e insumos.</p>
        </div>

        <div className="flex flex-col gap-2 w-full md:w-auto">
             <button
                onClick={handlePrint}
                className="bg-white border border-slate-300 text-slate-700 hover:bg-slate-50 px-4 py-2 rounded-lg font-medium flex items-center justify-center gap-2 shadow-sm transition-colors w-full md:w-auto"
            >
                <Printer size={20} />
                Imprimir Relatório
            </button>
        </div>
      </div>

      <div className="flex flex-col sm:flex-row items-start sm:items-center gap-4 print:hidden bg-slate-50 p-2 rounded-xl shadow-sm border border-slate-100">
        <div className="flex space-x-1 bg-slate-200 p-1 rounded-lg w-full sm:w-auto">
            <button
            onClick={() => { setActiveTab('REFUELING'); resetForms(); }}
            className={`flex-1 sm:flex-none px-6 py-2 rounded-md text-sm font-bold transition-all flex items-center justify-center gap-2 ${
                activeTab === 'REFUELING' 
                ? 'bg-white text-slate-900 shadow-sm' 
                : 'text-slate-600 hover:text-slate-900'
            }`}
            >
            <ClipboardList size={16} />
            Registros
            </button>
            <button
            onClick={() => { setActiveTab('STATIONS'); resetForms(); }}
            className={`flex-1 sm:flex-none px-6 py-2 rounded-md text-sm font-bold transition-all flex items-center justify-center gap-2 ${
                activeTab === 'STATIONS' 
                ? 'bg-white text-slate-900 shadow-sm' 
                : 'text-slate-600 hover:text-slate-900'
            }`}
            >
            <Fuel size={16} />
            Postos
            </button>
        </div>

        {!isReadOnly && (
          <div className="w-full sm:w-auto">
            <button
                onClick={() => { resetForms(); setShowForm(!showForm); }}
                className={`${showForm ? 'bg-slate-600 hover:bg-slate-700' : 'bg-blue-600 hover:bg-blue-700'} text-white px-6 py-2 rounded-lg font-bold flex items-center justify-center gap-2 shadow transition-colors w-full sm:w-auto whitespace-nowrap h-[40px]`}
            >
                {showForm ? <X size={18} /> : <Plus size={18} />}
                {showForm ? 'Cancelar' : activeTab === 'REFUELING' ? 'Novo Abastecimento' : 'Novo Posto'}
            </button>
        </div>
        )}
      </div>

      {activeTab === 'REFUELING' && (
        <div className="space-y-6">
            <div className="bg-white rounded-xl border border-slate-200 shadow-sm print:hidden relative z-40">
                <div onClick={() => setShowFilters(!showFilters)} className="p-4 bg-white flex items-center justify-between cursor-pointer hover:bg-slate-50 transition-colors rounded-xl">
                    <div className="flex items-center gap-2 text-slate-800 font-bold">
                        <Filter size={20} className="text-blue-600" />
                        Filtros Avançados
                        {activeFiltersCount > 0 && <span className="bg-blue-100 text-blue-700 text-xs px-2 py-0.5 rounded-full ml-2">{activeFiltersCount} ativos</span>}
                    </div>
                    <div className="flex items-center gap-2">
                         {activeFiltersCount > 0 && <button onClick={(e) => { e.stopPropagation(); resetFilters(); }} className="text-xs text-red-600 hover:bg-red-50 px-3 py-1 rounded-full font-medium flex items-center gap-1 transition-colors mr-2"><X size={14} /> Limpar</button>}
                        {showFilters ? <ChevronUp size={20} className="text-slate-400"/> : <ChevronDown size={20} className="text-slate-400"/>}
                    </div>
                </div>

                {showFilters && (
                    <div className="p-5 border-t border-slate-100 bg-slate-50/50 animate-in slide-in-from-top-5 duration-200 rounded-b-xl overflow-visible">
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                            <div><label className="block text-xs font-bold text-slate-500 mb-1">Data Início</label><input type="date" className={selectClass} value={filterDateStart} onChange={(e) => setFilterDateStart(e.target.value)} /></div>
                            <div><label className="block text-xs font-bold text-slate-500 mb-1">Data Final</label><input type="date" className={selectClass} value={filterDateEnd} onChange={(e) => setFilterDateEnd(e.target.value)} /></div>
                            <div className="relative z-10"><MultiSelect label="Placa" options={plateOptions} selected={filterPlate} onChange={setFilterPlate} placeholder="Todas" /></div>
                            <div className="relative z-10"><MultiSelect label="Equipe" options={foremanOptions} selected={filterForeman} onChange={setFilterForeman} placeholder="Todos" /></div>
                            <div className="relative z-10"><MultiSelect label="Posto" options={stationOptions} selected={filterStation} onChange={setFilterStation} placeholder="Todos" /></div>
                            <div className="relative z-10"><MultiSelect label="Contrato" options={contractOptions} selected={filterContract} onChange={setFilterContract} placeholder="Todos" /></div>
                            <div className="relative z-10"><MultiSelect label="Município" options={municipalityOptions} selected={filterMunicipality} onChange={setFilterMunicipality} placeholder="Todos" /></div>
                            <div className="relative z-10"><MultiSelect label="Combustível" options={fuelOptions} selected={filterFuel} onChange={setFilterFuel} placeholder="Todos" /></div>
                        </div>
                    </div>
                )}
            </div>

            {showForm && !isReadOnly && (
                <div className="bg-white rounded-xl shadow-lg border border-slate-200 p-6 animate-in fade-in slide-in-from-top-2 print:hidden">
                    <h3 className="font-bold text-lg text-slate-800 mb-4 flex items-center gap-2"><Droplet className="text-blue-500" />{isEditing ? 'Editar Abastecimento' : 'Registrar Novo Abastecimento'}</h3>

                    <div className="mb-6 flex items-center p-3 bg-blue-50 border border-blue-200 rounded-lg">
                        <label className="relative inline-flex items-center cursor-pointer">
                        <input type="checkbox" className="sr-only peer" checked={isExternal} onChange={(e) => { setIsExternal(e.target.checked); setRefuelingHeader({ ...refuelingHeader, vehicleId: '' }); }} />
                        <div className="w-11 h-6 bg-gray-300 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-blue-300 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-blue-600"></div>
                        <span className="ml-3 text-sm font-bold text-slate-700 flex items-center gap-2"><Fuel size={16} />Equipamento Externo / Não Cadastrado</span>
                        </label>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8 pb-6 border-b border-slate-100">
                        <div className="col-span-full mb-2"><span className="text-[10px] font-black text-blue-900 uppercase tracking-widest">Informações Gerais do Registro</span></div>
                        <div><label className="block text-xs font-bold uppercase text-slate-500 mb-1">Data</label><input type="date" required value={refuelingHeader.date} onChange={e => setRefuelingHeader({...refuelingHeader, date: e.target.value})} className={inputClass} /></div>
                        <div><label className="block text-xs font-bold uppercase text-slate-500 mb-1">Hora</label><input type="time" required value={refuelingHeader.time} onChange={e => setRefuelingHeader({...refuelingHeader, time: e.target.value})} className={inputClass} /></div>
                        {isExternal ? (
                            <>
                                <div><label className="block text-xs font-bold uppercase text-slate-500 mb-1">Identificação</label><select required value={externalData.identifier} onChange={e => setExternalData({...externalData, identifier: e.target.value})} className={`${inputClass} font-bold border-blue-300`}>{EXTERNAL_EQUIPMENT_TYPES.map(type => (<option key={type} value={type}>{type}</option>))}</select></div>
                                <div><label className="block text-xs font-bold uppercase text-slate-500 mb-1">Contrato</label><select required value={externalData.contract} onChange={e => setExternalData({...externalData, contract: e.target.value})} className={inputClass}><option value="">Selecione...</option>{Object.values(ContractType).map(c => (<option key={c} value={c}>{c}</option>))}</select></div>
                            </>
                        ) : (
                            <div className="lg:col-span-2 relative"><SelectWithSearch label="Veículo Cadastrado" options={vehicleOptions} value={refuelingHeader.vehicleId || ''} onChange={handleVehicleChange} required placeholder="Selecione ou digite..." /></div>
                        )}
                        <div className="relative"><SelectWithSearch label="Posto" options={stationSelectOptions} value={refuelingHeader.gasStationId || ''} onChange={(val) => setRefuelingHeader({...refuelingHeader, gasStationId: val})} required placeholder="Selecione o posto..." /></div>
                        <div><label className="block text-xs font-bold uppercase text-slate-500 mb-1">Equipe</label><select value={refuelingHeader.foremanSnapshot || ''} onChange={e => setRefuelingHeader({...refuelingHeader, foremanSnapshot: e.target.value})} className={inputClass}><option value="">Selecione...</option>{uniqueForemen.map(f => (<option key={f} value={f}>{f}</option>))}</select></div>
                        <div><label className="block text-xs font-bold uppercase text-slate-500 mb-1">Nota Fiscal</label><input type="text" placeholder="Nº da Nota" value={refuelingHeader.invoiceNumber || ''} onChange={e => setRefuelingHeader({...refuelingHeader, invoiceNumber: e.target.value.toUpperCase()})} className={inputClass} /></div>
                        <div><label className="block text-xs font-bold uppercase text-slate-500 mb-1">Requisição</label><input type="text" placeholder="Nº da Requisição" value={refuelingHeader.requisitionNumber || ''} onChange={e => setRefuelingHeader({...refuelingHeader, requisitionNumber: e.target.value.toUpperCase()})} className={inputClass} /></div>
                    </div>

                    <div className="bg-slate-50 p-4 rounded-xl border border-slate-200 mb-8">
                        <div className="flex items-center gap-2 mb-4 text-blue-700 font-bold"><Package size={18} />Adicionar Itens ao Carrinho</div>
                        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
                            <div className="md:col-span-1"><label className="block text-[10px] font-bold uppercase text-slate-500 mb-1">Produto / Insumo</label><select value={currentItem.fuelType || ''} onChange={e => setCurrentItem({...currentItem, fuelType: e.target.value as FuelType})} className={selectClass}><option value="">Selecione...</option><optgroup label="COMBUSTÍVEIS">{FUEL_TYPES_LIST.map(f => (<option key={f} value={f}>{f}</option>))}</optgroup><optgroup label="INSUMOS">{SUPPLY_TYPES_LIST.map(f => (<option key={f} value={f}>{f}</option>))}</optgroup></select></div>
                            <div><label className="block text-[10px] font-bold uppercase text-slate-500 mb-1">Quantidade</label><input type="number" step="0.01" value={currentItem.liters || ''} onChange={e => setCurrentItem({...currentItem, liters: Number(e.target.value)})} className={inputClass} /></div>
                            <div><label className="block text-[10px] font-bold uppercase text-slate-500 mb-1">Valor Total (R$)</label><input type="number" step="0.01" value={currentItem.totalCost || ''} onChange={e => setCurrentItem({...currentItem, totalCost: Number(e.target.value)})} className={inputClass} /></div>
                            <button type="button" onClick={handleAddItemToCart} className="bg-slate-800 text-white px-4 py-2.5 rounded-lg font-bold hover:bg-slate-900 transition-colors flex items-center justify-center gap-2 shadow-sm h-[44px]"><Plus size={18} /> Incluir Item</button>
                        </div>
                    </div>

                    <div className="mb-8">
                        <div className="flex items-center gap-2 mb-3 text-slate-700 font-bold"><ShoppingCart size={18} />Lista de Itens Lançados ({cartItems.length})</div>
                        {cartItems.length === 0 ? (
                            <div className="text-center p-6 border-2 border-dashed border-slate-200 rounded-lg text-slate-400 bg-slate-50/50">Nenhum item adicionado à lista.</div>
                        ) : (
                            <div className="border border-slate-200 rounded-xl overflow-hidden shadow-sm">
                                <table className="w-full text-sm">
                                    <thead className="bg-slate-100 text-slate-600 font-bold uppercase text-[10px]"><tr><th className="px-4 py-2 text-left">Item</th><th className="px-4 py-2 text-center">Quantidade</th><th className="px-4 py-2 text-right">Valor Total</th><th className="px-4 py-2 text-center w-16">Ações</th></tr></thead>
                                    <tbody className="divide-y divide-slate-100 bg-white">
                                        {cartItems.map((item) => (
                                            <tr key={item.id} className="hover:bg-slate-50">
                                                <td className="px-4 py-3"><span className={`text-xs font-bold px-2 py-0.5 rounded border ${getFuelColor(item.fuelType)}`}>{item.fuelType}</span></td>
                                                <td className="px-4 py-3 text-center"><input type="number" step="0.01" value={item.liters} onChange={(e) => handleUpdateCartItem(item.id, 'liters', e.target.value)} className="w-24 text-center font-mono font-bold bg-slate-50 border border-slate-200 rounded p-1" /></td>
                                                <td className="px-4 py-3 text-right"><div className="relative inline-block"><span className="absolute left-1 top-1.5 text-[10px] text-slate-400">R$</span><input type="number" step="0.01" value={item.totalCost} onChange={(e) => handleUpdateCartItem(item.id, 'totalCost', e.target.value)} className="w-32 text-right font-mono font-bold text-green-700 bg-slate-50 border border-slate-200 rounded p-1 pl-6" /></div></td>
                                                <td className="px-4 py-3 text-center"><button onClick={() => handleRemoveItemFromCart(item.id)} className="text-red-500 hover:bg-red-50 p-1.5 rounded"><Trash2 size={16} /></button></td>
                                            </tr>
                                        ))}
                                    </tbody>
                                    <tfoot className="bg-slate-50 font-bold text-slate-800 border-t border-slate-200">
                                        <tr><td className="px-4 py-3 text-right" colSpan={2}>Soma Total:</td><td className="px-4 py-3 text-right text-lg text-blue-900">{formatCurrency(cartItems.reduce((acc, curr) => acc + Number(curr.totalCost || 0), 0))}</td><td></td></tr>
                                    </tfoot>
                                </table>
                            </div>
                        )}
                    </div>

                    <div className="flex justify-end gap-3 pt-6 border-t border-slate-100">
                        <button type="button" onClick={resetForms} className="px-6 py-2.5 text-slate-600 hover:bg-slate-100 rounded-lg font-medium transition-colors">Cancelar</button>
                        <button onClick={handleSaveRefueling} disabled={loading || cartItems.length === 0} className="bg-blue-800 text-white px-8 py-2.5 rounded-lg font-bold hover:bg-blue-900 transition-all flex items-center gap-2 shadow-lg disabled:opacity-50 transform active:scale-95">{loading ? <Loader2 className="animate-spin"/> : <Save size={18} />}Salvar Lançamento Único</button>
                    </div>
                </div>
            )}

             <div className="grid grid-cols-2 md:grid-cols-4 gap-4 print:hidden">
                <div className="bg-white p-3 rounded-lg shadow-sm border border-slate-200"><p className="text-[10px] font-bold text-slate-500 uppercase">Registros Listados</p><p className="text-xl font-bold text-slate-800">{filteredRefuelings.length}</p></div>
                <div className="bg-blue-50 p-3 rounded-lg shadow-sm border border-blue-100"><p className="text-[10px] font-bold text-blue-600 uppercase">Total Litros</p><p className="text-xl font-bold text-blue-800">{totalLitersCalculated.toFixed(2)} L</p></div>
                <div className="bg-green-50 p-3 rounded-lg shadow-sm border border-green-100"><p className="text-[10px] font-bold text-green-600 uppercase">Total Valor (Geral)</p><p className="text-xl font-bold text-blue-800">{formatCurrency(totalCostCalculated)}</p></div>
             </div>

            <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden print:border-none print:shadow-none print:overflow-visible">
                <div className="overflow-x-auto print:overflow-visible">
                    <table className="w-full text-sm text-left">
                        <thead className="bg-slate-100 text-slate-600 font-bold uppercase text-xs border-b border-slate-200 print:bg-slate-200">
                            <tr><th className="px-6 py-3 print:px-2">Data / Hora</th><th className="px-6 py-3 print:px-2">Veículo / Equipe</th><th className="px-6 py-3 print:px-2">Posto</th><th className="px-6 py-3 print:px-2">Documentos</th><th className="px-6 py-3 print:px-2">Combustível</th><th className="px-6 py-3 print:px-2">Litros</th><th className="px-6 py-3 print:px-2">Valor Total</th><th className="px-6 py-3 print:hidden text-center">Ações</th></tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {paginatedRefuelings.length === 0 ? (
                                <tr><td colSpan={8} className="px-6 py-12 text-center text-slate-400">Nenhum abastecimento encontrado.</td></tr>
                            ) : (
                                paginatedRefuelings.map(item => {
                                    const station = stations.find(s => s.id === item.gasStationId);
                                    const isExt = item.vehicleId === 'EXTERNAL';
                                    const isPending = (item.totalCost <= 0);
                                    const fuelDisplay = (item.items && item.items.length > 1) ? `DIVERSOS (${item.items.length})` : item.fuelType;

                                    return (
                                        <tr key={item.id} className={`hover:bg-slate-50 transition-colors print:hover:bg-transparent ${isPending ? 'bg-red-50/30' : ''}`}>
                                            <td className="px-6 py-3 font-medium text-slate-900 print:px-2">{formatDate(item.date)}{item.time && <div className="text-xs text-slate-500">{item.time}</div>}</td>
                                            <td className="px-6 py-3 print:px-2"><div className="font-bold text-slate-800">{item.plateSnapshot}{isExt && <AlertCircle size={12} className="inline ml-1 text-orange-500" />}</div><div className="text-xs text-slate-500">{item.foremanSnapshot || 'S/ Equipe'}</div></td>
                                            <td className="px-6 py-3 print:px-2"><div className="font-medium">{station?.name || '---'}</div><div className="text-xs text-slate-500">{item.municipalitySnapshot}</div></td>
                                            <td className="px-6 py-3 print:px-2"><div className="flex flex-col gap-1">{item.invoiceNumber && (<span className="text-[10px] bg-slate-100 px-1 rounded">NF: {item.invoiceNumber}</span>)}{item.requisitionNumber && (<span className="text-[10px] bg-slate-100 px-1 rounded">REQ: {item.requisitionNumber}</span>)}</div></td>
                                            <td className="px-6 py-3 print:px-2"><span className={`text-[10px] font-bold px-1.5 py-0.5 rounded border ${getFuelColor(item.fuelType)} print:border-none print:p-0`}>{fuelDisplay}</span></td>
                                            <td className="px-6 py-3 font-mono print:px-2 text-slate-600">{item.liters > 0 ? `${item.liters.toFixed(2)} L` : <span className="text-slate-300 italic text-[10px]">Insumos</span>}</td>
                                            <td className="px-6 py-3 font-mono font-bold text-slate-700 print:px-2">{isPending ? <span className="text-red-600 animate-pulse">PENDENTE</span> : formatCurrency(item.totalCost)}</td>
                                            <td className="px-6 py-3 print:hidden text-center"><div className="flex justify-center gap-1"><button onClick={() => setSelectedTicket(item)} className="p-1.5 text-slate-600 hover:bg-slate-100 rounded" title="Ver Bilhete"><Receipt size={18} /></button>{!isReadOnly && (<><button onClick={() => handleEditRefueling(item)} className="p-1.5 text-blue-600 hover:bg-blue-50 rounded" title="Editar"><Edit2 size={18} /></button><button onClick={() => confirmDelete(item.id)} className="p-1.5 text-red-600 hover:bg-red-50 rounded" title="Excluir"><Trash2 size={18} /></button></>)}</div></td>
                                        </tr>
                                    );
                                })
                            )}
                        </tbody>
                        <tfoot className="bg-slate-100 font-bold text-slate-800 border-t border-slate-300 print:bg-slate-200">
                             <tr><td colSpan={5} className="px-6 py-3 text-right uppercase text-xs">Totais do Período</td><td className="px-6 py-3 text-blue-800">{totalLitersCalculated.toFixed(2)} L</td><td className="px-6 py-3 text-green-800">{formatCurrency(totalCostCalculated)}</td><td className="print:hidden"></td></tr>
                         </tfoot>
                    </table>
                </div>

                {totalPages > 1 && (
                  <div className="flex items-center justify-between border-t border-slate-200 bg-white px-4 py-3 sm:px-6 print:hidden">
                    <nav className="isolate inline-flex -space-x-px rounded-md shadow-sm">
                      <button onClick={() => setCurrentPage(p => Math.max(1, p - 1))} disabled={currentPage === 1} className="px-2 py-2 text-slate-400 ring-1 ring-inset ring-slate-300 hover:bg-slate-50 disabled:opacity-50"><ChevronLeft className="h-5 w-5" /></button>
                      <span className="px-4 py-2 text-sm font-semibold text-slate-900 ring-1 ring-inset ring-slate-300">Página {currentPage} de {totalPages}</span>
                      <button onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))} disabled={currentPage === totalPages} className="px-2 py-2 text-slate-400 ring-1 ring-inset ring-slate-300 hover:bg-slate-50 disabled:opacity-50"><ChevronRight className="h-5 w-5" /></button>
                    </nav>
                  </div>
                )}
            </div>
        </div>
      )}

      {activeTab === 'STATIONS' && (
        <div className="space-y-6">
           {showForm && !isReadOnly && (
             <div className="bg-white rounded-xl shadow-lg border border-slate-200 p-6 animate-in fade-in slide-in-from-top-2">
                <h3 className="font-bold text-lg text-slate-800 mb-4 flex items-center gap-2"><Fuel className="text-blue-500" />{isEditing ? 'Editar Posto' : 'Cadastrar Novo Posto'}</h3>
                <form onSubmit={handleSaveStation} className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="md:col-span-2"><label className="block text-xs font-bold uppercase text-slate-500 mb-1">Nome Fantasia</label><input type="text" required value={currentStation.name || ''} onChange={e => setCurrentStation({...currentStation, name: e.target.value.toUpperCase()})} className={inputClass} placeholder="EX: POSTO IPIRANGA..." /></div>
                    <div><label className="block text-xs font-bold uppercase text-slate-500 mb-1">Município</label><input type="text" required value={currentStation.municipality || ''} onChange={e => setCurrentStation({...currentStation, municipality: e.target.value.toUpperCase()})} className={inputClass} /></div>
                    <div><label className="block text-xs font-bold uppercase text-slate-500 mb-1">CNPJ (Opcional)</label><input type="text" value={currentStation.cnpj || ''} onChange={e => setCurrentStation({...currentStation, cnpj: e.target.value.toUpperCase()})} className={inputClass} /></div>
                    <div><label className="block text-xs font-bold uppercase text-slate-500 mb-1">Telefone (Opcional)</label><input type="text" value={currentStation.phone || ''} onChange={e => setCurrentStation({...currentStation, phone: e.target.value})} className={inputClass} /></div>
                    <div><label className="block text-xs font-bold uppercase text-slate-500 mb-1">Endereço (Opcional)</label><input type="text" value={currentStation.address || ''} onChange={e => setCurrentStation({...currentStation, address: e.target.value.toUpperCase()})} className={inputClass} /></div>
                    <div className="md:col-span-2 flex justify-end gap-3 pt-4 border-t border-slate-100"><button type="button" onClick={resetForms} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg font-medium">Cancelar</button><button type="submit" disabled={loading} className="bg-blue-800 text-white px-6 py-2 rounded-lg font-bold hover:bg-blue-900 transition-colors flex items-center gap-2">{loading ? <Loader2 className="animate-spin"/> : <Save size={18} />}Salvar Posto</button></div>
                </form>
             </div>
           )}

           <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                <table className="w-full text-sm text-left"><thead className="bg-slate-100 text-slate-600 font-bold uppercase text-xs border-b"><tr><th className="px-6 py-3">Nome</th><th className="px-6 py-3">Município</th><th className="px-6 py-3">Contato</th>{!isReadOnly && <th className="px-6 py-3 text-center">Ações</th>}</tr></thead>
                <tbody className="divide-y divide-slate-100">
                    {stations.length === 0 ? (<tr><td colSpan={4} className="px-6 py-12 text-center text-slate-400">Nenhum posto cadastrado.</td></tr>) : (stations.map(station => (<tr key={station.id} className="hover:bg-slate-50"><td className="px-6 py-3 font-bold text-slate-800">{station.name}</td><td className="px-6 py-3 text-slate-600 flex items-center gap-1"><MapPin size={14} className="text-slate-400"/> {station.municipality}</td><td className="px-6 py-3 text-slate-500 text-xs">{station.phone && <div>Tel: {station.phone}</div>}{station.cnpj && <div>CNPJ: {station.cnpj}</div>}</td>{!isReadOnly && (<td className="px-6 py-3 text-center"><div className="flex justify-center gap-2"><button onClick={() => handleEditStation(station)} className="p-2 text-blue-600 hover:bg-blue-50 rounded"><Edit2 size={16} /></button><button onClick={() => confirmDelete(station.id)} className="p-2 text-red-600 hover:bg-red-50 rounded"><Trash2 size={16} /></button></div></td>)}</tr>)))}
                </tbody></table>
           </div>
        </div>
      )}
    </div>
  );
};

export default FuelManagement;

export enum ContractType {
  MANUTENCAO = 'MANUTENÇÃO',
  LINHA_VIVA = 'LINHA VIVA',
  PLPT = 'PLPT',
  ADM_MANAUS = 'ADM_MANAUS',
  ADM_PIN = 'ADM_PIN',
  CTRNOVO = 'CTRNOVO',
  AME = 'AME',
  OFICINA = 'OFICINA',
  TRAVESSIA_SUBAQUATICA = 'TRAVESSIA SUBAQUÁTICA'
}

export enum VehicleType {
  CAMINHAO = 'CAMINHÃO',
  LINHA_VIVA = 'LINHA VIVA',
  STRADA_CABINE_SIMPLES = 'STRADA CABINE SIMPLES',
  STRADA_CABINE_DUPLA = 'STRADA CABINE DUPLA',
  PICK_UP = 'PICK-UP'
}

// --- NOVOS TIPOS DE AUTH ---
