                </form>
             </div>
           )}

           <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                <table className="w-full text-sm text-left"><thead className="bg-slate-100 text-slate-600 font-bold uppercase text-xs border-b"><tr><th className="px-6 py-3">Nome</th><th className="px-6 py-3">Município</th><th className="px-6 py-3">Contato</th>{!isReadOnly && <th className="px-6 py-3 text-center">Ações</th>}</tr></thead>
                <tbody className="divide-y divide-slate-100">
                    {stations.length === 0 ? (<tr><td colSpan={4} className="px-6 py-12 text-center text-slate-400">Nenhum posto cadastrado.</td></tr>) : (stations.map(station => (<tr key={station.id} className="hover:bg-slate-50"><td className="px-6 py-3 font-bold text-slate-800">{station.name}</td><td className="px-6 py-3 text-slate-600 flex items-center gap-1"><MapPin size={14} className="text-slate-400"/> {station.municipality}</td><td className="px-6 py-3 text-slate-500 text-xs">{station.phone && <div>Tel: {station.phone}</div>}{station.cnpj && <div>CNPJ: {station.cnpj}</div>}</td>{!isReadOnly && (<td className="px-6 py-3 text-center"><div className="flex justify-center gap-2"><button onClick={() => handleEditStation(station)} className="p-2 text-blue-600 hover:bg-blue-50 rounded"><Edit2 size={16} /></button><button onClick={() => confirmDelete(station.id)} className="p-2 text-red-600 hover:bg-red-50 rounded"><Trash2 size={16} /></button></div></td>)}</tr>)))}
                </tbody></table>
           </div>
        </div>
      )}
    </div>
  );
};

export default FuelManagement;

import React, { useState, useEffect } from 'react';
import { GasStation, RefuelingLog, Vehicle, FuelType, ContractType, UserRole, UserProfile, FUEL_TYPES_LIST, SUPPLY_TYPES_LIST, RefuelingItem } from '../types';
import { storageService } from '../services/storage';
import PasswordModal from './PasswordModal';
import { useAuth } from '../contexts/AuthContext';
import { 
  Fuel, Plus, Save, Trash2, Edit2, Droplet, Filter, X, Calendar, Printer, AlertCircle, Users, ChevronDown, ChevronUp, MapPin, Clock, ClipboardList, ChevronLeft, ChevronRight, Loader2, ShoppingCart, Package, DollarSign, Receipt
} from 'lucide-react';
import { PrintHeader } from './PrintHeader';
import MultiSelect, { MultiSelectOption } from './MultiSelect';
import SelectWithSearch from './SelectWithSearch';
import { ParisLogo } from './ParisLogo';

type TabType = 'REFUELING' | 'STATIONS';

const EXTERNAL_EQUIPMENT_TYPES = [
  'BARCO', 
  'BALSA', 
  'MOTO', 
  'CARRO',
  'LANCHA', 
  'MOTOR DE POUPA',
  'MOTOPODA', 
  'GERADOR', 
  'GALÃO', 
  'TAMBOR'
];

const ITEMS_PER_PAGE = 50;

interface RefuelingCartItem {
    id: string;
    fuelType: FuelType;
    liters: number;
    totalCost: number;
}

const FuelManagement: React.FC = () => {
  const { user } = useAuth();
  const isReadOnly = user?.role === UserRole.GERENCIA;

  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<TabType>('REFUELING');

  const [stations, setStations] = useState<GasStation[]>([]);
  const [refuelings, setRefuelings] = useState<RefuelingLog[]>([]);
  const [vehicles, setVehicles] = useState<Vehicle[]>([]);

  const [currentPage, setCurrentPage] = useState(1);

  const [filterDateStart, setFilterDateStart] = useState('');
  const [filterDateEnd, setFilterDateEnd] = useState('');
  const [filterPlate, setFilterPlate] = useState<string[]>([]);
  const [filterStation, setFilterStation] = useState<string[]>([]);
  const [filterContract, setFilterContract] = useState<string[]>([]);
  const [filterMunicipality, setFilterMunicipality] = useState<string[]>([]);
  const [filterFuel, setFilterFuel] = useState<string[]>([]);
  const [filterForeman, setFilterForeman] = useState<string[]>([]);

  const [showFilters, setShowFilters] = useState(false);

  const [uniquePlates, setUniquePlates] = useState<string[]>([]);
  const [uniqueContracts, setUniqueContracts] = useState<string[]>([]);
  const [uniqueMunicipalities, setUniqueMunicipalities] = useState<string[]>([]);
  const [uniqueForemen, setUniqueForemen] = useState<string[]>([]);

  const [showForm, setShowForm] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editingRecordId, setEditingRecordId] = useState<string | null>(null);

  const [currentStation, setCurrentStation] = useState<Partial<GasStation>>({});

  // Ticket State
  const [selectedTicket, setSelectedTicket] = useState<RefuelingLog | null>(null);

  const getTodayLocal = () => {
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const getCurrentTime = () => {
    const now = new Date();
    return now.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
  };

  // Refueling Form States
  const [refuelingHeader, setRefuelingHeader] = useState({
      date: getTodayLocal(),
      time: getCurrentTime(),
      vehicleId: '',
      gasStationId: '',
      foremanSnapshot: '',
      invoiceNumber: '',
      requisitionNumber: ''
  });

  const [cartItems, setCartItems] = useState<RefuelingCartItem[]>([]);
  const [currentItem, setCurrentItem] = useState<Partial<RefuelingCartItem>>({
      fuelType: '' as any,
      liters: 0,
      totalCost: 0
  });

  const [isExternal, setIsExternal] = useState(false);
  const [externalData, setExternalData] = useState({
    identifier: '', 
    model: '',
    contract: '',
    municipality: '',
    description: '' 
  });

  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);

  useEffect(() => {
    loadData();
  }, []);

  useEffect(() => {
    setCurrentPage(1);
  }, [filterDateStart, filterDateEnd, filterPlate, filterStation, filterContract, filterMunicipality, filterFuel, filterForeman]);

  const loadData = async () => {
    setLoading(true);
    try {
      const [sData, rData, vData] = await Promise.all([
          storageService.getGasStations(),
          storageService.getRefuelings(),
          storageService.getVehicles()
      ]);

      setStations(sData);
      setRefuelings(rData);
      setVehicles(vData);

      const plates = Array.from(new Set(rData.map(r => r.plateSnapshot))).sort();
      const contracts = Array.from(new Set(rData.map(r => r.contractSnapshot))).sort();
      const cities = Array.from(new Set(rData.map(r => r.municipalitySnapshot))).sort();
      const vehicleTeams = Array.from(new Set(vData.map(v => v.foreman).filter(f => f && f.trim() !== ''))).sort();

      setUniquePlates(plates);
      setUniqueContracts(contracts);
      setUniqueMunicipalities(cities);
      setUniqueForemen(vehicleTeams);
    } catch (e) {
        console.error(e);
    } finally {
        setLoading(false);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const getFuelColor = (fuelType: string) => {
    if (fuelType === FuelType.OUTROS || fuelType.includes('DIVERSOS')) return 'bg-purple-100 text-purple-800 border-purple-200';
    switch (fuelType) {
      case FuelType.GASOLINA: return 'bg-orange-100 text-orange-800 border-orange-200'; 
      case FuelType.ETANOL: return 'bg-green-100 text-green-800 border-green-200';
      case FuelType.DIESEL: return 'bg-yellow-100 text-yellow-800 border-yellow-200';
      case FuelType.DIESEL_S10: return 'bg-slate-100 text-slate-800 border-slate-200';
      default: return 'bg-gray-100 text-gray-800 border-gray-200';
    }
  };

  const handleAddItemToCart = () => {
      if (!currentItem.fuelType) {
          alert("Selecione o item/combustível.");
          return;
      }

      const qty = Number(currentItem.liters || 0);
      const cost = Number(currentItem.totalCost || 0);

      if (qty <= 0 && cost <= 0) {
          alert("Informe a quantidade ou o valor do item.");
          return;
      }

      const newItem: RefuelingCartItem = {
          id: crypto.randomUUID(),
          fuelType: currentItem.fuelType as FuelType,
          liters: qty,
          totalCost: cost
      };

      setCartItems(prev => [...prev, newItem]);
      setCurrentItem({ fuelType: '' as any, liters: 0, totalCost: 0 });
  };

  const handleUpdateCartItem = (id: string, field: 'liters' | 'totalCost', value: string) => {
      const numValue = value === '' ? 0 : Number(value);
      setCartItems(prev => prev.map(item => 
          item.id === id ? { ...item, [field]: numValue } : item
      ));
  };

  const handleRemoveItemFromCart = (id: string) => {
      setCartItems(prev => prev.filter(item => item.id !== id));
  };

  const handleSaveStation = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly) return;
    if (!currentStation.name || !currentStation.municipality) return;

    const newStation: GasStation = {
      id: currentStation.id || crypto.randomUUID(),
      name: currentStation.name.toUpperCase(),
      cnpj: currentStation.cnpj ? currentStation.cnpj.toUpperCase() : '',
      municipality: currentStation.municipality.toUpperCase(),
      phone: currentStation.phone || '',
      address: currentStation.address ? currentStation.address.toUpperCase() : ''
    };

    setLoading(true);
    try {
        await storageService.saveGasStation(newStation);
        await loadData();
        resetForms();
    } catch (err: any) {
        console.error(err);
        alert(`Erro ao salvar posto: ${err.message}`);
    } finally {
        setLoading(false);
    }
  };

  const handleEditStation = (station: GasStation) => {
    if (isReadOnly) return;
    setCurrentStation(station);
    setIsEditing(true);
    setShowForm(true);
    setActiveTab('STATIONS');
  };

  const deleteStation = async (id: string) => {
    if (isReadOnly) return;
    const hasUsage = refuelings.some(r => r.gasStationId === id);
    if(hasUsage) {
        alert("Não é possível excluir este posto pois existem abastecimentos vinculados a ele.");
        return;
    }
    setLoading(true);
    try {
        await storageService.deleteGasStation(id);
        await loadData();
        setShowDeleteModal(false);
        setItemToDelete(null);
    } catch (err: any) {
        console.error(err);
        alert(`Erro ao excluir posto: ${err.message}`);
    } finally {
        setLoading(false);
    }
  };

  const getTicketItems = (log: RefuelingLog): RefuelingItem[] => {
      if (log.items && log.items.length > 0) return log.items;
      // Fallback para registros antigos que não tinham o array de itens consolidado
      return [{
          fuelType: log.fuelType,
          liters: log.liters,
          totalCost: log.totalCost
      }];
  };

  const handleSaveRefueling = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly) return;

    // Validações básicas
    if (!refuelingHeader.gasStationId) {
        alert("Selecione o posto.");
        return;
    }

    if (cartItems.length === 0) {
        alert("Adicione pelo menos um item à lista.");
        return;
    }

    let snapshotData = {
        plate: '',
        model: '',
        contract: '',
        municipality: '',
        foreman: refuelingHeader.foremanSnapshot || ''
    };

    let vehicleIdToSave = '';

    if (isExternal) {
        if (!externalData.identifier || !externalData.contract || !externalData.municipality) {
            alert("Para equipamentos externos, preencha Identificação, Contrato e Município.");
            return;
        }
        snapshotData.plate = externalData.identifier.toUpperCase();
        snapshotData.model = externalData.model ? externalData.model.toUpperCase() : '';
        snapshotData.contract = externalData.contract;
        snapshotData.municipality = externalData.municipality.toUpperCase();
        vehicleIdToSave = 'EXTERNAL';
    } else {
        if (!refuelingHeader.vehicleId) {
            alert("Selecione o veículo.");
            return;
        }

        const vehicle = vehicles.find(v => v.id === refuelingHeader.vehicleId);
        if (!vehicle) {
            alert("Veículo não encontrado no cadastro.");
            return;
        }

        snapshotData.plate = vehicle.plate;
        snapshotData.model = vehicle.model || '';
        snapshotData.contract = vehicle.contract;
        snapshotData.municipality = vehicle.municipality;
        if (!snapshotData.foreman) snapshotData.foreman = vehicle.foreman;

        vehicleIdToSave = refuelingHeader.vehicleId;
    }

    setLoading(true);
    try {
        // --- LÓGICA DE CONSOLIDAÇÃO INTELIGENTE ---

        // 1. Somar apenas litros de combustíveis líquidos (para não distorcer média de KM/L)
        const totalLiters = cartItems.reduce((acc, curr) => {
            return FUEL_TYPES_LIST.includes(curr.fuelType) ? acc + Number(curr.liters || 0) : acc;
        }, 0);

        // 2. Somar custo total de TODOS os itens (combustível + óleos + insumos)
        const totalCost = cartItems.reduce((acc, curr) => acc + Number(curr.totalCost || 0), 0);

        // 3. Determinar o tipo principal para o banco de dados
        // Se houver múltiplos tipos, marcamos como "OUTROS" para compatibilidade,
        // mas a interface exibirá "DIVERSOS"
        const isMultiple = cartItems.length > 1;
        const mainFuelType = isMultiple ? FuelType.OUTROS : cartItems[0].fuelType;

        // 4. Criar string de observação detalhada
        const itemsBreakdown = cartItems.map(i => `${i.fuelType}: ${Number(i.liters).toFixed(2)}${FUEL_TYPES_LIST.includes(i.fuelType) ? 'L' : 'un'}`).join(' | ');
        const customObs = isExternal && externalData.description ? externalData.description.toUpperCase() : '';
        const finalObs = `[ITENS: ${itemsBreakdown}] ${customObs}`.trim();

        const newRefueling: RefuelingLog = {
            id: (isEditing && editingRecordId) ? editingRecordId : crypto.randomUUID(),
            date: refuelingHeader.date,
            vehicleId: vehicleIdToSave,
            gasStationId: refuelingHeader.gasStationId,
            fuelType: mainFuelType, 
            liters: Number(totalLiters.toFixed(2)), 
            totalCost: Number(totalCost.toFixed(2)), 
            items: cartItems.map(i => ({ fuelType: i.fuelType, liters: i.liters, totalCost: i.totalCost })), // Salvando o JSON completo
            invoiceNumber: refuelingHeader.invoiceNumber ? refuelingHeader.invoiceNumber.toUpperCase() : '',
            requisitionNumber: refuelingHeader.requisitionNumber ? refuelingHeader.requisitionNumber.toUpperCase() : '',
            time: refuelingHeader.time || '', 

            plateSnapshot: snapshotData.plate,
            modelSnapshot: snapshotData.model,
            foremanSnapshot: snapshotData.foreman, 
            contractSnapshot: snapshotData.contract,
            municipalitySnapshot: snapshotData.municipality,
            observation: finalObs
        };

        // Salvar via upsert no Supabase
        await storageService.saveRefueling(newRefueling);

        await loadData();
        resetForms();
        alert("Abastecimento consolidado salvo com sucesso!");
    } catch (err: any) {
        console.error("Erro ao salvar abastecimento:", err);
        alert(`Erro ao salvar no servidor: ${err.message || 'Verifique sua conexão.'}`);
    } finally {
        setLoading(false);
    }
  };

  const handleEditRefueling = (refueling: RefuelingLog) => {
    if (isReadOnly) return;

    setRefuelingHeader({
        date: refueling.date,
        time: refueling.time || '',
        vehicleId: refueling.vehicleId,
        gasStationId: refueling.gasStationId,
        foremanSnapshot: refueling.foremanSnapshot || '',
        invoiceNumber: refueling.invoiceNumber || '',
        requisitionNumber: refueling.requisitionNumber || ''
    });

    setEditingRecordId(refueling.id);

    // Reconstruir o carrinho a partir do array de itens ou do registro simples
    const savedItems: RefuelingCartItem[] = (refueling.items && refueling.items.length > 0)
        ? refueling.items.map(i => ({ ...i, id: crypto.randomUUID() }))
        : [{
            id: crypto.randomUUID(),
            fuelType: refueling.fuelType,
            liters: refueling.liters,
            totalCost: refueling.totalCost
        }];

    setCartItems(savedItems);

    const vehicleExists = vehicles.find(v => v.id === refueling.vehicleId);

    if (!vehicleExists || refueling.vehicleId === 'EXTERNAL') {
        setIsExternal(true);
        // Limpar a observação para não mostrar o prefixo técnico [ITENS: ...] no campo de texto
        const cleanObs = refueling.observation?.includes('] ') ? refueling.observation.split('] ')[1] : refueling.observation;
        setExternalData({
            identifier: refueling.plateSnapshot,
            model: refueling.modelSnapshot,
            contract: refueling.contractSnapshot,
            municipality: refueling.municipalitySnapshot,
            description: cleanObs || ''
        });
    } else {
        setIsExternal(false);
        setExternalData({ identifier: '', model: '', contract: '', municipality: '', description: '' });
    }

    setIsEditing(true);
    setShowForm(true);
    setActiveTab('REFUELING');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const deleteRefueling = async (id: string) => {
    if (isReadOnly) return;
    setLoading(true);
    try {
        await storageService.deleteRefueling(id);
        await loadData();
        setShowDeleteModal(false);
        setItemToDelete(null);
    } catch (err: any) {
        console.error(err);
        alert(`Erro ao excluir abastecimento: ${err.message}`);
    } finally {
        setLoading(false);
    }
  };

  const resetForms = () => {
    setShowForm(false);
    setIsEditing(false);
    setEditingRecordId(null);
    setCurrentStation({});
    setRefuelingHeader({
      date: getTodayLocal(),
      time: getCurrentTime(),
      vehicleId: '',
      gasStationId: '',
      foremanSnapshot: '',
      invoiceNumber: '',
      requisitionNumber: ''
    });
    setCartItems([]);
    setCurrentItem({ fuelType: '' as any, liters: 0, totalCost: 0 });
    setIsExternal(false);
    setExternalData({ identifier: '', model: '', contract: '', municipality: '', description: '' });
  };

  const resetFilters = () => {
    setFilterDateStart('');
    setFilterDateEnd('');
    setFilterPlate([]);
    setFilterStation([]);
    setFilterContract([]);
    setFilterMunicipality([]);
    setFilterFuel([]);
    setFilterForeman([]);
  };

  const confirmDelete = (id: string) => {
    if (isReadOnly) return;
    setItemToDelete(id);
    setShowDeleteModal(true);
  };

  const executeDelete = () => {
    if (itemToDelete) {
      if (activeTab === 'STATIONS') {
        deleteStation(itemToDelete);
      } else {
        deleteRefueling(itemToDelete);
      }
    }
  };

  const handleVehicleChange = (vehicleId: string) => {
    const vehicle = vehicles.find(v => v.id === vehicleId);
    if (vehicle) {
        setRefuelingHeader(prev => ({
            ...prev,
            vehicleId: vehicleId,
            foremanSnapshot: vehicle.foreman || ''
        }));
    } else {
        setRefuelingHeader(prev => ({ ...prev, vehicleId: vehicleId, foremanSnapshot: '' }));
    }
  };

  const formatDate = (dateStr: string) => {
    if (!dateStr) return '-';
    const [y, m, d] = dateStr.split('-');
    return `${d}/${m}/${y}`;
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val || 0);
  };

  const filteredRefuelings = refuelings.filter(r => {
      const rDate = new Date(r.date).getTime();
      const start = filterDateStart ? new Date(filterDateStart).getTime() : null;
      const end = filterDateEnd ? new Date(filterDateEnd).getTime() : null;
      const matchesDate = (!start || rDate >= start) && (!end || rDate <= end);

      const matchesPlate = filterPlate.length === 0 || filterPlate.includes(r.plateSnapshot);
      const matchesStation = filterStation.length === 0 || filterStation.includes(r.gasStationId);
      const matchesContract = filterContract.length === 0 || filterContract.includes(r.contractSnapshot);
      const matchesCity = filterMunicipality.length === 0 || filterMunicipality.includes(r.municipalitySnapshot);

      const matchesFuel = filterFuel.length === 0 || 
                         filterFuel.includes(r.fuelType) || 
                         (r.items && r.items.some(i => filterFuel.includes(i.fuelType)));

      const matchesForeman = filterForeman.length === 0 || (r.foremanSnapshot && filterForeman.includes(r.foremanSnapshot));

      return matchesDate && matchesPlate && matchesStation && matchesContract && matchesCity && matchesFuel && matchesForeman;
  }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  const totalPages = Math.ceil(filteredRefuelings.length / ITEMS_PER_PAGE);
  const paginatedRefuelings = filteredRefuelings.slice(
    (currentPage - 1) * ITEMS_PER_PAGE,
    currentPage * ITEMS_PER_PAGE
  );

  const totalLitersCalculated = filteredRefuelings.reduce((acc, curr) => acc + (curr.liters || 0), 0);
  const totalCostCalculated = filteredRefuelings.reduce((acc, curr) => acc + (curr.totalCost || 0), 0);

  const activeFiltersCount = [
    filterDateStart, filterDateEnd, 
    filterPlate.length, filterStation.length, 
    filterContract.length, filterMunicipality.length, filterFuel.length, filterForeman.length
  ].filter(Boolean).reduce((a, b) => a + (typeof b === 'number' ? b : 1), 0);

  const inputClass = "w-full rounded-lg border border-slate-300 bg-slate-50 p-2.5 text-slate-800 focus:border-blue-600 focus:bg-white focus:ring-2 focus:ring-blue-100 outline-none transition-all";
  const selectClass = "w-full rounded-lg border border-slate-300 bg-white p-2 text-slate-700 focus:border-blue-600 focus:ring-2 focus:ring-blue-100 outline-none transition-all h-[42px] shadow-sm";

  const plateOptions: MultiSelectOption[] = uniquePlates.map(p => ({ value: p, label: p }));
  const stationOptions: MultiSelectOption[] = stations.map(s => ({ value: s.id, label: s.name }));
  const contractOptions: MultiSelectOption[] = uniqueContracts.map(c => ({ value: c, label: c }));
  const municipalityOptions: MultiSelectOption[] = uniqueMunicipalities.map(m => ({ value: m, label: m }));
  const foremanOptions: MultiSelectOption[] = uniqueForemen.map(f => ({ value: f, label: f }));
  const fuelOptions: MultiSelectOption[] = Object.values(FuelType).map(f => ({ value: f, label: f }));

  const vehicleOptions = vehicles.map(v => ({
      value: v.id,
      label: `${v.plate} - ${v.driverName} (${v.type})`
  }));

  const stationSelectOptions = stations.map(s => ({
      value: s.id,
      label: `${s.name} - ${s.municipality}`
  }));

  if (loading && activeTab === 'REFUELING' && refuelings.length === 0) {
      return <div className="flex justify-center items-center h-64"><Loader2 className="animate-spin text-blue-600" size={48} /></div>;
  }

  return (
    <div className="space-y-6">

      <PrintHeader 
        title="Relatório de Abastecimentos"
        subtitle="Consolidado de Consumo"
        details={
            <>
                <span>Registros: {filteredRefuelings.length}</span>
                <span>Total Litros: {totalLitersCalculated.toFixed(2)} L</span>
                <span>Total Valor: {formatCurrency(totalCostCalculated)}</span>
            </>
        }
      />

       <div className="print:hidden">
        <PasswordModal
            isOpen={showDeleteModal}
            onClose={() => setShowDeleteModal(false)}
            onConfirm={executeDelete}
            title={activeTab === 'STATIONS' ? "Excluir Posto" : "Excluir Abastecimento"}
        />
      </div>

      {selectedTicket && (
        <div className="fixed inset-0 bg-black/70 backdrop-blur-sm z-[999] flex items-center justify-center p-4 print:hidden">
            <div className="bg-white rounded-xl shadow-2xl max-w-sm w-full overflow-hidden animate-in zoom-in-95 duration-200">
                <div className="bg-slate-900 p-4 text-white flex justify-between items-center">
                    <h3 className="font-bold flex items-center gap-2"><Receipt size={20} /> Bilhete de Lançamento</h3>
                    <button onClick={() => setSelectedTicket(null)} className="p-1 hover:bg-slate-800 rounded transition-colors"><X size={20}/></button>
                </div>

                <div className="p-6 bg-white font-mono text-xs text-slate-700 space-y-4" id="refueling-ticket-print">
                    <div className="flex flex-col items-center border-b border-dashed border-slate-300 pb-4">
                        <ParisLogo variant="dark" size="normal" />
