import React, { useState, useEffect } from 'react';
import { GasStation, RefuelingLog, Vehicle, FuelType, ContractType, UserRole, FUEL_TYPES_LIST, SUPPLY_TYPES_LIST } from '../types';
import { storageService } from '../services/storage';
import PasswordModal from './PasswordModal';
import { useAuth } from '../contexts/AuthContext';
import { 
  Fuel, Plus, Save, Trash2, Edit2, Droplet, Filter, X, Calendar, Printer, AlertCircle, Users, ChevronDown, ChevronUp, MapPin, Clock, ClipboardList, ChevronLeft, ChevronRight, Loader2
} from 'lucide-react';
import { PrintHeader } from './PrintHeader';
import MultiSelect, { MultiSelectOption } from './MultiSelect';
import SelectWithSearch from './SelectWithSearch';

type TabType = 'REFUELING' | 'STATIONS';

const EXTERNAL_EQUIPMENT_TYPES = [
  'BARCO', 'BALSA', 'MOTO', 'CARRO', 'LANCHA', 'MOTOR DE POUPA', 'MOTOPODA', 'GERADOR', 'GALÃO', 'TAMBOR'
];

const ITEMS_PER_PAGE = 50;

const FuelManagement: React.FC = () => {
  const { user } = useAuth();
  const isReadOnly = user?.role === UserRole.GERENCIA;

  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<TabType>('REFUELING');

  const [stations, setStations] = useState<GasStation[]>([]);
  const [refuelings, setRefuelings] = useState<RefuelingLog[]>([]);
  const [vehicles, setVehicles] = useState<Vehicle[]>([]);

  const [currentPage, setCurrentPage] = useState(1);

  const [filterDateStart, setFilterDateStart] = useState('');
  const [filterDateEnd, setFilterDateEnd] = useState('');
  const [filterPlate, setFilterPlate] = useState<string[]>([]);
  const [filterStation, setFilterStation] = useState<string[]>([]);
  const [filterContract, setFilterContract] = useState<string[]>([]);
  const [filterMunicipality, setFilterMunicipality] = useState<string[]>([]);
  const [filterFuel, setFilterFuel] = useState<string[]>([]);
  const [filterForeman, setFilterForeman] = useState<string[]>([]);

  const [showFilters, setShowFilters] = useState(false);

  const [uniquePlates, setUniquePlates] = useState<string[]>([]);
  const [uniqueContracts, setUniqueContracts] = useState<string[]>([]);
  const [uniqueMunicipalities, setUniqueMunicipalities] = useState<string[]>([]);
  const [uniqueForemen, setUniqueForemen] = useState<string[]>([]);

  const [showForm, setShowForm] = useState(false);
  const [isEditing, setIsEditing] = useState(false);

  const [currentStation, setCurrentStation] = useState<Partial<GasStation>>({});

  const getTodayLocal = () => {
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const getCurrentTime = () => {
    const now = new Date();
    return now.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
  };

  const [formData, setFormData] = useState<Partial<RefuelingLog>>({
    date: getTodayLocal(),
    time: getCurrentTime(),
    fuelType: FuelType.DIESEL_S10,
    liters: 0,
    totalCost: 0,
    vehicleId: '',
    gasStationId: '',
    invoiceNumber: '',
    requisitionNumber: '',
    observation: ''
  });

  const [isExternal, setIsExternal] = useState(false);
  const [externalInfo, setExternalInfo] = useState({
    identifier: '',
    type: 'GERADOR',
    contract: ContractType.ADM_MANAUS,
    municipality: ''
  });

  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    try {
      const [sData, rData, vData] = await Promise.all([
          storageService.getGasStations(),
          storageService.getRefuelings(),
          storageService.getVehicles()
      ]);

      setStations(sData);
      setRefuelings(rData);
      setVehicles(vData);

      const plates = Array.from(new Set(rData.map(r => r.plateSnapshot))).sort();
      const contracts = Array.from(new Set(rData.map(r => r.contractSnapshot))).sort();
      const cities = Array.from(new Set(rData.map(r => r.municipalitySnapshot))).sort();
      const vehicleTeams = Array.from(new Set(vData.map(v => v.foreman).filter(f => f && f.trim() !== ''))).sort();

      setUniquePlates(plates);
      setUniqueContracts(contracts);
      setUniqueMunicipalities(cities);
      setUniqueForemen(vehicleTeams);
    } catch (e) {
        console.error(e);
    } finally {
        setLoading(false);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const handleSaveStation = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly) return;
    if (!currentStation.name || !currentStation.municipality) return;

    const newStation: GasStation = {
      id: currentStation.id || crypto.randomUUID(),
      name: currentStation.name.toUpperCase(),
      cnpj: currentStation.cnpj ? currentStation.cnpj.toUpperCase() : '',
      municipality: currentStation.municipality.toUpperCase(),
      phone: currentStation.phone || '',
      address: currentStation.address ? currentStation.address.toUpperCase() : ''
    };

    setLoading(true);
    try {
        await storageService.saveGasStation(newStation);
        await loadData();
        resetForms();
    } catch (err: any) {
        alert(`Erro ao salvar posto: ${err.message}`);
    } finally {
        setLoading(false);
    }
  };

  const handleSaveRefueling = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly) return;

    if (!formData.gasStationId) {
        alert("Selecione o posto.");
        return;
    }

    let logToSave: RefuelingLog;

    if (isExternal) {
        if (!externalInfo.identifier || !externalInfo.municipality) {
            alert("Preencha a identificação e o município do equipamento externo.");
            return;
        }
        logToSave = {
            id: formData.id || crypto.randomUUID(),
            date: formData.date!,
            time: formData.time,
            vehicleId: 'EXTERNAL',
            gasStationId: formData.gasStationId,
            fuelType: formData.fuelType!,
            liters: Number(formData.liters),
            totalCost: Number(formData.totalCost),
            invoiceNumber: formData.invoiceNumber?.toUpperCase() || '',
            requisitionNumber: formData.requisitionNumber?.toUpperCase() || '',
            plateSnapshot: externalInfo.identifier.toUpperCase(),
            modelSnapshot: externalInfo.type,
            foremanSnapshot: 'EXTERNO',
            contractSnapshot: externalInfo.contract,
            municipalitySnapshot: externalInfo.municipality.toUpperCase(),
            observation: formData.observation?.toUpperCase() || ''
        };
    } else {
        if (!formData.vehicleId) {
            alert("Selecione o veículo.");
            return;
        }
        const v = vehicles.find(veh => veh.id === formData.vehicleId);
        if (!v) return;

        logToSave = {
            id: formData.id || crypto.randomUUID(),
            date: formData.date!,
            time: formData.time,
            vehicleId: formData.vehicleId,
            gasStationId: formData.gasStationId,
            fuelType: formData.fuelType!,
            liters: Number(formData.liters),
            totalCost: Number(formData.totalCost),
            invoiceNumber: formData.invoiceNumber?.toUpperCase() || '',
            requisitionNumber: formData.requisitionNumber?.toUpperCase() || '',
            plateSnapshot: v.plate,
            modelSnapshot: v.model || '',
            foremanSnapshot: v.foreman,
            contractSnapshot: v.contract,
            municipalitySnapshot: v.municipality,
            observation: formData.observation?.toUpperCase() || ''
        };
    }

    setLoading(true);
    try {
        await storageService.saveRefueling(logToSave);
        await loadData();
        resetForms();
        alert("Abastecimento salvo com sucesso!");
    } catch (err: any) {
        alert(`Erro ao salvar: ${err.message}`);
    } finally {
        setLoading(false);
    }
  };

  const handleEditRefueling = (refueling: RefuelingLog) => {
    if (isReadOnly) return;
    setFormData(refueling);
    if (refueling.vehicleId === 'EXTERNAL') {
        setIsExternal(true);
        setExternalInfo({
            identifier: refueling.plateSnapshot,
            type: refueling.modelSnapshot,
            contract: refueling.contractSnapshot as ContractType,
            municipality: refueling.municipalitySnapshot
        });
    } else {
        setIsExternal(false);
    }
    setIsEditing(true);
    setShowForm(true);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const resetForms = () => {
    setShowForm(false);
    setIsEditing(false);
    setCurrentStation({});
    setFormData({
      date: getTodayLocal(),
      time: getCurrentTime(),
      fuelType: FuelType.DIESEL_S10,
      liters: 0,
      totalCost: 0,
      vehicleId: '',
      gasStationId: '',
      invoiceNumber: '',
      requisitionNumber: '',
      observation: ''
    });
    setIsExternal(false);
  };

  const confirmDelete = (id: string) => {
    if (isReadOnly) return;
    setItemToDelete(id);
    setShowDeleteModal(true);
  };

  const executeDelete = async () => {
    if (itemToDelete) {
        setLoading(true);
        try {
            if (activeTab === 'STATIONS') {
                await storageService.deleteGasStation(itemToDelete);
            } else {
                await storageService.deleteRefueling(itemToDelete);
            }
            await loadData();
            setShowDeleteModal(false);
            setItemToDelete(null);
        } catch (e) {
            alert("Erro ao excluir.");
        } finally {
            setLoading(false);
        }
    }
  };

  const filteredRefuelings = refuelings.filter(r => {
      const rDate = new Date(r.date).getTime();
      const start = filterDateStart ? new Date(filterDateStart).getTime() : null;
      const end = filterDateEnd ? new Date(filterDateEnd).getTime() : null;
      const matchesDate = (!start || rDate >= start) && (!end || rDate <= end);

      const matchesPlate = filterPlate.length === 0 || filterPlate.includes(r.plateSnapshot);
      const matchesStation = filterStation.length === 0 || filterStation.includes(r.gasStationId);
      const matchesContract = filterContract.length === 0 || filterContract.includes(r.contractSnapshot);
      const matchesCity = filterMunicipality.length === 0 || filterMunicipality.includes(r.municipalitySnapshot);
      const matchesFuel = filterFuel.length === 0 || filterFuel.includes(r.fuelType);

      return matchesDate && matchesPlate && matchesStation && matchesContract && matchesCity && matchesFuel;
  }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  const totalPages = Math.ceil(filteredRefuelings.length / ITEMS_PER_PAGE);
  const paginatedRefuelings = filteredRefuelings.slice(
    (currentPage - 1) * ITEMS_PER_PAGE,
    currentPage * ITEMS_PER_PAGE
  );

  const inputClass = "w-full rounded-lg border border-slate-300 bg-slate-50 p-2.5 text-slate-800 focus:border-blue-600 focus:bg-white outline-none transition-all";

  return (
    <div className="space-y-6">
      <PrintHeader title="Abastecimentos" />

      <PasswordModal isOpen={showDeleteModal} onClose={() => setShowDeleteModal(false)} onConfirm={executeDelete} title="Excluir Registro" />

      <div className="flex justify-between items-center print:hidden">
        <h1 className="text-2xl font-bold flex items-center gap-2"><Fuel className="text-blue-600" /> Abastecimento</h1>
        <div className="flex gap-2">
            <button onClick={() => { resetForms(); setShowForm(!showForm); }} className="bg-blue-600 text-white px-4 py-2 rounded-lg font-bold flex items-center gap-2">
                {showForm ? <X size={18} /> : <Plus size={18} />} {showForm ? 'Cancelar' : 'Novo'}
            </button>
            <button onClick={handlePrint} className="bg-white border px-4 py-2 rounded-lg font-bold flex items-center gap-2"><Printer size={18}/> Imprimir</button>
        </div>
      </div>

      <div className="flex border-b print:hidden">
        <button onClick={() => setActiveTab('REFUELING')} className={`px-6 py-2 font-bold ${activeTab === 'REFUELING' ? 'border-b-2 border-blue-600 text-blue-600' : 'text-slate-500'}`}>Registros</button>
        <button onClick={() => setActiveTab('STATIONS')} className={`px-6 py-2 font-bold ${activeTab === 'STATIONS' ? 'border-b-2 border-blue-600 text-blue-600' : 'text-slate-500'}`}>Postos</button>
      </div>

      {showForm && !isReadOnly && (
        <div className="bg-white p-6 rounded-xl shadow-lg border animate-in fade-in print:hidden">
            <form onSubmit={handleSaveRefueling} className="grid grid-cols-1 md:grid-cols-4 gap-4">
                <div className="md:col-span-4 flex items-center gap-2 mb-2">
                    <input type="checkbox" checked={isExternal} onChange={e => setIsExternal(e.target.checked)} id="ext" className="w-4 h-4" />
                    <label htmlFor="ext" className="text-sm font-bold text-slate-700">Equipamento Externo / Não Cadastrado</label>
                </div>

                <div><label className="block text-xs font-bold uppercase text-slate-500 mb-1">Data</label><input type="date" required value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} className={inputClass} /></div>
                <div><label className="block text-xs font-bold uppercase text-slate-500 mb-1">Hora</label><input type="time" value={formData.time} onChange={e => setFormData({...formData, time: e.target.value})} className={inputClass} /></div>

                {isExternal ? (
                    <>
                        <div className="md:col-span-2"><label className="block text-xs font-bold uppercase text-slate-500 mb-1">Identificação</label><input type="text" required value={externalInfo.identifier} onChange={e => setExternalInfo({...externalInfo, identifier: e.target.value})} className={inputClass} placeholder="Placa ou Nome" /></div>
                        <div><label className="block text-xs font-bold uppercase text-slate-500 mb-1">Tipo</label><select value={externalInfo.type} onChange={e => setExternalInfo({...externalInfo, type: e.target.value})} className={inputClass}>{EXTERNAL_EQUIPMENT_TYPES.map(t => <option key={t} value={t}>{t}</option>)}</select></div>
                        <div><label className="block text-xs font-bold uppercase text-slate-500 mb-1">Município</label><input type="text" required value={externalInfo.municipality} onChange={e => setExternalInfo({...externalInfo, municipality: e.target.value})} className={inputClass} /></div>
                    </>
                ) : (
                    <div className="md:col-span-2"><SelectWithSearch label="Veículo" options={vehicles.map(v => ({value: v.id, label: v.plate}))} value={formData.vehicleId || ''} onChange={val => setFormData({...formData, vehicleId: val})} /></div>
                )}

                <div><label className="block text-xs font-bold uppercase text-slate-500 mb-1">Posto</label><select required value={formData.gasStationId} onChange={e => setFormData({...formData, gasStationId: e.target.value})} className={inputClass}><option value="">Selecione...</option>{stations.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}</select></div>
                <div><label className="block text-xs font-bold uppercase text-slate-500 mb-1">Combustível</label><select value={formData.fuelType} onChange={e => setFormData({...formData, fuelType: e.target.value as FuelType})} className={inputClass}>{Object.values(FuelType).map(f => <option key={f} value={f}>{f}</option>)}</select></div>
                <div><label className="block text-xs font-bold uppercase text-slate-500 mb-1">Litros</label><input type="number" step="0.01" value={formData.liters} onChange={e => setFormData({...formData, liters: Number(e.target.value)})} className={inputClass} /></div>
                <div><label className="block text-xs font-bold uppercase text-slate-500 mb-1">Valor Total (R$)</label><input type="number" step="0.01" value={formData.totalCost} onChange={e => setFormData({...formData, totalCost: Number(e.target.value)})} className={inputClass} /></div>
                <div className="md:col-span-2"><label className="block text-xs font-bold uppercase text-slate-500 mb-1">Observação</label><input type="text" value={formData.observation} onChange={e => setFormData({...formData, observation: e.target.value})} className={inputClass} /></div>

                <div className="md:col-span-4 flex justify-end gap-2 mt-4 border-t pt-4">
                    <button type="button" onClick={resetForms} className="px-6 py-2 text-slate-500 font-bold">Cancelar</button>
                    <button type="submit" disabled={loading} className="bg-green-600 text-white px-8 py-2 rounded-lg font-bold flex items-center gap-2 shadow-md">
                        {loading ? <Loader2 className="animate-spin" /> : <Save size={18}/>} SALVAR
                    </button>
                </div>
            </form>
        </div>
      )}

      {activeTab === 'REFUELING' && (
          <div className="bg-white rounded-xl shadow overflow-hidden">
              <div className="overflow-x-auto">
                  <table className="w-full text-sm text-left">
                      <thead className="bg-slate-100 font-bold text-slate-600 uppercase">
                          <tr>
                              <th className="px-6 py-3">Data</th>
                              <th className="px-6 py-3">Veículo</th>
                              <th className="px-6 py-3">Posto</th>
                              <th className="px-6 py-3">Combustível</th>
                              <th className="px-6 py-3">Litros</th>
                              <th className="px-6 py-3">Valor</th>
                              <th className="px-6 py-3 text-center print:hidden">Ações</th>
                          </tr>
                      </thead>
                      <tbody className="divide-y">
                          {paginatedRefuelings.map(r => (
                              <tr key={r.id} className="hover:bg-slate-50">
                                  <td className="px-6 py-4">{r.date.split('-').reverse().join('/')}</td>
                                  <td className="px-6 py-4 font-bold">{r.plateSnapshot}</td>
                                  <td className="px-6 py-4">{stations.find(s => s.id === r.gasStationId)?.name}</td>
                                  <td className="px-6 py-4 text-xs font-bold">{r.fuelType}</td>
                                  <td className="px-6 py-4">{r.liters} L</td>
                                  <td className="px-6 py-4 font-bold text-green-700">R$ {r.totalCost.toFixed(2)}</td>
                                  <td className="px-6 py-4 text-center print:hidden">
                                      <div className="flex justify-center gap-2">
                                          <button onClick={() => handleEditRefueling(r)} className="text-blue-600"><Edit2 size={16}/></button>
                                          <button onClick={() => confirmDelete(r.id)} className="text-red-600"><Trash2 size={16}/></button>
                                      </div>
                                  </td>
                              </tr>
                          ))}
                      </tbody>
                  </table>
              </div>
          </div>
      )}

      {activeTab === 'STATIONS' && (
          <div className="space-y-4">
              {showForm && (
                  <form onSubmit={handleSaveStation} className="bg-white p-6 rounded-xl border grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div className="md:col-span-2"><label className="block text-xs font-bold uppercase text-slate-500 mb-1">Nome</label><input type="text" required value={currentStation.name || ''} onChange={e => setCurrentStation({...currentStation, name: e.target.value})} className={inputClass} /></div>
                      <div><label className="block text-xs font-bold uppercase text-slate-500 mb-1">Município</label><input type="text" required value={currentStation.municipality || ''} onChange={e => setCurrentStation({...currentStation, municipality: e.target.value})} className={inputClass} /></div>
                      <div><label className="block text-xs font-bold uppercase text-slate-500 mb-1">CNPJ</label><input type="text" value={currentStation.cnpj || ''} onChange={e => setCurrentStation({...currentStation, cnpj: e.target.value})} className={inputClass} /></div>
                      <div className="md:col-span-2 flex justify-end gap-2"><button type="submit" className="bg-blue-600 text-white px-6 py-2 rounded-lg font-bold">Salvar Posto</button></div>
                  </form>
              )}
              <div className="bg-white rounded-xl shadow overflow-hidden">
                  <table className="w-full text-sm text-left">
                      <thead className="bg-slate-100 font-bold text-slate-600 uppercase"><tr><th className="px-6 py-3">Nome</th><th className="px-6 py-3">Município</th><th className="px-6 py-3 text-center">Ações</th></tr></thead>
                      <tbody className="divide-y">{stations.map(s => <tr key={s.id} className="hover:bg-slate-50"><td className="px-6 py-4 font-bold">{s.name}</td><td className="px-6 py-4">{s.municipality}</td><td className="px-6 py-4 text-center"><div className="flex justify-center gap-2"><button onClick={() => {setCurrentStation(s); setShowForm(true);}} className="text-blue-600"><Edit2 size={16}/></button><button onClick={() => confirmDelete(s.id)} className="text-red-600"><Trash2 size={16}/></button></div></td></tr>)}</tbody>
                  </table>
              </div>
          </div>
      )}
    </div>
  );
};

export default FuelManagement;

