import React, { useState, useEffect } from 'react';
import { GasStation, RefuelingLog, Vehicle, FuelType, ContractType, UserRole, FUEL_TYPES_LIST, SUPPLY_TYPES_LIST, RefuelingItem } from '../types';
import { storageService } from '../services/storage';
import PasswordModal from './PasswordModal';
import { useAuth } from '../contexts/AuthContext';
import { 
  Fuel, Plus, Save, Trash2, Edit2, Droplet, Filter, X, Calendar, Printer, AlertCircle, Users, ChevronDown, ChevronUp, MapPin, Clock, ClipboardList, ChevronLeft, ChevronRight, Loader2, ShoppingCart, Package, DollarSign, Receipt
} from 'lucide-react';
import { PrintHeader } from './PrintHeader';
import MultiSelect, { MultiSelectOption } from './MultiSelect';
import SelectWithSearch from './SelectWithSearch';
import { ParisLogo } from './ParisLogo';

type TabType = 'REFUELING' | 'STATIONS';

const EXTERNAL_EQUIPMENT_TYPES = [
  'BARCO', 'BALSA', 'MOTO', 'CARRO', 'LANCHA', 'MOTOR DE POUPA', 'MOTOPODA', 'GERADOR', 'GALÃO', 'TAMBOR'
];

const ITEMS_PER_PAGE = 50;

interface RefuelingCartItem {
    id: string;
    fuelType: FuelType;
    liters: number;
    totalCost: number;
}

const FuelManagement: React.FC = () => {
  const { user } = useAuth();
  const isReadOnly = user?.role === UserRole.GERENCIA;

  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<TabType>('REFUELING');

  const [stations, setStations] = useState<GasStation[]>([]);
  const [refuelings, setRefuelings] = useState<RefuelingLog[]>([]);
  const [vehicles, setVehicles] = useState<Vehicle[]>([]);

  const [currentPage, setCurrentPage] = useState(1);

  const [filterDateStart, setFilterDateStart] = useState('');
  const [filterDateEnd, setFilterDateEnd] = useState('');
  const [filterPlate, setFilterPlate] = useState<string[]>([]);
  const [filterStation, setFilterStation] = useState<string[]>([]);
  const [filterContract, setFilterContract] = useState<string[]>([]);
  const [filterMunicipality, setFilterMunicipality] = useState<string[]>([]);
  const [filterFuel, setFilterFuel] = useState<string[]>([]);
  const [filterForeman, setFilterForeman] = useState<string[]>([]);

  const [showFilters, setShowFilters] = useState(false);

  const [uniquePlates, setUniquePlates] = useState<string[]>([]);
  const [uniqueContracts, setUniqueContracts] = useState<string[]>([]);
  const [uniqueMunicipalities, setUniqueMunicipalities] = useState<string[]>([]);
  const [uniqueForemen, setUniqueForemen] = useState<string[]>([]);

  const [showForm, setShowForm] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editingRecordId, setEditingRecordId] = useState<string | null>(null);

  const [currentStation, setCurrentStation] = useState<Partial<GasStation>>({});
  const [selectedTicket, setSelectedTicket] = useState<RefuelingLog | null>(null);

  const getTodayLocal = () => {
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const getCurrentTime = () => {
    const now = new Date();
    return now.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
  };

  const [refuelingHeader, setRefuelingHeader] = useState({
      date: getTodayLocal(),
      time: getCurrentTime(),
      vehicleId: '',
      gasStationId: '',
      foremanSnapshot: '',
      invoiceNumber: '',
      requisitionNumber: ''
  });

  const [cartItems, setCartItems] = useState<RefuelingCartItem[]>([]);
  const [currentItem, setCurrentItem] = useState<Partial<RefuelingCartItem>>({
      fuelType: '' as any,
      liters: 0,
      totalCost: 0
  });

  const [isExternal, setIsExternal] = useState(false);
  const [externalData, setExternalData] = useState({
    identifier: '', 
    model: '',
    contract: '',
    municipality: '',
    description: ''
  });

  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    try {
      const [sData, rData, vData] = await Promise.all([
          storageService.getGasStations(),
          storageService.getRefuelings(),
          storageService.getVehicles()
      ]);

      setStations(sData);
      setRefuelings(rData);
      setVehicles(vData);

      const plates = Array.from(new Set(rData.map(r => r.plateSnapshot))).sort();
      const contracts = Array.from(new Set(rData.map(r => r.contractSnapshot))).sort();
      const cities = Array.from(new Set(rData.map(r => r.municipalitySnapshot))).sort();
      const vehicleTeams = Array.from(new Set(vData.map(v => v.foreman).filter(f => f && f.trim() !== ''))).sort();

      setUniquePlates(plates);
      setUniqueContracts(contracts);
      setUniqueMunicipalities(cities);
      setUniqueForemen(vehicleTeams);
    } catch (e) {
        console.error(e);
    } finally {
        setLoading(false);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const getFuelColor = (fuelType: string) => {
    if (fuelType === FuelType.OUTROS || fuelType.includes('DIVERSOS')) return 'bg-purple-100 text-purple-800 border-purple-200';
    switch (fuelType) {
      case FuelType.GASOLINA: return 'bg-orange-100 text-orange-800 border-orange-200'; 
      case FuelType.ETANOL: return 'bg-green-100 text-green-800 border-green-200';
      case FuelType.DIESEL: return 'bg-yellow-100 text-yellow-800 border-yellow-200';
      case FuelType.DIESEL_S10: return 'bg-slate-100 text-slate-800 border-slate-200';
      default: return 'bg-gray-100 text-gray-800 border-gray-200';
    }
  };

  const handleAddItemToCart = () => {
      if (!currentItem.fuelType) {
          alert("Selecione o produto.");
          return;
      }

      const qty = Number(currentItem.liters || 0);
      const cost = Number(currentItem.totalCost || 0);

      if (qty <= 0 && cost <= 0) {
          alert("Informe a quantidade ou o valor.");
          return;
      }

      const newItem: RefuelingCartItem = {
          id: crypto.randomUUID(),
          fuelType: currentItem.fuelType as FuelType,
          liters: qty,
          totalCost: cost
      };

      setCartItems(prev => [...prev, newItem]);
      setCurrentItem({ fuelType: '' as any, liters: 0, totalCost: 0 });
  };

  const handleUpdateCartItem = (id: string, field: 'liters' | 'totalCost', value: string) => {
      const numValue = value === '' ? 0 : Number(value);
      setCartItems(prev => prev.map(item => 
          item.id === id ? { ...item, [field]: numValue } : item
      ));
  };

  const handleRemoveItemFromCart = (id: string) => {
      setCartItems(prev => prev.filter(item => item.id !== id));
  };

  const handleSaveStation = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly) return;
    if (!currentStation.name || !currentStation.municipality) return;

    const newStation: GasStation = {
      id: currentStation.id || crypto.randomUUID(),
      name: currentStation.name.toUpperCase(),
      cnpj: currentStation.cnpj ? currentStation.cnpj.toUpperCase() : '',
      municipality: currentStation.municipality.toUpperCase(),
      phone: currentStation.phone || '',
      address: currentStation.address ? currentStation.address.toUpperCase() : ''
    };

    setLoading(true);
    try {
        await storageService.saveGasStation(newStation);
        await loadData();
        resetForms();
    } catch (err: any) {
        alert(`Erro ao salvar posto: ${err.message}`);
    } finally {
        setLoading(false);
    }
  };

  const handleSaveRefueling = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly) return;

    if (!refuelingHeader.gasStationId) {
        alert("Selecione o posto.");
        return;
    }

    if (cartItems.length === 0) {
        alert("Adicione pelo menos um item à lista.");
        return;
    }

    let snapshotData = {
        plate: '', model: '', contract: '', municipality: '', foreman: refuelingHeader.foremanSnapshot || ''
    };

    let vehicleIdToSave = '';

    if (isExternal) {
        if (!externalData.identifier || !externalData.contract || !externalData.municipality) {
            alert("Preencha Identificação, Contrato e Município.");
            return;
        }
        snapshotData.plate = externalData.identifier.toUpperCase();
        snapshotData.model = externalData.model ? externalData.model.toUpperCase() : '';
        snapshotData.contract = externalData.contract;
        snapshotData.municipality = externalData.municipality.toUpperCase();
        vehicleIdToSave = 'EXTERNAL';
    } else {
        if (!refuelingHeader.vehicleId) {
            alert("Selecione o veículo.");
            return;
        }
        const vehicle = vehicles.find(v => v.id === refuelingHeader.vehicleId);
        if (!vehicle) return;

        snapshotData.plate = vehicle.plate;
        snapshotData.model = vehicle.model || '';
        snapshotData.contract = vehicle.contract;
        snapshotData.municipality = vehicle.municipality;
        if (!snapshotData.foreman) snapshotData.foreman = vehicle.foreman;
        vehicleIdToSave = refuelingHeader.vehicleId;
    }

    setLoading(true);
    try {
        // Consolidação
        const totalLiters = cartItems.reduce((acc, curr) => {
            return FUEL_TYPES_LIST.includes(curr.fuelType) ? acc + Number(curr.liters || 0) : acc;
        }, 0);
        const totalCost = cartItems.reduce((acc, curr) => acc + Number(curr.totalCost || 0), 0);
        const mainFuelType = cartItems.length > 1 ? FuelType.OUTROS : cartItems[0].fuelType;

        const summary = cartItems.map(i => `${i.fuelType}: ${i.liters}`).join(' | ');
        const obs = isExternal && externalData.description ? externalData.description.toUpperCase() : '';

        const newRefueling: RefuelingLog = {
            id: editingRecordId || crypto.randomUUID(),
            date: refuelingHeader.date,
            vehicleId: vehicleIdToSave,
            gasStationId: refuelingHeader.gasStationId,
            fuelType: mainFuelType, 
            liters: Number(totalLiters.toFixed(2)), 
            totalCost: Number(totalCost.toFixed(2)), 
            items: cartItems.map(i => ({ fuelType: i.fuelType, liters: i.liters, totalCost: i.totalCost })),
            invoiceNumber: refuelingHeader.invoiceNumber?.toUpperCase() || '',
            requisitionNumber: refuelingHeader.requisitionNumber?.toUpperCase() || '',
            time: refuelingHeader.time || '', 
            plateSnapshot: snapshotData.plate,
            modelSnapshot: snapshotData.model,
            foremanSnapshot: snapshotData.foreman, 
            contractSnapshot: snapshotData.contract,
            municipalitySnapshot: snapshotData.municipality,
            observation: `[ITENS: ${summary}] ${obs}`.trim()
        };

        await storageService.saveRefueling(newRefueling);
        await loadData();
        resetForms();
        alert("Abastecimento consolidado salvo!");
    } catch (err: any) {
        alert(`Erro ao salvar: ${err.message}`);
    } finally {
        setLoading(false);
    }
  };

  const handleEditRefueling = (refueling: RefuelingLog) => {
    if (isReadOnly) return;
    setRefuelingHeader({
        date: refueling.date,
        time: refueling.time || '',
        vehicleId: refueling.vehicleId,
        gasStationId: refueling.gasStationId,
        foremanSnapshot: refueling.foremanSnapshot || '',
        invoiceNumber: refueling.invoiceNumber || '',
        requisitionNumber: refueling.requisitionNumber || ''
    });
    setEditingRecordId(refueling.id);

    const initialItems: RefuelingCartItem[] = (refueling.items && refueling.items.length > 0)
        ? refueling.items.map(i => ({ ...i, id: crypto.randomUUID() }))
        : [{ id: crypto.randomUUID(), fuelType: refueling.fuelType, liters: refueling.liters, totalCost: refueling.totalCost }];

    setCartItems(initialItems);
    setIsExternal(refueling.vehicleId === 'EXTERNAL');

    if (refueling.vehicleId === 'EXTERNAL') {
        const cleanObs = refueling.observation?.includes('] ') ? refueling.observation.split('] ')[1] : refueling.observation;
        setExternalData({
            identifier: refueling.plateSnapshot,
            model: refueling.modelSnapshot,
            contract: refueling.contractSnapshot,
            municipality: refueling.municipalitySnapshot,
            description: cleanObs || ''
        });
    }

    setIsEditing(true);
    setShowForm(true);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const resetForms = () => {
    setShowForm(false);
    setIsEditing(false);
    setEditingRecordId(null);
    setRefuelingHeader({
      date: getTodayLocal(),
      time: getCurrentTime(),
      vehicleId: '',
      gasStationId: '',
      foremanSnapshot: '',
      invoiceNumber: '',
      requisitionNumber: ''
    });
    setCartItems([]);
    setIsExternal(false);
  };

  const filteredRefuelings = refuelings.filter(r => {
      const rDate = new Date(r.date).getTime();
      const start = filterDateStart ? new Date(filterDateStart).getTime() : null;
      const end = filterDateEnd ? new Date(filterDateEnd).getTime() : null;
      const matchesDate = (!start || rDate >= start) && (!end || rDate <= end);
      const matchesPlate = filterPlate.length === 0 || filterPlate.includes(r.plateSnapshot);
      const matchesStation = filterStation.length === 0 || filterStation.includes(r.gasStationId);
      const matchesFuel = filterFuel.length === 0 || filterFuel.includes(r.fuelType);
      return matchesDate && matchesPlate && matchesStation && matchesFuel;
  }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  const totalLitersCalculated = filteredRefuelings.reduce((acc, curr) => acc + (curr.liters || 0), 0);
  const totalCostCalculated = filteredRefuelings.reduce((acc, curr) => acc + (curr.totalCost || 0), 0);

  const inputClass = "w-full rounded-lg border border-slate-300 bg-slate-50 p-2.5 text-slate-800 focus:border-blue-600 outline-none transition-all";
  const selectClass = "w-full rounded-lg border border-slate-300 bg-white p-2 text-slate-700 focus:border-blue-600 outline-none h-[42px] shadow-sm";

  return (
    <div className="space-y-6">
      <PrintHeader title="Abastecimentos" />

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 print:hidden">
        <div>
          <h1 className="text-2xl font-bold flex items-center gap-2"><Fuel className="text-blue-600" /> Abastecimento</h1>
          <p className="text-slate-500 text-sm">Controle consolidado de combustível e insumos.</p>
        </div>
        <div className="flex gap-2 w-full md:w-auto">
            <button onClick={() => { resetForms(); setShowForm(!showForm); }} className="flex-1 md:flex-none bg-blue-600 text-white px-6 py-2 rounded-lg font-bold flex items-center justify-center gap-2">
                {showForm ? <X size={18} /> : <Plus size={18} />} {showForm ? 'Cancelar' : 'Novo Registro'}
            </button>
            <button onClick={handlePrint} className="bg-white border px-4 py-2 rounded-lg font-bold flex items-center gap-2"><Printer size={18}/> Imprimir</button>
        </div>
      </div>

      <div className="flex border-b print:hidden">
        <button onClick={() => { setActiveTab('REFUELING'); resetForms(); }} className={`px-6 py-2 font-bold transition-all ${activeTab === 'REFUELING' ? 'border-b-2 border-blue-600 text-blue-600' : 'text-slate-500'}`}>Registros</button>
        <button onClick={() => { setActiveTab('STATIONS'); resetForms(); }} className={`px-6 py-2 font-bold transition-all ${activeTab === 'STATIONS' ? 'border-b-2 border-blue-600 text-blue-600' : 'text-slate-500'}`}>Postos</button>
      </div>

      {activeTab === 'REFUELING' && (
        <div className="space-y-6">
            {showForm && !isReadOnly && (
                <div className="bg-white p-6 rounded-xl shadow-lg border animate-in fade-in print:hidden">
                    <h3 className="font-bold text-lg mb-6 flex items-center gap-2 text-slate-800 border-b pb-2">
                        <Droplet size={20} className="text-blue-500" /> 
                        {isEditing ? 'Editar Registro' : 'Novo Abastecimento Consolidado'}
                    </h3>

                    <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-8 bg-slate-50 p-4 rounded-lg border">
                        <div className="md:col-span-4 flex items-center gap-2 mb-2">
                            <input type="checkbox" checked={isExternal} onChange={e => setIsExternal(e.target.checked)} id="ext" className="w-5 h-5 accent-blue-600" />
                            <label htmlFor="ext" className="text-sm font-bold text-slate-700">Equipamento Externo / Não Cadastrado</label>
                        </div>

                        <div><label className="block text-[10px] font-bold uppercase text-slate-500 mb-1">Data</label><input type="date" required value={refuelingHeader.date} onChange={e => setRefuelingHeader({...refuelingHeader, date: e.target.value})} className={inputClass} /></div>
                        <div><label className="block text-[10px] font-bold uppercase text-slate-500 mb-1">Hora</label><input type="time" value={refuelingHeader.time} onChange={e => setRefuelingHeader({...refuelingHeader, time: e.target.value})} className={inputClass} /></div>

                        {isExternal ? (
                            <>
                                <div><label className="block text-[10px] font-bold uppercase text-slate-500 mb-1">Identificação</label><select value={externalData.identifier} onChange={e => setExternalData({...externalData, identifier: e.target.value})} className={inputClass}><option value="">Selecione...</option>{EXTERNAL_EQUIPMENT_TYPES.map(t => <option key={t} value={t}>{t}</option>)}</select></div>
                                <div><label className="block text-[10px] font-bold uppercase text-slate-500 mb-1">Contrato</label><select value={externalData.contract} onChange={e => setExternalData({...externalData, contract: e.target.value})} className={inputClass}><option value="">Selecione...</option>{Object.values(ContractType).map(c => <option key={c} value={c}>{c}</option>)}</select></div>
                            </>
                        ) : (
                            <div className="md:col-span-2"><SelectWithSearch label="Veículo" options={vehicles.map(v => ({value: v.id, label: v.plate}))} value={refuelingHeader.vehicleId || ''} onChange={val => setRefuelingHeader({...refuelingHeader, vehicleId: val})} /></div>
                        )}

                        <div className="md:col-span-2"><SelectWithSearch label="Posto Conveniado" options={stations.map(s => ({value: s.id, label: `${s.name} (${s.municipality})`}))} value={refuelingHeader.gasStationId || ''} onChange={val => setRefuelingHeader({...refuelingHeader, gasStationId: val})} /></div>
                        <div><label className="block text-[10px] font-bold uppercase text-slate-500 mb-1">NF</label><input type="text" value={refuelingHeader.invoiceNumber} onChange={e => setRefuelingHeader({...refuelingHeader, invoiceNumber: e.target.value})} className={inputClass} /></div>
                        <div><label className="block text-[10px] font-bold uppercase text-slate-500 mb-1">Requisição</label><input type="text" value={refuelingHeader.requisitionNumber} onChange={e => setRefuelingHeader({...refuelingHeader, requisitionNumber: e.target.value})} className={inputClass} /></div>
                    </div>

                    <div className="bg-blue-50 p-4 rounded-xl border border-blue-200 mb-6">
                        <div className="flex items-center gap-2 mb-4 text-blue-700 font-bold"><Package size={18} /> Adicionar Itens ao Registro</div>
                        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
                            <div className="md:col-span-1">
                                <label className="block text-[10px] font-bold uppercase text-slate-500 mb-1">Produto</label>
                                <select value={currentItem.fuelType || ''} onChange={e => setCurrentItem({...currentItem, fuelType: e.target.value as FuelType})} className={selectClass}>
                                    <option value="">Selecione...</option>
                                    <optgroup label="COMBUSTÍVEIS">{FUEL_TYPES_LIST.map(f => <option key={f} value={f}>{f}</option>)}</optgroup>
                                    <optgroup label="INSUMOS">{SUPPLY_TYPES_LIST.map(f => <option key={f} value={f}>{f}</option>)}</optgroup>
                                </select>
                            </div>
                            <div><label className="block text-[10px] font-bold uppercase text-slate-500 mb-1">Qtd (L/un)</label><input type="number" step="0.01" value={currentItem.liters || ''} onChange={e => setCurrentItem({...currentItem, liters: Number(e.target.value)})} className={inputClass} /></div>
                            <div><label className="block text-[10px] font-bold uppercase text-slate-500 mb-1">Valor Total (R$)</label><input type="number" step="0.01" value={currentItem.totalCost || ''} onChange={e => setCurrentItem({...currentItem, totalCost: Number(e.target.value)})} className={inputClass} /></div>
                            <button type="button" onClick={handleAddItemToCart} className="bg-slate-800 text-white px-4 py-2.5 rounded-lg font-bold hover:bg-slate-900 transition-all flex items-center justify-center gap-2 h-[44px]"><Plus size={18} /> Incluir Item</button>
                        </div>
                    </div>

                    <div className="mb-8 overflow-hidden rounded-xl border">
                        <table className="w-full text-sm">
                            <thead className="bg-slate-100 text-slate-600 font-bold uppercase text-[10px]"><tr><th className="px-4 py-2 text-left">Item</th><th className="px-4 py-2 text-center">Quantidade</th><th className="px-4 py-2 text-right">Valor</th><th className="px-4 py-2 text-center">Ações</th></tr></thead>
                            <tbody className="divide-y">
                                {cartItems.map(item => (
                                    <tr key={item.id} className="hover:bg-slate-50">
                                        <td className="px-4 py-2 font-bold">{item.fuelType}</td>
                                        <td className="px-4 py-2 text-center font-mono">{item.liters.toFixed(2)}</td>
                                        <td className="px-4 py-2 text-right font-bold text-green-700">R$ {item.totalCost.toFixed(2)}</td>
                                        <td className="px-4 py-2 text-center"><button onClick={() => handleRemoveItemFromCart(item.id)} className="text-red-500 p-1 hover:bg-red-50 rounded"><Trash2 size={16} /></button></td>
                                    </tr>
                                ))}
                                {cartItems.length === 0 && <tr><td colSpan={4} className="p-4 text-center text-slate-400 italic">Nenhum item adicionado.</td></tr>}
                            </tbody>
                            <tfoot className="bg-slate-50 font-bold">
                                <tr><td colSpan={2} className="px-4 py-3 text-right">TOTAIS:</td><td className="px-4 py-3 text-right text-blue-700 text-lg">R$ {cartItems.reduce((a,c) => a + c.totalCost, 0).toFixed(2)}</td><td></td></tr>
                            </tfoot>
                        </table>
                    </div>

                    <div className="flex justify-end gap-3 pt-4 border-t">
                        <button type="button" onClick={resetForms} className="px-6 py-2 text-slate-500 font-bold">Descartar</button>
                        <button onClick={handleSaveRefueling} disabled={loading || cartItems.length === 0} className="bg-green-600 text-white px-10 py-3 rounded-lg font-bold flex items-center gap-2 shadow-lg hover:bg-green-700 transform active:scale-95 transition-all">
                            {loading ? <Loader2 className="animate-spin" /> : <Save size={18}/>} SALVAR TUDO
                        </button>
                    </div>
                </div>
            )}

            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 print:hidden">
                <div className="bg-white p-3 rounded-lg border"><p className="text-[10px] font-bold text-slate-500 uppercase">Litros Totais</p><p className="text-xl font-bold">{totalLitersCalculated.toFixed(2)} L</p></div>
                <div className="bg-white p-3 rounded-lg border"><p className="text-[10px] font-bold text-slate-500 uppercase">Valor Total</p><p className="text-xl font-bold text-green-600">R$ {totalCostCalculated.toFixed(2)}</p></div>
            </div>

            <div className="bg-white rounded-xl shadow overflow-hidden">
                <table className="w-full text-sm text-left">
                    <thead className="bg-slate-100 font-bold text-slate-600 uppercase text-xs">
                        <tr><th className="px-6 py-3">Data / Hora</th><th className="px-6 py-3">Veículo</th><th className="px-6 py-3">Posto</th><th className="px-6 py-3">Combustível</th><th className="px-6 py-3">Litros</th><th className="px-6 py-3">Valor</th><th className="px-6 py-3 text-center print:hidden">Ações</th></tr>
                    </thead>
                    <tbody className="divide-y">
                        {filteredRefuelings.map(r => {
                            const isDiverse = r.items && r.items.length > 1;
                            return (
                            <tr key={r.id} className="hover:bg-slate-50">
                                <td className="px-6 py-4">{r.date.split('-').reverse().join('/')} <div className="text-[10px] text-slate-400">{r.time}</div></td>
                                <td className="px-6 py-4 font-bold">{r.plateSnapshot}</td>
                                <td className="px-6 py-4">{stations.find(s => s.id === r.gasStationId)?.name}</td>
                                <td className="px-6 py-4"><span className={`px-2 py-1 rounded text-[10px] font-bold ${getFuelColor(r.fuelType)}`}>{isDiverse ? `DIVERSOS (${r.items?.length})` : r.fuelType}</span></td>
                                <td className="px-6 py-4 font-mono">{r.liters.toFixed(2)} L</td>
                                <td className="px-6 py-4 font-bold text-green-700">R$ {r.totalCost.toFixed(2)}</td>
                                <td className="px-6 py-4 text-center print:hidden">
                                    <div className="flex justify-center gap-2">
                                        <button onClick={() => handleEditRefueling(r)} className="text-blue-600 p-2 hover:bg-blue-50 rounded"><Edit2 size={16}/></button>
                                        <button onClick={() => { setItemToDelete(r.id); setShowDeleteModal(true); }} className="text-red-600 p-2 hover:bg-red-50 rounded"><Trash2 size={16}/></button>
                                    </div>
                                </td>
                            </tr>
                        )})}
                    </tbody>
                </table>
            </div>
        </div>
      )}

      {activeTab === 'STATIONS' && (
          <div className="space-y-4">
              {showForm && (
                  <form onSubmit={handleSaveStation} className="bg-white p-6 rounded-xl border grid grid-cols-1 md:grid-cols-2 gap-4 animate-in slide-in-from-top-2">
                      <div className="md:col-span-2"><label className="block text-xs font-bold uppercase text-slate-500 mb-1">Nome</label><input type="text" required value={currentStation.name || ''} onChange={e => setCurrentStation({...currentStation, name: e.target.value.toUpperCase()})} className={inputClass} /></div>
                      <div><label className="block text-xs font-bold uppercase text-slate-500 mb-1">Município</label><input type="text" required value={currentStation.municipality || ''} onChange={e => setCurrentStation({...currentStation, municipality: e.target.value.toUpperCase()})} className={inputClass} /></div>
                      <div><label className="block text-xs font-bold uppercase text-slate-500 mb-1">CNPJ</label><input type="text" value={currentStation.cnpj || ''} onChange={e => setCurrentStation({...currentStation, cnpj: e.target.value})} className={inputClass} /></div>
                      <div className="md:col-span-2 flex justify-end gap-2 pt-4"><button type="submit" className="bg-blue-600 text-white px-6 py-2 rounded-lg font-bold">Salvar Posto</button></div>
                  </form>
              )}
              <div className="bg-white rounded-xl shadow overflow-hidden">
                  <table className="w-full text-sm text-left">
                      <thead className="bg-slate-100 font-bold text-slate-600 uppercase text-xs"><tr><th className="px-6 py-3">Nome</th><th className="px-6 py-3">Município</th><th className="px-6 py-3 text-center">Ações</th></tr></thead>
                      <tbody className="divide-y">{stations.map(s => <tr key={s.id} className="hover:bg-slate-50"><td className="px-6 py-4 font-bold">{s.name}</td><td className="px-6 py-4 flex items-center gap-1"><MapPin size={14} className="text-slate-400"/> {s.municipality}</td><td className="px-6 py-4 text-center"><div className="flex justify-center gap-2"><button onClick={() => {setCurrentStation(s); setShowForm(true);}} className="text-blue-600 p-2 hover:bg-blue-50 rounded"><Edit2 size={16}/></button></div></td></tr>)}</tbody>
                  </table>
              </div>
          </div>
      )}

      <PasswordModal isOpen={showDeleteModal} onClose={() => setShowDeleteModal(false)} onConfirm={async () => {
          if (itemToDelete) {
              setLoading(true);
              try {
                  if (activeTab === 'STATIONS') await storageService.deleteGasStation(itemToDelete);
                  else await storageService.deleteRefueling(itemToDelete);
                  await loadData();
                  setShowDeleteModal(false);
                  setItemToDelete(null);
              } catch (e) { alert("Erro ao excluir."); } finally { setLoading(false); }
          }
      }} title="Excluir Registro" />
    </div>
  );
};

export default FuelManagement;

export enum ContractType {
  MANUTENCAO = 'MANUTENÇÃO',
  LINHA_VIVA = 'LINHA VIVA',
  PLPT = 'PLPT',
  ADM_MANAUS = 'ADM_MANAUS',
  ADM_PIN = 'ADM_PIN',
  CTRNOVO = 'CTRNOVO',
  AME = 'AME',
  OFICINA = 'OFICINA',
  TRAVESSIA_SUBAQUATICA = 'TRAVESSIA SUBAQUÁTICA'
}

export enum VehicleType {
  CAMINHAO = 'CAMINHÃO',
  LINHA_VIVA = 'LINHA VIVA',
  STRADA_CABINE_SIMPLES = 'STRADA CABINE SIMPLES',
  STRADA_CABINE_DUPLA = 'STRADA CABINE DUPLA',
  PICK_UP = 'PICK-UP'
}

export enum UserRole {
  ADMIN = 'ADMIN',       
  GESTOR = 'GESTOR',     
  OPERADOR = 'OPERADOR', 
  FINANCEIRO = 'FINANCEIRO', 
  RH = 'RH',              
  GERENCIA = 'GERENCIA',   
  ENCARREGADO = 'ENCARREGADO' 
}

export interface UserProfile {
  id: string;
  email: string;
  role: UserRole;
  name?: string; 
}

export interface Vehicle {
  id: string;
  contract: ContractType;
  plate: string;
  model?: string; 
  year?: string;  
  driverName: string;
  municipality: string;
  foreman: string; 
  type: VehicleType;
  status?: 'ATIVO' | 'INATIVO';
}

export interface DailyLog {
  id: string;
  date: string;
  vehicleId: string;
  firstIgnition: string; 
  startTime: string; 
  lunchStart: string; 
  lunchEnd: string; 
  endTime: string; 
  kmDriven: number;
  maxSpeed: number;
  speedingCount: number; 
  observations: string;
  extraTimeStart: string; 
  extraTimeEnd: string; 
  historicalPlate?: string; 
  historicalModel?: string; 
  historicalDriver?: string;
  historicalMunicipality?: string;
  historicalContract?: string;
  nonOperatingReason?: string; 
  kmBeforeRefueling?: number; 
}

export interface DailyLogReport extends DailyLog {
  vehicle: Vehicle;
  calculatedHours: string;
  lastRefuelingInfo?: {
    date: string;
    liters: number;
    kmSince: number;
  };
}

export interface GasStation {
  id: string;
  name: string;
  cnpj: string;
  municipality: string;
  phone?: string;
  address?: string; 
}

export enum FuelType {
  GASOLINA = 'GASOLINA',
  DIESEL = 'DIESEL',
  DIESEL_S10 = 'DIESEL S10',
  ETANOL = 'ETANOL',
  ARLA_32 = 'ARLA 32',
  OLEO_MOTOR = 'ÓLEO MOTOR',
  OLEO_HIDRAULICO = 'ÓLEO HIDRÁULICO',
  OLEO_TRANSMISSAO = 'ÓLEO TRANSMISSÃO',
  OLEO_2T = 'ÓLEO 2T',
  GRAXA = 'GRAXA',
  ADITIVO = 'ADITIVO RADIADOR',
  OUTROS = 'OUTROS'
}

export const FUEL_TYPES_LIST = [
  FuelType.GASOLINA,
  FuelType.DIESEL,
  FuelType.DIESEL_S10,
  FuelType.ETANOL
];

export const SUPPLY_TYPES_LIST = Object.values(FuelType).filter(t => !FUEL_TYPES_LIST.includes(t));

export interface RefuelingItem {
    fuelType: FuelType;
    liters: number;
    totalCost: number;
}

export interface RefuelingLog {
  id: string;
  date: string;
  vehicleId: string;
  gasStationId: string;
  fuelType: FuelType;
  liters: number;
  totalCost: number;
  items?: RefuelingItem[];
  invoiceNumber?: string; 
  requisitionNumber?: string; 
  plateSnapshot: string;
  modelSnapshot: string;
  foremanSnapshot: string; 
  contractSnapshot: string;
  municipalitySnapshot: string;
  observation?: string; 
  time?: string; 
}

export enum RequisitionStatus {
  PENDING = 'PENDENTE',
  APPROVED = 'APROVADA',
  REJECTED = 'RECUSADA'
}

export interface UserVehicle {
  id: string;
  userId: string;
  vehicleId: string;
}

export interface Requisition {
  id: string;
  internalId: number; 
  externalId?: string; 
  date: string; 
  requestTime: string; 
  requesterId: string;
  requesterName?: string; 
  vehicleId: string; 
  externalType?: string; 
  externalPlate?: string;
  fuelType: FuelType;
  liters: number;
  isFullTank?: boolean; 
  observation?: string;
  municipality: string; 
  status: RequisitionStatus;
  approvedBy?: string; 
  approvalDate?: string;
  gasStationId?: string;
}

import React, { useState, useEffect } from 'react';
import { GasStation, RefuelingLog, Vehicle, FuelType, ContractType, UserRole, UserProfile, FUEL_TYPES_LIST, SUPPLY_TYPES_LIST, RefuelingItem } from './types';
import { storageService } from './services/storage';
import PasswordModal from './components/PasswordModal';
import { useAuth } from './contexts/AuthContext';
import { 
  Fuel, Plus, Save, Trash2, Edit2, Droplet, Filter, X, Calendar, Printer, AlertCircle, Users, ChevronDown, ChevronUp, MapPin, Clock, ClipboardList, ChevronLeft, ChevronRight, Loader2, ShoppingCart, Package, DollarSign, Receipt
} from 'lucide-react';
import { PrintHeader } from './components/PrintHeader';
import MultiSelect, { MultiSelectOption } from './components/MultiSelect';
import SelectWithSearch from './components/SelectWithSearch';
import { ParisLogo } from './components/ParisLogo';

type TabType = 'REFUELING' | 'STATIONS';

const EXTERNAL_EQUIPMENT_TYPES = [
  'BARCO', 
  'BALSA', 
  'MOTO', 
  'CARRO',
  'LANCHA', 
  'MOTOR DE POUPA',
  'MOTOPODA', 
  'GERADOR', 
  'GALÃO', 
  'TAMBOR'
];

const ITEMS_PER_PAGE = 50;

interface RefuelingCartItem {
    id: string;
    fuelType: FuelType;
    liters: number;
    totalCost: number;
}

const FuelManagement: React.FC = () => {
  const { user } = useAuth();
  const isReadOnly = user?.role === UserRole.GERENCIA;

  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<TabType>('REFUELING');

  const [stations, setStations] = useState<GasStation[]>([]);
  const [refuelings, setRefuelings] = useState<RefuelingLog[]>([]);
  const [vehicles, setVehicles] = useState<Vehicle[]>([]);

  const [currentPage, setCurrentPage] = useState(1);

  const [filterDateStart, setFilterDateStart] = useState('');
  const [filterDateEnd, setFilterDateEnd] = useState('');
  const [filterPlate, setFilterPlate] = useState<string[]>([]);
  const [filterStation, setFilterStation] = useState<string[]>([]);
  const [filterContract, setFilterContract] = useState<string[]>([]);
  const [filterMunicipality, setFilterMunicipality] = useState<string[]>([]);
  const [filterFuel, setFilterFuel] = useState<string[]>([]);
  const [filterForeman, setFilterForeman] = useState<string[]>([]);

  const [showFilters, setShowFilters] = useState(false);

  const [uniquePlates, setUniquePlates] = useState<string[]>([]);
  const [uniqueContracts, setUniqueContracts] = useState<string[]>([]);
  const [uniqueMunicipalities, setUniqueMunicipalities] = useState<string[]>([]);
  const [uniqueForemen, setUniqueForemen] = useState<string[]>([]);

  const [showForm, setShowForm] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editingRecordId, setEditingRecordId] = useState<string | null>(null);

  const [currentStation, setCurrentStation] = useState<Partial<GasStation>>({});

  // Ticket State
  const [selectedTicket, setSelectedTicket] = useState<RefuelingLog | null>(null);

  const getTodayLocal = () => {
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const getCurrentTime = () => {
    const now = new Date();
    return now.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
  };

  // Refueling Form States
  const [refuelingHeader, setRefuelingHeader] = useState({
      date: getTodayLocal(),
      time: getCurrentTime(),
      vehicleId: '',
      gasStationId: '',
      foremanSnapshot: '',
      invoiceNumber: '',
      requisitionNumber: ''
  });

  const [cartItems, setCartItems] = useState<RefuelingCartItem[]>([]);
  const [currentItem, setCurrentItem] = useState<Partial<RefuelingCartItem>>({
      fuelType: '' as any,
      liters: 0,
      totalCost: 0
  });

  const [isExternal, setIsExternal] = useState(false);
  const [externalData, setExternalData] = useState({
    identifier: '', 
    model: '',
    contract: '',
    municipality: '',
    description: '' 
  });

  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);

  useEffect(() => {
    loadData();
  }, []);

  useEffect(() => {
    setCurrentPage(1);
  }, [filterDateStart, filterDateEnd, filterPlate, filterStation, filterContract, filterMunicipality, filterFuel, filterForeman]);

  const loadData = async () => {
    setLoading(true);
    try {
      const [sData, rData, vData] = await Promise.all([
          storageService.getGasStations(),
          storageService.getRefuelings(),
          storageService.getVehicles()
      ]);

      setStations(sData);
      setRefuelings(rData);
      setVehicles(vData);

      const plates = Array.from(new Set(rData.map(r => r.plateSnapshot))).sort();
      const contracts = Array.from(new Set(rData.map(r => r.contractSnapshot))).sort();
      const cities = Array.from(new Set(rData.map(r => r.municipalitySnapshot))).sort();
      const vehicleTeams = Array.from(new Set(vData.map(v => v.foreman).filter(f => f && f.trim() !== ''))).sort();

      setUniquePlates(plates);
      setUniqueContracts(contracts);
      setUniqueMunicipalities(cities);
      setUniqueForemen(vehicleTeams);
    } catch (e) {
        console.error(e);
    } finally {
        setLoading(false);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const getFuelColor = (fuelType: string) => {
    if (fuelType === FuelType.OUTROS || fuelType.includes('DIVERSOS')) return 'bg-purple-100 text-purple-800 border-purple-200';
    switch (fuelType) {
      case FuelType.GASOLINA: return 'bg-orange-100 text-orange-800 border-orange-200'; 
      case FuelType.ETANOL: return 'bg-green-100 text-green-800 border-green-200';
      case FuelType.DIESEL: return 'bg-yellow-100 text-yellow-800 border-yellow-200';
      case FuelType.DIESEL_S10: return 'bg-slate-100 text-slate-800 border-slate-200';
      default: return 'bg-gray-100 text-gray-800 border-gray-200';
    }
  };

  const handleAddItemToCart = () => {
      if (!currentItem.fuelType) {
          alert("Selecione o item/combustível.");
          return;
      }

      const qty = Number(currentItem.liters || 0);
      const cost = Number(currentItem.totalCost || 0);

      const newItem: RefuelingCartItem = {
          id: crypto.randomUUID(),
          fuelType: currentItem.fuelType as FuelType,
          liters: qty,
          totalCost: cost
      };

      setCartItems(prev => [...prev, newItem]);
      setCurrentItem({ fuelType: '' as any, liters: 0, totalCost: 0 });
  };

  const handleUpdateCartItem = (id: string, field: 'liters' | 'totalCost', value: string) => {
      const numValue = value === '' ? 0 : Number(value);
      setCartItems(prev => prev.map(item => 
          item.id === id ? { ...item, [field]: numValue } : item
      ));
  };

  const handleRemoveItemFromCart = (id: string) => {
      setCartItems(prev => prev.filter(item => item.id !== id));
  };

  const handleSaveStation = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly) return;
    if (!currentStation.name || !currentStation.municipality) return;

    const newStation: GasStation = {
      id: currentStation.id || crypto.randomUUID(),
      name: currentStation.name.toUpperCase(),
      cnpj: currentStation.cnpj ? currentStation.cnpj.toUpperCase() : '',
      municipality: currentStation.municipality.toUpperCase(),
      phone: currentStation.phone || '',
      address: currentStation.address ? currentStation.address.toUpperCase() : ''
    };

    setLoading(true);
    try {
        await storageService.saveGasStation(newStation);
        await loadData();
        resetForms();
    } catch (err: any) {
        console.error(err);
        alert(`Erro ao salvar posto: ${err.message}`);
    } finally {
        setLoading(false);
    }
  };

  const handleEditStation = (station: GasStation) => {
    if (isReadOnly) return;
    setCurrentStation(station);
    setIsEditing(true);
    setShowForm(true);
    setActiveTab('STATIONS');
  };

  const deleteStation = async (id: string) => {
    if (isReadOnly) return;
    const hasUsage = refuelings.some(r => r.gasStationId === id);
    if(hasUsage) {
        alert("Não é possível excluir este posto pois existem abastecimentos vinculados a ele.");
        return;
    }
    setLoading(true);
    try {
        await storageService.deleteGasStation(id);
        await loadData();
        setShowDeleteModal(false);
        setItemToDelete(null);
    } catch (err: any) {
        console.error(err);
        alert(`Erro ao excluir posto: ${err.message}`);
    } finally {
        setLoading(false);
    }
  };

  const getTicketItems = (log: RefuelingLog): RefuelingItem[] => {
      if (log.items && log.items.length > 0) return log.items;
      // Fallback para dados legados
      return [{
          fuelType: log.fuelType,
          liters: log.liters,
          totalCost: log.totalCost
      }];
  };

  const handleSaveRefueling = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly) return;

    if (!refuelingHeader.gasStationId) {
        alert("Selecione o posto.");
        return;
    }

    if (cartItems.length === 0) {
        alert("Adicione pelo menos um item à lista.");
        return;
    }

    let snapshotData = {
        plate: '',
        model: '',
        contract: '',
        municipality: '',
        foreman: refuelingHeader.foremanSnapshot || ''
    };

    let vehicleIdToSave = '';

    if (isExternal) {
        if (!externalData.identifier || !externalData.contract || !externalData.municipality) {
            alert("Para equipamentos externos, preencha Identificação, Contrato e Município.");
            return;
        }
        snapshotData.plate = externalData.identifier.toUpperCase();
        snapshotData.model = externalData.model ? externalData.model.toUpperCase() : '';
        snapshotData.contract = externalData.contract;
        snapshotData.municipality = externalData.municipality.toUpperCase();
        vehicleIdToSave = 'EXTERNAL';
    } else {
        if (!refuelingHeader.vehicleId) {
            alert("Selecione o veículo.");
            return;
        }

        const vehicle = vehicles.find(v => v.id === refuelingHeader.vehicleId);
        if (!vehicle) {
            alert("Veículo não encontrado no cadastro.");
            return;
        }

        snapshotData.plate = vehicle.plate;
        snapshotData.model = vehicle.model || '';
        snapshotData.contract = vehicle.contract;
        snapshotData.municipality = vehicle.municipality;
        if (!snapshotData.foreman) snapshotData.foreman = vehicle.foreman;

        vehicleIdToSave = refuelingHeader.vehicleId;
    }

    setLoading(true);
    try {
        // CONSOLIDATION & SUMMATION LOGIC
        const totalLiters = cartItems.reduce((acc, curr) => acc + Number(curr.liters || 0), 0);
        const totalCost = cartItems.reduce((acc, curr) => acc + Number(curr.totalCost || 0), 0);

        // Se houver mais de um tipo, marcamos como "OUTROS" para o banco de dados
        // Mas o sistema usará o campo 'items' para o detalhamento
        const mainFuelType = cartItems.length > 1 ? FuelType.OUTROS : cartItems[0].fuelType;

        const itemsBreakdown = cartItems.map(i => `${i.fuelType}: ${i.liters}${FUEL_TYPES_LIST.includes(i.fuelType) ? 'L' : 'un'}`).join(' | ');
        const customObs = isExternal && externalData.description ? externalData.description.toUpperCase() : '';
        const finalObservation = `[ITENS: ${itemsBreakdown}] ${customObs}`.trim();

        const newRefueling: RefuelingLog = {
            id: (isEditing && editingRecordId) ? editingRecordId : crypto.randomUUID(),
            date: refuelingHeader.date,
            vehicleId: vehicleIdToSave,
            gasStationId: refuelingHeader.gasStationId,
            fuelType: mainFuelType, 
            liters: Number(totalLiters.toFixed(2)), 
            totalCost: Number(totalCost.toFixed(2)), 
            items: cartItems.map(i => ({ fuelType: i.fuelType, liters: i.liters, totalCost: i.totalCost })), // Salvando o detalhamento JSON
            invoiceNumber: refuelingHeader.invoiceNumber ? refuelingHeader.invoiceNumber.toUpperCase() : '',
            requisitionNumber: refuelingHeader.requisitionNumber ? refuelingHeader.requisitionNumber.toUpperCase() : '',
            time: refuelingHeader.time || '', 

            plateSnapshot: snapshotData.plate,
            modelSnapshot: snapshotData.model,
            foremanSnapshot: snapshotData.foreman, 
            contractSnapshot: snapshotData.contract,
            municipalitySnapshot: snapshotData.municipality,
            observation: finalObservation
        };

        // Salva via upsert (se id já existe, sobrescreve o antigo)
        await storageService.saveRefueling(newRefueling);

        await loadData();
        resetForms();
        alert("Abastecimento salvo com sucesso!");
    } catch (err: any) {
        console.error("Erro ao salvar abastecimento:", err);
        alert(`Erro ao salvar no servidor: ${err.message || 'Verifique sua conexão.'}`);
    } finally {
        setLoading(false);
    }
  };

  const handleEditRefueling = (refueling: RefuelingLog) => {
    if (isReadOnly) return;

    setRefuelingHeader({
        date: refueling.date,
        time: refueling.time || '',
        vehicleId: refueling.vehicleId,
        gasStationId: refueling.gasStationId,
        foremanSnapshot: refueling.foremanSnapshot || '',
        invoiceNumber: refueling.invoiceNumber || '',
        requisitionNumber: refueling.requisitionNumber || ''
    });

    setEditingRecordId(refueling.id);

    // Reconstroi o carrinho a partir dos itens salvos ou cria um item a partir do registro legado
    let reconstructedItems: RefuelingCartItem[] = [];
    if (refueling.items && refueling.items.length > 0) {
        reconstructedItems = refueling.items.map(i => ({ ...i, id: crypto.randomUUID() }));
    } else {
        reconstructedItems = [{
            id: crypto.randomUUID(),
            fuelType: refueling.fuelType,
            liters: refueling.liters,
            totalCost: refueling.totalCost
        }];
    }

    setCartItems(reconstructedItems);

    const vehicleExists = vehicles.find(v => v.id === refueling.vehicleId);

    if (!vehicleExists || refueling.vehicleId === 'EXTERNAL') {
        setIsExternal(true);
        // Tenta remover o prefixo de itens da observação para exibição limpa
        const cleanObs = refueling.observation?.includes('] ') ? refueling.observation.split('] ')[1] : refueling.observation;
        setExternalData({
            identifier: refueling.plateSnapshot,
            model: refueling.modelSnapshot,
            contract: refueling.contractSnapshot,
            municipality: refueling.municipalitySnapshot,
            description: cleanObs || ''
        });
    } else {
        setIsExternal(false);
        setExternalData({ identifier: '', model: '', contract: '', municipality: '', description: '' });
    }

    setIsEditing(true);
    setShowForm(true);
    setActiveTab('REFUELING');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const deleteRefueling = async (id: string) => {
    if (isReadOnly) return;
    setLoading(true);
    try {
        await storageService.deleteRefueling(id);
        await loadData();
        setShowDeleteModal(false);
        setItemToDelete(null);
    } catch (err: any) {
        console.error(err);
        alert(`Erro ao excluir abastecimento: ${err.message}`);
    } finally {
        setLoading(false);
    }
  };

  const resetForms = () => {
    setShowForm(false);
    setIsEditing(false);
    setEditingRecordId(null);
    setCurrentStation({});
    setRefuelingHeader({
      date: getTodayLocal(),
      time: getCurrentTime(),
      vehicleId: '',
      gasStationId: '',
      foremanSnapshot: '',
      invoiceNumber: '',
      requisitionNumber: ''
    });
    setCartItems([]);
    setCurrentItem({ fuelType: '' as any, liters: 0, totalCost: 0 });
    setIsExternal(false);
    setExternalData({ identifier: '', model: '', contract: '', municipality: '', description: '' });
  };

  const resetFilters = () => {
    setFilterDateStart('');
    setFilterDateEnd('');
    setFilterPlate([]);
    setFilterStation([]);
    setFilterContract([]);
    setFilterMunicipality([]);
    setFilterFuel([]);
    setFilterForeman([]);
  };

  const confirmDelete = (id: string) => {
    if (isReadOnly) return;
    setItemToDelete(id);
    setShowDeleteModal(true);
  };

  const executeDelete = () => {
    if (itemToDelete) {
      if (activeTab === 'STATIONS') {
        deleteStation(itemToDelete);
      } else {
        deleteRefueling(itemToDelete);
      }
    }
  };

  const handleVehicleChange = (vehicleId: string) => {
    const vehicle = vehicles.find(v => v.id === vehicleId);
    if (vehicle) {
        setRefuelingHeader(prev => ({
            ...prev,
            vehicleId: vehicleId,
            foremanSnapshot: vehicle.foreman || ''
        }));
    } else {
        setRefuelingHeader(prev => ({ ...prev, vehicleId: vehicleId, foremanSnapshot: '' }));
    }
  };

  const formatDate = (dateStr: string) => {
    if (!dateStr) return '-';
    const [y, m, d] = dateStr.split('-');
    return `${d}/${m}/${y}`;
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val || 0);
  };

  const filteredRefuelings = refuelings.filter(r => {
      const rDate = new Date(r.date).getTime();
      const start = filterDateStart ? new Date(filterDateStart).getTime() : null;
      const end = filterDateEnd ? new Date(filterDateEnd).getTime() : null;
      const matchesDate = (!start || rDate >= start) && (!end || rDate <= end);

      const matchesPlate = filterPlate.length === 0 || filterPlate.includes(r.plateSnapshot);
      const matchesStation = filterStation.length === 0 || filterStation.includes(r.gasStationId);
      const matchesContract = filterContract.length === 0 || filterContract.includes(r.contractSnapshot);
      const matchesCity = filterMunicipality.length === 0 || filterMunicipality.includes(r.municipalitySnapshot);
      const matchesFuel = filterFuel.length === 0 || filterFuel.includes(r.fuelType) || (r.items && r.items.some(it => filterFuel.includes(it.fuelType)));
      const matchesForeman = filterForeman.length === 0 || (r.foremanSnapshot && filterForeman.includes(r.foremanSnapshot));

      return matchesDate && matchesPlate && matchesStation && matchesContract && matchesCity && matchesFuel && matchesForeman;
  }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  const totalPages = Math.ceil(filteredRefuelings.length / ITEMS_PER_PAGE);
  const paginatedRefuelings = filteredRefuelings.slice(
    (currentPage - 1) * ITEMS_PER_PAGE,
    currentPage * ITEMS_PER_PAGE
  );

  const totalLitersCalculated = filteredRefuelings.reduce((acc, curr) => acc + (curr.liters || 0), 0);
  const totalCostCalculated = filteredRefuelings.reduce((acc, curr) => acc + (curr.totalCost || 0), 0);

  const activeFiltersCount = [
    filterDateStart, filterDateEnd, 
    filterPlate.length, filterStation.length, 
    filterContract.length, filterMunicipality.length, filterFuel.length, filterForeman.length
  ].filter(Boolean).reduce((a, b) => a + (typeof b === 'number' ? b : 1), 0);

  const inputClass = "w-full rounded-lg border border-slate-300 bg-slate-50 p-2.5 text-slate-800 focus:border-blue-600 focus:bg-white focus:ring-2 focus:ring-blue-100 outline-none transition-all";
  const selectClass = "w-full rounded-lg border border-slate-300 bg-white p-2 text-slate-700 focus:border-blue-600 focus:ring-2 focus:ring-blue-100 outline-none transition-all h-[42px] shadow-sm";

  const plateOptions: MultiSelectOption[] = uniquePlates.map(p => ({ value: p, label: p }));
  const stationOptions: MultiSelectOption[] = stations.map(s => ({ value: s.id, label: s.name }));
  const contractOptions: MultiSelectOption[] = uniqueContracts.map(c => ({ value: c, label: c }));
  const municipalityOptions: MultiSelectOption[] = uniqueMunicipalities.map(m => ({ value: m, label: m }));
  const foremanOptions: MultiSelectOption[] = uniqueForemen.map(f => ({ value: f, label: f }));
  const fuelOptions: MultiSelectOption[] = Object.values(FuelType).map(f => ({ value: f, label: f }));

  const vehicleOptions = vehicles.map(v => ({
      value: v.id,
      label: `${v.plate} - ${v.driverName} (${v.type})`
  }));

  const stationSelectOptions = stations.map(s => ({
      value: s.id,
      label: `${s.name} - ${s.municipality}`
  }));

  if (loading && activeTab === 'REFUELING' && refuelings.length === 0) {
      return <div className="flex justify-center items-center h-64"><Loader2 className="animate-spin text-blue-600" size={48} /></div>;
  }

  return (
    <div className="space-y-6">

      <PrintHeader 
        title="Relatório de Abastecimentos"
        subtitle="Consolidado de Consumo"
        details={
            <>
                <span>Registros: {filteredRefuelings.length}</span>
                <span>Total Litros: {totalLitersCalculated.toFixed(2)} L</span>
                <span>Total Valor: {formatCurrency(totalCostCalculated)}</span>
            </>
        }
      />

       <div className="print:hidden">
        <PasswordModal
            isOpen={showDeleteModal}
            onClose={() => setShowDeleteModal(false)}
            onConfirm={executeDelete}
