                                        <td className="px-6 py-3 text-slate-500 text-xs">
                                            {station.phone && <div>Tel: {station.phone}</div>}
                                            {station.cnpj && <div>CNPJ: {station.cnpj}</div>}
                                        </td>
                                        {!isReadOnly && (
                                            <td className="px-6 py-3 text-center">
                                                <div className="flex justify-center gap-2">
                                                    <button onClick={() => handleEditStation(station)} className="p-2 text-blue-600 hover:bg-blue-50 rounded"><Edit2 size={16} /></button>
                                                    <button onClick={() => confirmDelete(station.id)} className="p-2 text-red-600 hover:bg-red-50 rounded"><Trash2 size={16} /></button>
                                                </div>
                                            </td>
                                        )}
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default FuelManagement;

import React, { useState, useEffect } from 'react';
import { GasStation, RefuelingLog, Vehicle, FuelType, ContractType, UserRole, UserProfile, FUEL_TYPES_LIST, SUPPLY_TYPES_LIST, RefuelingItem } from './types';
import { storageService } from './services/storage';
import PasswordModal from './components/PasswordModal';
import { useAuth } from './contexts/AuthContext';
import { 
  Fuel, Plus, Save, Trash2, Edit2, Droplet, Filter, X, Calendar, Printer, AlertCircle, Users, ChevronDown, ChevronUp, MapPin, Clock, ClipboardList, ChevronLeft, ChevronRight, Loader2, ShoppingCart, Package, DollarSign, Receipt
} from 'lucide-react';
import { PrintHeader } from './components/PrintHeader';
import MultiSelect, { MultiSelectOption } from './components/MultiSelect';
import SelectWithSearch from './components/SelectWithSearch';
import { ParisLogo } from './components/ParisLogo';

type TabType = 'REFUELING' | 'STATIONS';

const EXTERNAL_EQUIPMENT_TYPES = [
  'BARCO', 'BALSA', 'MOTO', 'CARRO', 'LANCHA', 'MOTOR DE POUPA', 'MOTOPODA', 'GERADOR', 'GALÃO', 'TAMBOR'
];

const ITEMS_PER_PAGE = 50;

interface RefuelingCartItem {
    id: string;
    fuelType: FuelType;
    liters: number;
    totalCost: number;
}

const FuelManagement: React.FC = () => {
  const { user } = useAuth();
  const isReadOnly = user?.role === UserRole.GERENCIA;

  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<TabType>('REFUELING');

  const [stations, setStations] = useState<GasStation[]>([]);
  const [refuelings, setRefuelings] = useState<RefuelingLog[]>([]);
  const [vehicles, setVehicles] = useState<Vehicle[]>([]);

  const [currentPage, setCurrentPage] = useState(1);

  const [filterDateStart, setFilterDateStart] = useState('');
  const [filterDateEnd, setFilterDateEnd] = useState('');
  const [filterPlate, setFilterPlate] = useState<string[]>([]);
  const [filterStation, setFilterStation] = useState<string[]>([]);
  const [filterContract, setFilterContract] = useState<string[]>([]);
  const [filterMunicipality, setFilterMunicipality] = useState<string[]>([]);
  const [filterFuel, setFilterFuel] = useState<string[]>([]);
  const [filterForeman, setFilterForeman] = useState<string[]>([]);

  const [showFilters, setShowFilters] = useState(false);

  const [uniquePlates, setUniquePlates] = useState<string[]>([]);
  const [uniqueContracts, setUniqueContracts] = useState<string[]>([]);
  const [uniqueMunicipalities, setUniqueMunicipalities] = useState<string[]>([]);
  const [uniqueForemen, setUniqueForemen] = useState<string[]>([]);

  const [showForm, setShowForm] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editingRecordId, setEditingRecordId] = useState<string | null>(null);

  const [currentStation, setCurrentStation] = useState<Partial<GasStation>>({});
  const [selectedTicket, setSelectedTicket] = useState<RefuelingLog | null>(null);

  const getTodayLocal = () => {
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const getCurrentTime = () => {
    const now = new Date();
    return now.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
  };

  const [refuelingHeader, setRefuelingHeader] = useState({
      date: getTodayLocal(),
      time: getCurrentTime(),
      vehicleId: '',
      gasStationId: '',
      foremanSnapshot: '',
      invoiceNumber: '',
      requisitionNumber: ''
  });

  const [cartItems, setCartItems] = useState<RefuelingCartItem[]>([]);
  const [currentItem, setCurrentItem] = useState<Partial<RefuelingCartItem>>({
      fuelType: '' as any,
      liters: 0,
      totalCost: 0
  });

  const [isExternal, setIsExternal] = useState(false);
  const [externalData, setExternalData] = useState({
    identifier: '', 
    model: '',
    contract: '',
    municipality: '',
    description: '' 
  });

  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    try {
      const [sData, rData, vData] = await Promise.all([
          storageService.getGasStations(),
          storageService.getRefuelings(),
          storageService.getVehicles()
      ]);

      setStations(sData);
      setRefuelings(rData);
      setVehicles(vData);

      const plates = Array.from(new Set(rData.map(r => r.plateSnapshot))).sort();
      const contracts = Array.from(new Set(rData.map(r => r.contractSnapshot))).sort();
      const cities = Array.from(new Set(rData.map(r => r.municipalitySnapshot))).sort();
      const vehicleTeams = Array.from(new Set(vData.map(v => v.foreman).filter(f => f && f.trim() !== ''))).sort();

      setUniquePlates(plates);
      setUniqueContracts(contracts);
      setUniqueMunicipalities(cities);
      setUniqueForemen(vehicleTeams);
    } catch (e) { console.error(e); } finally { setLoading(false); }
  };

  const handlePrint = () => { window.print(); };

  const getFuelColor = (fuelType: string) => {
    if (fuelType === FuelType.OUTROS || fuelType.includes('DIVERSOS')) return 'bg-purple-100 text-purple-800 border-purple-200';
    switch (fuelType) {
      case FuelType.GASOLINA: return 'bg-orange-100 text-orange-800 border-orange-200'; 
      case FuelType.ETANOL: return 'bg-green-100 text-green-800 border-green-200';
      case FuelType.DIESEL: return 'bg-yellow-100 text-yellow-800 border-yellow-200';
      case FuelType.DIESEL_S10: return 'bg-slate-100 text-slate-800 border-slate-200';
      default: return 'bg-gray-100 text-gray-800 border-gray-200';
    }
  };

  // --- LÓGICA DE CÁLCULO UNIFICADA ---
  const getEffectiveValues = (log: RefuelingLog) => {
      // Se não houver filtro de combustível, retorna o total do registro
      if (filterFuel.length === 0) {
          return { liters: log.liters || 0, cost: log.totalCost || 0 };
      }

      // Se houver filtro, mas o registro não tem itens detalhados (legado), checa o tipo principal
      if (!log.items || log.items.length === 0) {
          const matches = filterFuel.includes(log.fuelType);
          return {
              liters: matches ? (log.liters || 0) : 0,
              cost: matches ? (log.totalCost || 0) : 0
          };
      }

      // Se houver filtro e itens detalhados, soma apenas os itens que batem com o filtro
      const filteredItems = log.items.filter(it => filterFuel.includes(it.fuelType));
      return {
          liters: filteredItems.reduce((acc, it) => acc + Number(it.liters || 0), 0),
          cost: filteredItems.reduce((acc, it) => acc + Number(it.totalCost || 0), 0)
      };
  };

  const handleAddItemToCart = () => {
      if (!currentItem.fuelType) { alert("Selecione o produto."); return; }
      const qty = Number(currentItem.liters || 0);
      const cost = Number(currentItem.totalCost || 0);
      setCartItems(prev => [...prev, { id: crypto.randomUUID(), fuelType: currentItem.fuelType as FuelType, liters: qty, totalCost: cost }]);
      setCurrentItem({ fuelType: '' as any, liters: 0, totalCost: 0 });
  };

  const handleUpdateCartItem = (id: string, field: 'liters' | 'totalCost', value: string) => {
      const numValue = value === '' ? 0 : Number(value);
      setCartItems(prev => prev.map(item => item.id === id ? { ...item, [field]: numValue } : item));
  };

  const handleRemoveItemFromCart = (id: string) => { setCartItems(prev => prev.filter(item => item.id !== id)); };

  const handleSaveRefueling = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly || !refuelingHeader.gasStationId || cartItems.length === 0) return;

    let snapshotData = { plate: '', model: '', contract: '', municipality: '', foreman: refuelingHeader.foremanSnapshot || '' };
    let vehicleIdToSave = '';

    if (isExternal) {
        snapshotData.plate = externalData.identifier.toUpperCase();
        snapshotData.model = externalData.model.toUpperCase();
        snapshotData.contract = externalData.contract;
        snapshotData.municipality = externalData.municipality.toUpperCase();
        vehicleIdToSave = 'EXTERNAL';
    } else {
        const vehicle = vehicles.find(v => v.id === refuelingHeader.vehicleId);
        if (!vehicle) return;
        snapshotData.plate = vehicle.plate;
        snapshotData.model = vehicle.model || '';
        snapshotData.contract = vehicle.contract;
        snapshotData.municipality = vehicle.municipality;
        if (!snapshotData.foreman) snapshotData.foreman = vehicle.foreman;
        vehicleIdToSave = refuelingHeader.vehicleId;
    }

    setLoading(true);
    try {
        const totalLiters = cartItems.reduce((acc, curr) => acc + Number(curr.liters || 0), 0);
        const totalCost = cartItems.reduce((acc, curr) => acc + Number(curr.totalCost || 0), 0);
        const mainFuelType = cartItems.length > 1 ? FuelType.OUTROS : cartItems[0].fuelType;

        const newRefueling: RefuelingLog = {
            id: editingRecordId || crypto.randomUUID(),
            date: refuelingHeader.date,
            vehicleId: vehicleIdToSave,
            gasStationId: refuelingHeader.gasStationId,
            fuelType: mainFuelType, 
            liters: Number(totalLiters.toFixed(2)), 
            totalCost: Number(totalCost.toFixed(2)), 
            items: cartItems.map(i => ({ fuelType: i.fuelType, liters: i.liters, totalCost: i.totalCost })),
            invoiceNumber: refuelingHeader.invoiceNumber?.toUpperCase() || '',
            requisitionNumber: refuelingHeader.requisitionNumber?.toUpperCase() || '',
            time: refuelingHeader.time || '', 
            plateSnapshot: snapshotData.plate,
            modelSnapshot: snapshotData.model,
            foremanSnapshot: snapshotData.foreman, 
            contractSnapshot: snapshotData.contract,
            municipalitySnapshot: snapshotData.municipality,
            observation: `[Consolidação de ${cartItems.length} itens]`.toUpperCase()
        };

        await storageService.saveRefueling(newRefueling);
        await loadData();
        resetForms();
    } catch (err: any) { alert(`Erro ao salvar: ${err.message}`); } finally { setLoading(false); }
  };

  const handleEditRefueling = (refueling: RefuelingLog) => {
    if (isReadOnly) return;
    setRefuelingHeader({
        date: refueling.date,
        time: refueling.time || '',
        vehicleId: refueling.vehicleId,
        gasStationId: refueling.gasStationId,
        foremanSnapshot: refueling.foremanSnapshot || '',
        invoiceNumber: refueling.invoiceNumber || '',
        requisitionNumber: refueling.requisitionNumber || ''
    });
    setEditingRecordId(refueling.id);
    setCartItems(refueling.items?.map(i => ({ ...i, id: crypto.randomUUID() })) || [{ id: crypto.randomUUID(), fuelType: refueling.fuelType, liters: refueling.liters, totalCost: refueling.totalCost }]);
    setIsExternal(refueling.vehicleId === 'EXTERNAL');
    setIsEditing(true);
    setShowForm(true);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const resetForms = () => {
    setShowForm(false); setIsEditing(false); setEditingRecordId(null);
    setRefuelingHeader({ date: getTodayLocal(), time: getCurrentTime(), vehicleId: '', gasStationId: '', foremanSnapshot: '', invoiceNumber: '', requisitionNumber: '' });
    setCartItems([]); setIsExternal(false);
  };

  const filteredRefuelings = refuelings.filter(r => {
      const rDate = new Date(r.date).getTime();
      const start = filterDateStart ? new Date(filterDateStart).getTime() : null;
      const end = filterDateEnd ? new Date(filterDateEnd).getTime() : null;
      const matchesDate = (!start || rDate >= start) && (!end || rDate <= end);
      const matchesPlate = filterPlate.length === 0 || filterPlate.includes(r.plateSnapshot);
      const matchesStation = filterStation.length === 0 || filterStation.includes(r.gasStationId);
      const matchesFuel = filterFuel.length === 0 || filterFuel.includes(r.fuelType) || (r.items && r.items.some(it => filterFuel.includes(it.fuelType)));
      return matchesDate && matchesPlate && matchesStation && matchesFuel;
  });

  const totalLitersCalculated = filteredRefuelings.reduce((acc, curr) => acc + getEffectiveValues(curr).liters, 0);
  const totalCostCalculated = filteredRefuelings.reduce((acc, curr) => acc + getEffectiveValues(curr).cost, 0);

  const paginatedRefuelings = filteredRefuelings.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()).slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE);

  return (
    <div className="space-y-6">
      <PrintHeader title="Relatório de Abastecimentos" details={<><span>Total Litros: {totalLitersCalculated.toFixed(2)} L</span><span>Total Valor: {formatCurrency(totalCostCalculated)}</span></>} />

      <div className="flex flex-col md:flex-row justify-between items-start gap-4 print:hidden">
        <div><h1 className="text-3xl font-bold text-slate-900 flex items-center gap-3"><Fuel className="text-blue-600" size={32} /> Abastecimento</h1></div>
        <button onClick={handlePrint} className="bg-white border border-slate-300 text-slate-700 px-4 py-2 rounded-lg font-medium flex items-center gap-2 shadow-sm"><Printer size={20} /> Imprimir</button>
      </div>

      <div className="flex bg-slate-100 p-1 rounded-lg w-fit print:hidden">
        <button onClick={() => setActiveTab('REFUELING')} className={`px-6 py-2 rounded-md text-sm font-bold transition-all ${activeTab === 'REFUELING' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>Registros</button>
        <button onClick={() => setActiveTab('STATIONS')} className={`px-6 py-2 rounded-md text-sm font-bold transition-all ${activeTab === 'STATIONS' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>Postos</button>
      </div>

      {activeTab === 'REFUELING' && (
        <div className="space-y-6">
            <div className="bg-white rounded-xl border border-slate-200 shadow-sm print:hidden p-4">
                <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                    <div><label className="block text-xs font-bold text-slate-500 mb-1">Data Início</label><input type="date" className="w-full border rounded p-2" value={filterDateStart} onChange={(e) => setFilterDateStart(e.target.value)} /></div>
                    <div><label className="block text-xs font-bold text-slate-500 mb-1">Data Final</label><input type="date" className="w-full border rounded p-2" value={filterDateEnd} onChange={(e) => setFilterDateEnd(e.target.value)} /></div>
                    <div className="md:col-span-2 flex items-end gap-2">
                        <MultiSelect label="Combustível" options={Object.values(FuelType).map(f => ({value: f, label: f}))} selected={filterFuel} onChange={setFilterFuel} placeholder="Todos" />
                        <button onClick={() => setShowForm(!showForm)} className="bg-blue-600 text-white px-4 py-2 rounded-lg font-bold flex items-center gap-2 h-[42px]"><Plus size={18} /> Novo</button>
                    </div>
                </div>
            </div>

            {showForm && !isReadOnly && (
                <div className="bg-white rounded-xl shadow-lg border p-6 animate-in slide-in-from-top-2 print:hidden">
                    <h3 className="font-bold text-lg mb-6 flex items-center gap-2"><Droplet className="text-blue-500" /> {isEditing ? 'Editar' : 'Novo'} Lançamento Consolidado</h3>
                    <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-8 bg-slate-50 p-4 rounded-lg">
                        <div className="md:col-span-4 flex items-center gap-2 mb-2">
                            <input type="checkbox" checked={isExternal} onChange={e => setIsExternal(e.target.checked)} id="ext" className="w-5 h-5 accent-blue-600" />
                            <label htmlFor="ext" className="text-sm font-bold text-slate-700">Equipamento Externo</label>
                        </div>
                        <div><label className="block text-xs font-bold text-slate-500 mb-1">Data</label><input type="date" value={refuelingHeader.date} onChange={e => setRefuelingHeader({...refuelingHeader, date: e.target.value})} className="w-full border rounded p-2" /></div>
                        {isExternal ? (
                            <div className="md:col-span-2"><input type="text" placeholder="IDENTIFICAÇÃO" value={externalData.identifier} onChange={e => setExternalData({...externalData, identifier: e.target.value.toUpperCase()})} className="w-full border rounded p-2 mt-5" /></div>
                        ) : (
                            <div className="md:col-span-2"><SelectWithSearch label="Veículo" options={vehicles.map(v => ({value: v.id, label: v.plate}))} value={refuelingHeader.vehicleId} onChange={val => setRefuelingHeader({...refuelingHeader, vehicleId: val})} /></div>
                        )}
                        <div className="md:col-span-1"><SelectWithSearch label="Posto" options={stations.map(s => ({value: s.id, label: s.name}))} value={refuelingHeader.gasStationId} onChange={val => setRefuelingHeader({...refuelingHeader, gasStationId: val})} /></div>
                    </div>

                    <div className="bg-blue-50 p-4 rounded-xl border border-blue-200 mb-6 grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
                        <div><label className="block text-xs font-bold text-slate-500 mb-1">Produto</label><select value={currentItem.fuelType || ''} onChange={e => setCurrentItem({...currentItem, fuelType: e.target.value as FuelType})} className="w-full border rounded p-2 bg-white h-[42px]"><option value="">Selecione...</option><optgroup label="COMBUSTÍVEL">{FUEL_TYPES_LIST.map(f => <option key={f} value={f}>{f}</option>)}</optgroup><optgroup label="INSUMOS">{SUPPLY_TYPES_LIST.map(f => <option key={f} value={f}>{f}</option>)}</optgroup></select></div>
                        <div><label className="block text-xs font-bold text-slate-500 mb-1">Qtd</label><input type="number" step="0.01" value={currentItem.liters || ''} onChange={e => setCurrentItem({...currentItem, liters: Number(e.target.value)})} className="w-full border rounded p-2" /></div>
                        <div><label className="block text-xs font-bold text-slate-500 mb-1">Valor</label><input type="number" step="0.01" value={currentItem.totalCost || ''} onChange={e => setCurrentItem({...currentItem, totalCost: Number(e.target.value)})} className="w-full border rounded p-2" /></div>
                        <button type="button" onClick={handleAddItemToCart} className="bg-slate-800 text-white p-2.5 rounded-lg font-bold flex items-center justify-center gap-2 h-[42px]"><Plus size={18} /> Incluir</button>
                    </div>

                    <div className="mb-6 border rounded-xl overflow-hidden">
                        <table className="w-full text-sm">
                            <thead className="bg-slate-100 font-bold"><tr><th className="px-4 py-2 text-left">Item</th><th className="px-4 py-2 text-center">Qtd</th><th className="px-4 py-2 text-right">Valor</th><th className="px-4 py-2 text-center">Ações</th></tr></thead>
                            <tbody className="divide-y">{cartItems.map(item => (<tr key={item.id} className="hover:bg-slate-50"><td className="px-4 py-2 font-bold">{item.fuelType}</td><td className="px-4 py-2 text-center font-mono">{item.liters.toFixed(2)}</td><td className="px-4 py-2 text-right font-bold text-green-700">R$ {item.totalCost.toFixed(2)}</td><td className="px-4 py-2 text-center"><button onClick={() => handleRemoveItemFromCart(item.id)} className="text-red-500 p-1"><Trash2 size={16} /></button></td></tr>))}</tbody>
                        </table>
                    </div>

                    <div className="flex justify-end gap-3 pt-6 border-t"><button type="button" onClick={resetForms} className="px-6 py-2.5 text-slate-600 font-medium">Cancelar</button><button onClick={handleSaveRefueling} disabled={loading || cartItems.length === 0} className="bg-blue-800 text-white px-8 py-2.5 rounded-lg font-bold flex items-center gap-2 shadow-lg disabled:opacity-50">{loading ? <Loader2 className="animate-spin"/> : <Save size={18} />} Salvar Registro</button></div>
                </div>
            )}

             <div className="grid grid-cols-1 md:grid-cols-3 gap-4 print:hidden">
                <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200">
                    <p className="text-xs font-bold text-slate-500 uppercase">Litros Lançados no Período</p>
                    <p className="text-2xl font-black text-blue-800">{totalLitersCalculated.toFixed(2)} L</p>
                    {filterFuel.length > 0 && <p className="text-[10px] text-blue-600 font-bold uppercase mt-1">Filtro Ativo: {filterFuel.join(', ')}</p>}
                </div>
                <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200">
                    <p className="text-xs font-bold text-slate-500 uppercase">Valor Total do Período</p>
                    <p className="text-2xl font-black text-green-700">{formatCurrency(totalCostCalculated)}</p>
                </div>
             </div>

            <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left">
                        <thead className="bg-slate-100 text-slate-600 font-bold uppercase text-xs border-b">
                            <tr><th className="px-6 py-3">Data</th><th className="px-6 py-3">Veículo</th><th className="px-6 py-3">Posto</th><th className="px-6 py-3">Combustível</th><th className="px-6 py-3">Litros</th><th className="px-6 py-3">Valor</th><th className="px-6 py-3 text-center print:hidden">Ações</th></tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {paginatedRefuelings.map(item => {
                                const { liters, cost } = getEffectiveValues(item);
                                const isPartial = filterFuel.length > 0 && item.items && item.items.length > 1 && liters < item.liters;

                                return (
                                    <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                                        <td className="px-6 py-3 font-medium">{formatDate(item.date)}</td>
                                        <td className="px-6 py-3 font-bold">{item.plateSnapshot}</td>
                                        <td className="px-6 py-3">{stations.find(s => s.id === item.gasStationId)?.name}</td>
                                        <td className="px-6 py-3"><span className={`text-[10px] font-bold px-2 py-1 rounded border ${getFuelColor(item.fuelType)}`}>{item.items && item.items.length > 1 ? `DIVERSOS (${item.items.length})` : item.fuelType}</span></td>
                                        <td className="px-6 py-3 font-mono font-bold text-blue-900">
                                            {liters.toFixed(2)} L
                                            {isPartial && <div className="text-[9px] text-slate-400 font-normal">de {item.liters.toFixed(2)}L (Filtrado)</div>}
                                        </td>
                                        <td className="px-6 py-3 font-mono font-bold text-green-700">{formatCurrency(cost)}</td>
                                        <td className="px-6 py-3 print:hidden text-center">
                                            <div className="flex justify-center gap-1">
                                                <button onClick={() => setSelectedTicket(item)} className="p-1.5 text-slate-600 hover:bg-slate-100 rounded"><Receipt size={18} /></button>
                                                {!isReadOnly && <><button onClick={() => handleEditRefueling(item)} className="p-1.5 text-blue-600 hover:bg-blue-50 rounded"><Edit2 size={18} /></button><button onClick={() => confirmDelete(item.id)} className="p-1.5 text-red-600 hover:bg-red-50 rounded"><Trash2 size={18} /></button></>}
                                            </div>
                                        </td>
                                    </tr>
                                );
                            })}
                        </tbody>
                        <tfoot className="bg-slate-50 font-bold text-slate-800 border-t border-slate-200">
                             <tr>
                                 <td colSpan={4} className="px-6 py-3 text-right uppercase text-xs">Somatório Período {filterFuel.length > 0 ? '(Filtrado)' : ''}</td>
                                 <td className="px-6 py-3 text-blue-900">{totalLitersCalculated.toFixed(2)} L</td>
                                 <td className="px-6 py-3 text-green-800">{formatCurrency(totalCostCalculated)}</td>
                                 <td className="print:hidden"></td>
                             </tr>
                        </tfoot>
                    </table>
                </div>
            </div>
        </div>
      )}
      <PasswordModal isOpen={showDeleteModal} onClose={() => setShowDeleteModal(false)} onConfirm={() => { if (itemToDelete) { if (activeTab === 'STATIONS') storageService.deleteGasStation(itemToDelete).then(loadData); else storageService.deleteRefueling(itemToDelete).then(loadData); setShowDeleteModal(false); } }} title="Confirmar Exclusão" />
    </div>
  );
};

export default FuelManagement;

import React, { useState, useEffect } from 'react';
import { GasStation, RefuelingLog, Vehicle, FuelType, ContractType, UserRole, UserProfile, FUEL_TYPES_LIST, SUPPLY_TYPES_LIST, RefuelingItem } from './types';
import { storageService } from './services/storage';
import PasswordModal from './components/PasswordModal';
import { useAuth } from './contexts/AuthContext';
import { 
  Fuel, Plus, Save, Trash2, Edit2, Droplet, Filter, X, Calendar, Printer, AlertCircle, Users, ChevronDown, ChevronUp, MapPin, Clock, ClipboardList, ChevronLeft, ChevronRight, Loader2, ShoppingCart, Package, DollarSign, Receipt
} from 'lucide-react';
import { PrintHeader } from './components/PrintHeader';
import MultiSelect, { MultiSelectOption } from './components/MultiSelect';
import SelectWithSearch from './components/SelectWithSearch';
import { ParisLogo } from './components/ParisLogo';

type TabType = 'REFUELING' | 'STATIONS';

const EXTERNAL_EQUIPMENT_TYPES = [
  'BARCO', 'BALSA', 'MOTO', 'CARRO', 'LANCHA', 'MOTOR DE POUPA', 'MOTOPODA', 'GERADOR', 'GALÃO', 'TAMBOR'
];

const ITEMS_PER_PAGE = 50;

interface RefuelingCartItem {
    id: string;
    fuelType: FuelType;
    liters: number;
    totalCost: number;
}

const FuelManagement: React.FC = () => {
  const { user } = useAuth();
  const isReadOnly = user?.role === UserRole.GERENCIA;

  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<TabType>('REFUELING');

  const [stations, setStations] = useState<GasStation[]>([]);
  const [refuelings, setRefuelings] = useState<RefuelingLog[]>([]);
  const [vehicles, setVehicles] = useState<Vehicle[]>([]);

  const [currentPage, setCurrentPage] = useState(1);

  const [filterDateStart, setFilterDateStart] = useState('');
  const [filterDateEnd, setFilterDateEnd] = useState('');
  const [filterPlate, setFilterPlate] = useState<string[]>([]);
  const [filterStation, setFilterStation] = useState<string[]>([]);
  const [filterContract, setFilterContract] = useState<string[]>([]);
  const [filterMunicipality, setFilterMunicipality] = useState<string[]>([]);
  const [filterFuel, setFilterFuel] = useState<string[]>([]);
  const [filterForeman, setFilterForeman] = useState<string[]>([]);

  const [showFilters, setShowFilters] = useState(false);

  const [uniquePlates, setUniquePlates] = useState<string[]>([]);
  const [uniqueContracts, setUniqueContracts] = useState<string[]>([]);
  const [uniqueMunicipalities, setUniqueMunicipalities] = useState<string[]>([]);
  const [uniqueForemen, setUniqueForemen] = useState<string[]>([]);

  const [showForm, setShowForm] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editingRecordId, setEditingRecordId] = useState<string | null>(null);

  const [currentStation, setCurrentStation] = useState<Partial<GasStation>>({});
  const [selectedTicket, setSelectedTicket] = useState<RefuelingLog | null>(null);

  const getTodayLocal = () => {
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const getCurrentTime = () => {
    const now = new Date();
    return now.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
  };

  const [refuelingHeader, setRefuelingHeader] = useState({
      date: getTodayLocal(),
      time: getCurrentTime(),
      vehicleId: '',
      gasStationId: '',
      foremanSnapshot: '',
      invoiceNumber: '',
      requisitionNumber: ''
  });

  const [cartItems, setCartItems] = useState<RefuelingCartItem[]>([]);
  const [currentItem, setCurrentItem] = useState<Partial<RefuelingCartItem>>({
      fuelType: '' as any,
      liters: 0,
      totalCost: 0
  });

  const [isExternal, setIsExternal] = useState(false);
  const [externalData, setExternalData] = useState({
    identifier: '', 
    model: '',
    contract: '',
    municipality: '',
    description: '' 
  });

  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    try {
      const [sData, rData, vData] = await Promise.all([
          storageService.getGasStations(),
          storageService.getRefuelings(),
          storageService.getVehicles()
      ]);

      setStations(sData);
      setRefuelings(rData);
      setVehicles(vData);

      const plates = Array.from(new Set(rData.map(r => r.plateSnapshot))).sort();
      const contracts = Array.from(new Set(rData.map(r => r.contractSnapshot))).sort();
      const cities = Array.from(new Set(rData.map(r => r.municipalitySnapshot))).sort();
      const vehicleTeams = Array.from(new Set(vData.map(v => v.foreman).filter(f => f && f.trim() !== ''))).sort();

      setUniquePlates(plates);
      setUniqueContracts(contracts);
      setUniqueMunicipalities(cities);
      setUniqueForemen(vehicleTeams);
    } catch (e) { console.error(e); } finally { setLoading(false); }
  };

  const handlePrint = () => { window.print(); };

  const getFuelColor = (fuelType: string) => {
    if (fuelType === FuelType.OUTROS || fuelType.includes('DIVERSOS')) return 'bg-purple-100 text-purple-800 border-purple-200';
    switch (fuelType) {
      case FuelType.GASOLINA: return 'bg-orange-100 text-orange-800 border-orange-200'; 
      case FuelType.ETANOL: return 'bg-green-100 text-green-800 border-green-200';
      case FuelType.DIESEL: return 'bg-yellow-100 text-yellow-800 border-yellow-200';
      case FuelType.DIESEL_S10: return 'bg-slate-100 text-slate-800 border-slate-200';
      default: return 'bg-gray-100 text-gray-800 border-gray-200';
    }
  };

  // --- LÓGICA DE CÁLCULO UNIFICADA ---
  const getEffectiveValues = (log: RefuelingLog) => {
      // Se não houver filtro de combustível, retorna o total do registro
      if (filterFuel.length === 0) {
          return { liters: log.liters || 0, cost: log.totalCost || 0 };
      }

      // Se houver filtro, mas o registro não tem itens detalhados (legado), checa o tipo principal
      if (!log.items || log.items.length === 0) {
          const matches = filterFuel.includes(log.fuelType);
          return {
              liters: matches ? (log.liters || 0) : 0,
              cost: matches ? (log.totalCost || 0) : 0
          };
      }

      // Se houver filtro e itens detalhados, soma apenas os itens que batem com o filtro
      const filteredItems = log.items.filter(it => filterFuel.includes(it.fuelType));
      return {
          liters: filteredItems.reduce((acc, it) => acc + Number(it.liters || 0), 0),
          cost: filteredItems.reduce((acc, it) => acc + Number(it.totalCost || 0), 0)
      };
  };

  const handleAddItemToCart = () => {
      if (!currentItem.fuelType) { alert("Selecione o produto."); return; }
      const qty = Number(currentItem.liters || 0);
      const cost = Number(currentItem.totalCost || 0);
      setCartItems(prev => [...prev, { id: crypto.randomUUID(), fuelType: currentItem.fuelType as FuelType, liters: qty, totalCost: cost }]);
      setCurrentItem({ fuelType: '' as any, liters: 0, totalCost: 0 });
  };

  const handleUpdateCartItem = (id: string, field: 'liters' | 'totalCost', value: string) => {
      const numValue = value === '' ? 0 : Number(value);
      setCartItems(prev => prev.map(item => item.id === id ? { ...item, [field]: numValue } : item));
  };

  const handleRemoveItemFromCart = (id: string) => { setCartItems(prev => prev.filter(item => item.id !== id)); };

  const handleSaveRefueling = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly || !refuelingHeader.gasStationId || cartItems.length === 0) return;

    let snapshotData = { plate: '', model: '', contract: '', municipality: '', foreman: refuelingHeader.foremanSnapshot || '' };
    let vehicleIdToSave = '';

    if (isExternal) {
        snapshotData.plate = externalData.identifier.toUpperCase();
        snapshotData.model = externalData.model.toUpperCase();
        snapshotData.contract = externalData.contract;
        snapshotData.municipality = externalData.municipality.toUpperCase();
        vehicleIdToSave = 'EXTERNAL';
    } else {
        const vehicle = vehicles.find(v => v.id === refuelingHeader.vehicleId);
        if (!vehicle) return;
        snapshotData.plate = vehicle.plate;
        snapshotData.model = vehicle.model || '';
        snapshotData.contract = vehicle.contract;
        snapshotData.municipality = vehicle.municipality;
        if (!snapshotData.foreman) snapshotData.foreman = vehicle.foreman;
        vehicleIdToSave = refuelingHeader.vehicleId;
    }

    setLoading(true);
    try {
        const totalLiters = cartItems.reduce((acc, curr) => acc + Number(curr.liters || 0), 0);
        const totalCost = cartItems.reduce((acc, curr) => acc + Number(curr.totalCost || 0), 0);
        const mainFuelType = cartItems.length > 1 ? FuelType.OUTROS : cartItems[0].fuelType;

        const newRefueling: RefuelingLog = {
            id: editingRecordId || crypto.randomUUID(),
            date: refuelingHeader.date,
            vehicleId: vehicleIdToSave,
            gasStationId: refuelingHeader.gasStationId,
            fuelType: mainFuelType, 
            liters: Number(totalLiters.toFixed(2)), 
            totalCost: Number(totalCost.toFixed(2)), 
            items: cartItems.map(i => ({ fuelType: i.fuelType, liters: i.liters, totalCost: i.totalCost })),
            invoiceNumber: refuelingHeader.invoiceNumber?.toUpperCase() || '',
            requisitionNumber: refuelingHeader.requisitionNumber?.toUpperCase() || '',
            time: refuelingHeader.time || '', 
            plateSnapshot: snapshotData.plate,
            modelSnapshot: snapshotData.model,
            foremanSnapshot: snapshotData.foreman, 
            contractSnapshot: snapshotData.contract,
            municipalitySnapshot: snapshotData.municipality,
            observation: `[Consolidação de ${cartItems.length} itens]`.toUpperCase()
        };

        await storageService.saveRefueling(newRefueling);
        await loadData();
        resetForms();
    } catch (err: any) { alert(`Erro ao salvar: ${err.message}`); } finally { setLoading(false); }
  };

  const handleEditRefueling = (refueling: RefuelingLog) => {
    if (isReadOnly) return;
    setRefuelingHeader({
        date: refueling.date,
        time: refueling.time || '',
        vehicleId: refueling.vehicleId,
        gasStationId: refueling.gasStationId,
        foremanSnapshot: refueling.foremanSnapshot || '',
        invoiceNumber: refueling.invoiceNumber || '',
        requisitionNumber: refueling.requisitionNumber || ''
    });
    setEditingRecordId(refueling.id);
    setCartItems(refueling.items?.map(i => ({ ...i, id: crypto.randomUUID() })) || [{ id: crypto.randomUUID(), fuelType: refueling.fuelType, liters: refueling.liters, totalCost: refueling.totalCost }]);
    setIsExternal(refueling.vehicleId === 'EXTERNAL');
    setIsEditing(true);
    setShowForm(true);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const resetForms = () => {
    setShowForm(false); setIsEditing(false); setEditingRecordId(null);
    setRefuelingHeader({ date: getTodayLocal(), time: getCurrentTime(), vehicleId: '', gasStationId: '', foremanSnapshot: '', invoiceNumber: '', requisitionNumber: '' });
    setCartItems([]); setIsExternal(false);
  };

  // Helper functions to fix missing references
  const formatDate = (dateStr: string) => {
    if (!dateStr) return '-';
    const [y, m, d] = dateStr.split('-');
    return `${d}/${m}/${y}`;
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val || 0);
  };

  const confirmDelete = (id: string) => {
    if (isReadOnly) return;
    setItemToDelete(id);
    setShowDeleteModal(true);
  };

  const filteredRefuelings = refuelings.filter(r => {
      const rDate = new Date(r.date).getTime();
      const start = filterDateStart ? new Date(filterDateStart).getTime() : null;
      const end = filterDateEnd ? new Date(filterDateEnd).getTime() : null;
      const matchesDate = (!start || rDate >= start) && (!end || rDate <= end);
      const matchesPlate = filterPlate.length === 0 || filterPlate.includes(r.plateSnapshot);
      const matchesStation = filterStation.length === 0 || filterStation.includes(r.gasStationId);
      const matchesFuel = filterFuel.length === 0 || filterFuel.includes(r.fuelType) || (r.items && r.items.some(it => filterFuel.includes(it.fuelType)));
      return matchesDate && matchesPlate && matchesStation && matchesFuel;
  });

  const totalLitersCalculated = filteredRefuelings.reduce((acc, curr) => acc + getEffectiveValues(curr).liters, 0);
  const totalCostCalculated = filteredRefuelings.reduce((acc, curr) => acc + getEffectiveValues(curr).cost, 0);

  const paginatedRefuelings = filteredRefuelings.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()).slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE);

  return (
    <div className="space-y-6">
      <PrintHeader title="Relatório de Abastecimentos" details={<><span>Total Litros: {totalLitersCalculated.toFixed(2)} L</span><span>Total Valor: {formatCurrency(totalCostCalculated)}</span></>} />

      <div className="flex flex-col md:flex-row justify-between items-start gap-4 print:hidden">
        <div><h1 className="text-3xl font-bold text-slate-900 flex items-center gap-3"><Fuel className="text-blue-600" size={32} /> Abastecimento</h1></div>
        <button onClick={handlePrint} className="bg-white border border-slate-300 text-slate-700 px-4 py-2 rounded-lg font-medium flex items-center gap-2 shadow-sm"><Printer size={20} /> Imprimir</button>
      </div>

      <div className="flex bg-slate-100 p-1 rounded-lg w-fit print:hidden">
        <button onClick={() => setActiveTab('REFUELING')} className={`px-6 py-2 rounded-md text-sm font-bold transition-all ${activeTab === 'REFUELING' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>Registros</button>
        <button onClick={() => setActiveTab('STATIONS')} className={`px-6 py-2 rounded-md text-sm font-bold transition-all ${activeTab === 'STATIONS' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>Postos</button>
      </div>

      {activeTab === 'REFUELING' && (
        <div className="space-y-6">
            <div className="bg-white rounded-xl border border-slate-200 shadow-sm print:hidden p-4">
                <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                    <div><label className="block text-xs font-bold text-slate-500 mb-1">Data Início</label><input type="date" className="w-full border rounded p-2" value={filterDateStart} onChange={(e) => setFilterDateStart(e.target.value)} /></div>
                    <div><label className="block text-xs font-bold text-slate-500 mb-1">Data Final</label><input type="date" className="w-full border rounded p-2" value={filterDateEnd} onChange={(e) => setFilterDateEnd(e.target.value)} /></div>
                    <div className="md:col-span-2 flex items-end gap-2">
                        <MultiSelect label="Combustível" options={Object.values(FuelType).map(f => ({value: f, label: f}))} selected={filterFuel} onChange={setFilterFuel} placeholder="Todos" />
                        <button onClick={() => setShowForm(!showForm)} className="bg-blue-600 text-white px-4 py-2 rounded-lg font-bold flex items-center gap-2 h-[42px]"><Plus size={18} /> Novo</button>
                    </div>
                </div>
            </div>

            {showForm && !isReadOnly && (
                <div className="bg-white rounded-xl shadow-lg border p-6 animate-in slide-in-from-top-2 print:hidden">
                    <h3 className="font-bold text-lg mb-6 flex items-center gap-2"><Droplet className="text-blue-500" /> {isEditing ? 'Editar' : 'Novo'} Lançamento Consolidado</h3>
                    <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-8 bg-slate-50 p-4 rounded-lg">
                        <div className="md:col-span-4 flex items-center gap-2 mb-2">
                            <input type="checkbox" checked={isExternal} onChange={e => setIsExternal(e.target.checked)} id="ext" className="w-5 h-5 accent-blue-600" />
                            <label htmlFor="ext" className="text-sm font-bold text-slate-700">Equipamento Externo</label>
                        </div>
                        <div><label className="block text-xs font-bold text-slate-500 mb-1">Data</label><input type="date" value={refuelingHeader.date} onChange={e => setRefuelingHeader({...refuelingHeader, date: e.target.value})} className="w-full border rounded p-2" /></div>
                        {isExternal ? (
                            <div className="md:col-span-2"><input type="text" placeholder="IDENTIFICAÇÃO" value={externalData.identifier} onChange={e => setExternalData({...externalData, identifier: e.target.value.toUpperCase()})} className="w-full border rounded p-2 mt-5" /></div>
                        ) : (
                            <div className="md:col-span-2"><SelectWithSearch label="Veículo" options={vehicles.map(v => ({value: v.id, label: v.plate}))} value={refuelingHeader.vehicleId} onChange={val => setRefuelingHeader({...refuelingHeader, vehicleId: val})} /></div>
                        )}
                        <div className="md:col-span-1"><SelectWithSearch label="Posto" options={stations.map(s => ({value: s.id, label: s.name}))} value={refuelingHeader.gasStationId} onChange={val => setRefuelingHeader({...refuelingHeader, gasStationId: val})} /></div>
                    </div>

                    <div className="bg-blue-50 p-4 rounded-xl border border-blue-200 mb-6 grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
                        <div><label className="block text-xs font-bold text-slate-500 mb-1">Produto</label><select value={currentItem.fuelType || ''} onChange={e => setCurrentItem({...currentItem, fuelType: e.target.value as FuelType})} className="w-full border rounded p-2 bg-white h-[42px]"><option value="">Selecione...</option><optgroup label="COMBUSTÍVEL">{FUEL_TYPES_LIST.map(f => <option key={f} value={f}>{f}</option>)}</optgroup><optgroup label="INSUMOS">{SUPPLY_TYPES_LIST.map(f => <option key={f} value={f}>{f}</option>)}</optgroup></select></div>
                        <div><label className="block text-xs font-bold text-slate-500 mb-1">Qtd</label><input type="number" step="0.01" value={currentItem.liters || ''} onChange={e => setCurrentItem({...currentItem, liters: Number(e.target.value)})} className="w-full border rounded p-2" /></div>
                        <div><label className="block text-xs font-bold text-slate-500 mb-1">Valor</label><input type="number" step="0.01" value={currentItem.totalCost || ''} onChange={e => setCurrentItem({...currentItem, totalCost: Number(e.target.value)})} className="w-full border rounded p-2" /></div>
                        <button type="button" onClick={handleAddItemToCart} className="bg-slate-800 text-white p-2.5 rounded-lg font-bold flex items-center justify-center gap-2 h-[42px]"><Plus size={18} /> Incluir</button>
                    </div>

                    <div className="mb-6 border rounded-xl overflow-hidden">
                        <table className="w-full text-sm">
                            <thead className="bg-slate-100 font-bold"><tr><th className="px-4 py-2 text-left">Item</th><th className="px-4 py-2 text-center">Qtd</th><th className="px-4 py-2 text-right">Valor</th><th className="px-4 py-2 text-center">Ações</th></tr></thead>
                            <tbody className="divide-y">{cartItems.map(item => (<tr key={item.id} className="hover:bg-slate-50"><td className="px-4 py-2 font-bold">{item.fuelType}</td><td className="px-4 py-2 text-center font-mono">{item.liters.toFixed(2)}</td><td className="px-4 py-2 text-right font-bold text-green-700">R$ {item.totalCost.toFixed(2)}</td><td className="px-4 py-2 text-center"><button onClick={() => handleRemoveItemFromCart(item.id)} className="text-red-500 p-1"><Trash2 size={16} /></button></td></tr>))}</tbody>
                        </table>
                    </div>

                    <div className="flex justify-end gap-3 pt-6 border-t"><button type="button" onClick={resetForms} className="px-6 py-2.5 text-slate-600 font-medium">Cancelar</button><button onClick={handleSaveRefueling} disabled={loading || cartItems.length === 0} className="bg-blue-800 text-white px-8 py-2.5 rounded-lg font-bold flex items-center gap-2 shadow-lg disabled:opacity-50">{loading ? <Loader2 className="animate-spin"/> : <Save size={18} />} Salvar Registro</button></div>
                </div>
            )}

             <div className="grid grid-cols-1 md:grid-cols-3 gap-4 print:hidden">
                <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200">
                    <p className="text-xs font-bold text-slate-500 uppercase">Litros Lançados no Período</p>
                    <p className="text-2xl font-black text-blue-800">{totalLitersCalculated.toFixed(2)} L</p>
                    {filterFuel.length > 0 && <p className="text-[10px] text-blue-600 font-bold uppercase mt-1">Filtro Ativo: {filterFuel.join(', ')}</p>}
                </div>
                <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200">
                    <p className="text-xs font-bold text-slate-500 uppercase">Valor Total do Período</p>
                    <p className="text-2xl font-black text-green-700">{formatCurrency(totalCostCalculated)}</p>
                </div>
             </div>

            <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left">
                        <thead className="bg-slate-100 text-slate-600 font-bold uppercase text-xs border-b">
                            <tr><th className="px-6 py-3">Data</th><th className="px-6 py-3">Veículo</th><th className="px-6 py-3">Posto</th><th className="px-6 py-3">Combustível</th><th className="px-6 py-3">Litros</th><th className="px-6 py-3">Valor</th><th className="px-6 py-3 text-center print:hidden">Ações</th></tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {paginatedRefuelings.map(item => {
                                const { liters, cost } = getEffectiveValues(item);
                                const isPartial = filterFuel.length > 0 && item.items && item.items.length > 1 && liters < item.liters;

                                return (
                                    <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                                        <td className="px-6 py-3 font-medium">{formatDate(item.date)}</td>
                                        <td className="px-6 py-3 font-bold">{item.plateSnapshot}</td>
                                        <td className="px-6 py-3">{stations.find(s => s.id === item.gasStationId)?.name}</td>
                                        <td className="px-6 py-3"><span className={`text-[10px] font-bold px-2 py-1 rounded border ${getFuelColor(item.fuelType)}`}>{item.items && item.items.length > 1 ? `DIVERSOS (${item.items.length})` : item.fuelType}</span></td>
                                        <td className="px-6 py-3 font-mono font-bold text-blue-900">
                                            {liters.toFixed(2)} L
                                            {isPartial && <div className="text-[9px] text-slate-400 font-normal">de {item.liters.toFixed(2)}L (Filtrado)</div>}
                                        </td>
                                        <td className="px-6 py-3 font-mono font-bold text-green-700">{formatCurrency(cost)}</td>
                                        <td className="px-6 py-3 print:hidden text-center">
                                            <div className="flex justify-center gap-1">
                                                <button onClick={() => setSelectedTicket(item)} className="p-1.5 text-slate-600 hover:bg-slate-100 rounded"><Receipt size={18} /></button>
                                                {!isReadOnly && <><button onClick={() => handleEditRefueling(item)} className="p-1.5 text-blue-600 hover:bg-blue-50 rounded"><Edit2 size={18} /></button><button onClick={() => confirmDelete(item.id)} className="p-1.5 text-red-600 hover:bg-red-50 rounded"><Trash2 size={18} /></button></>}
                                            </div>
                                        </td>
                                    </tr>
                                );
                            })}
                        </tbody>
                        <tfoot className="bg-slate-50 font-bold text-slate-800 border-t border-slate-200">
                             <tr>
                                 <td colSpan={4} className="px-6 py-3 text-right uppercase text-xs">Somatório Período {filterFuel.length > 0 ? '(Filtrado)' : ''}</td>
                                 <td className="px-6 py-3 text-blue-900">{totalLitersCalculated.toFixed(2)} L</td>
                                 <td className="px-6 py-3 text-green-800">{formatCurrency(totalCostCalculated)}</td>
                                 <td className="print:hidden"></td>
                             </tr>
                        </tfoot>
                    </table>
                </div>
            </div>
        </div>
      )}
      <PasswordModal isOpen={showDeleteModal} onClose={() => setShowDeleteModal(false)} onConfirm={() => { if (itemToDelete) { if (activeTab === 'STATIONS') storageService.deleteGasStation(itemToDelete).then(loadData); else storageService.deleteRefueling(itemToDelete).then(loadData); setShowDeleteModal(false); } }} title="Confirmar Exclusão" />
    </div>
  );
};

export default FuelManagement;

import React, { useState, useEffect } from 'react';
import { GasStation, RefuelingLog, Vehicle, FuelType, ContractType, UserRole, UserProfile, FUEL_TYPES_LIST, SUPPLY_TYPES_LIST, RefuelingItem } from '../types';
import { storageService } from '../services/storage';
import PasswordModal from './PasswordModal';
import { useAuth } from '../contexts/AuthContext';
import { 
  Fuel, Plus, Save, Trash2, Edit2, Droplet, Filter, X, Calendar, Printer, AlertCircle, Users, ChevronDown, ChevronUp, MapPin, Clock, ClipboardList, ChevronLeft, ChevronRight, Loader2, ShoppingCart, Package, DollarSign, Receipt
} from 'lucide-react';
import { PrintHeader } from './PrintHeader';
import MultiSelect, { MultiSelectOption } from './MultiSelect';
import SelectWithSearch from './SelectWithSearch';
import { ParisLogo } from './ParisLogo';

type TabType = 'REFUELING' | 'STATIONS';

const EXTERNAL_EQUIPMENT_TYPES = [
  'BARCO', 'BALSA', 'MOTO', 'CARRO', 'LANCHA', 'MOTOR DE POUPA', 'MOTOPODA', 'GERADOR', 'GALÃO', 'TAMBOR'
];

const ITEMS_PER_PAGE = 50;

interface RefuelingCartItem {
    id: string;
    fuelType: FuelType;
    liters: number;
    totalCost: number;
}

const FuelManagement: React.FC = () => {
  const { user } = useAuth();
  const isReadOnly = user?.role === UserRole.GERENCIA;

  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<TabType>('REFUELING');

  const [stations, setStations] = useState<GasStation[]>([]);
  const [refuelings, setRefuelings] = useState<RefuelingLog[]>([]);
  const [vehicles, setVehicles] = useState<Vehicle[]>([]);

  const [currentPage, setCurrentPage] = useState(1);

  const [filterDateStart, setFilterDateStart] = useState('');
  const [filterDateEnd, setFilterDateEnd] = useState('');
  const [filterPlate, setFilterPlate] = useState<string[]>([]);
  const [filterStation, setFilterStation] = useState<string[]>([]);
  const [filterContract, setFilterContract] = useState<string[]>([]);
  const [filterMunicipality, setFilterMunicipality] = useState<string[]>([]);
  const [filterFuel, setFilterFuel] = useState<string[]>([]);
  const [filterForeman, setFilterForeman] = useState<string[]>([]);

  const [showFilters, setShowFilters] = useState(false);

  const [uniquePlates, setUniquePlates] = useState<string[]>([]);
  const [uniqueContracts, setUniqueContracts] = useState<string[]>([]);
  const [uniqueMunicipalities, setUniqueMunicipalities] = useState<string[]>([]);
  const [uniqueForemen, setUniqueForemen] = useState<string[]>([]);

  const [showForm, setShowForm] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editingRecordId, setEditingRecordId] = useState<string | null>(null);

  const [currentStation, setCurrentStation] = useState<Partial<GasStation>>({});
  const [selectedTicket, setSelectedTicket] = useState<RefuelingLog | null>(null);

  const getTodayLocal = () => {
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const getCurrentTime = () => {
    const now = new Date();
    return now.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
  };

  const [refuelingHeader, setRefuelingHeader] = useState({
      date: getTodayLocal(),
      time: getCurrentTime(),
      vehicleId: '',
      gasStationId: '',
      foremanSnapshot: '',
      invoiceNumber: '',
      requisitionNumber: ''
  });

  const [cartItems, setCartItems] = useState<RefuelingCartItem[]>([]);
  const [currentItem, setCurrentItem] = useState<Partial<RefuelingCartItem>>({
      fuelType: '' as any,
      liters: 0,
      totalCost: 0
  });

  const [isExternal, setIsExternal] = useState(false);
  const [externalData, setExternalData] = useState({
    identifier: '', 
    model: '',
    contract: '',
    municipality: '',
    description: '' 
  });

  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    try {
      const [sData, rData, vData] = await Promise.all([
          storageService.getGasStations(),
          storageService.getRefuelings(),
          storageService.getVehicles()
      ]);

      setStations(sData);
      setRefuelings(rData);
      setVehicles(vData);

      const plates = Array.from(new Set(rData.map(r => r.plateSnapshot))).sort();
      const contracts = Array.from(new Set(rData.map(r => r.contractSnapshot))).sort();
      const cities = Array.from(new Set(rData.map(r => r.municipalitySnapshot))).sort();
      const vehicleTeams = Array.from(new Set(vData.map(v => v.foreman).filter(f => f && f.trim() !== ''))).sort();

      setUniquePlates(plates);
      setUniqueContracts(contracts);
      setUniqueMunicipalities(cities);
      setUniqueForemen(vehicleTeams);
    } catch (e) { console.error(e); } finally { setLoading(false); }
  };

  const handlePrint = () => { window.print(); };

  const getFuelColor = (fuelType: string) => {
    if (fuelType === FuelType.OUTROS || fuelType.includes('DIVERSOS')) return 'bg-purple-100 text-purple-800 border-purple-200';
    switch (fuelType) {
      case FuelType.GASOLINA: return 'bg-orange-100 text-orange-800 border-orange-200'; 
      case FuelType.ETANOL: return 'bg-green-100 text-green-800 border-green-200';
      case FuelType.DIESEL: return 'bg-yellow-100 text-yellow-800 border-yellow-200';
      case FuelType.DIESEL_S10: return 'bg-slate-100 text-slate-800 border-slate-200';
      default: return 'bg-gray-100 text-gray-800 border-gray-200';
    }
  };

  const getEffectiveValues = (log: RefuelingLog) => {
      if (filterFuel.length === 0) {
          return { liters: log.liters || 0, cost: log.totalCost || 0 };
      }

      if (!log.items || log.items.length === 0) {
          const matches = filterFuel.includes(log.fuelType);
          return {
              liters: matches ? (log.liters || 0) : 0,
              cost: matches ? (log.totalCost || 0) : 0
          };
      }

      const filteredItems = log.items.filter(it => filterFuel.includes(it.fuelType));
      return {
          liters: filteredItems.reduce((acc, it) => acc + Number(it.liters || 0), 0),
          cost: filteredItems.reduce((acc, it) => acc + Number(it.totalCost || 0), 0)
      };
  };

  const handleAddItemToCart = () => {
      if (!currentItem.fuelType) { alert("Selecione o produto."); return; }
      const qty = Number(currentItem.liters || 0);
      const cost = Number(currentItem.totalCost || 0);
      setCartItems(prev => [...prev, { id: crypto.randomUUID(), fuelType: currentItem.fuelType as FuelType, liters: qty, totalCost: cost }]);
      setCurrentItem({ fuelType: '' as any, liters: 0, totalCost: 0 });
  };

  const handleUpdateCartItem = (id: string, field: 'liters' | 'totalCost', value: string) => {
      const numValue = value === '' ? 0 : Number(value);
      setCartItems(prev => prev.map(item => item.id === id ? { ...item, [field]: numValue } : item));
  };

  const handleRemoveItemFromCart = (id: string) => { setCartItems(prev => prev.filter(item => item.id !== id)); };

  const handleSaveRefueling = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly || !refuelingHeader.gasStationId || cartItems.length === 0) return;

    let snapshotData = { plate: '', model: '', contract: '', municipality: '', foreman: refuelingHeader.foremanSnapshot || '' };
    let vehicleIdToSave = '';

    if (isExternal) {
        snapshotData.plate = externalData.identifier.toUpperCase();
        snapshotData.model = externalData.model.toUpperCase();
        snapshotData.contract = externalData.contract;
        snapshotData.municipality = externalData.municipality.toUpperCase();
        vehicleIdToSave = 'EXTERNAL';
    } else {
        const vehicle = vehicles.find(v => v.id === refuelingHeader.vehicleId);
        if (!vehicle) return;
        snapshotData.plate = vehicle.plate;
        snapshotData.model = vehicle.model || '';
        snapshotData.contract = vehicle.contract;
        snapshotData.municipality = vehicle.municipality;
        if (!snapshotData.foreman) snapshotData.foreman = vehicle.foreman;
        vehicleIdToSave = refuelingHeader.vehicleId;
    }

    setLoading(true);
    try {
        // CORREÇÃO: Somar litros de TODOS os itens do carrinho
        const totalLiters = cartItems.reduce((acc, curr) => acc + Number(curr.liters || 0), 0);
        const totalCost = cartItems.reduce((acc, curr) => acc + Number(curr.totalCost || 0), 0);

        // Se houver mais de um tipo, marcamos como "DIVERSOS" (OUTROS)
        const mainFuelType = cartItems.length > 1 ? FuelType.OUTROS : cartItems[0].fuelType;

        const newRefueling: RefuelingLog = {
            id: editingRecordId || crypto.randomUUID(),
            date: refuelingHeader.date,
            vehicleId: vehicleIdToSave,
            gasStationId: refuelingHeader.gasStationId,
            fuelType: mainFuelType, 
            liters: Number(totalLiters.toFixed(2)), 
            totalCost: Number(totalCost.toFixed(2)), 
            items: cartItems.map(i => ({ fuelType: i.fuelType, liters: i.liters, totalCost: i.totalCost })),
            invoiceNumber: refuelingHeader.invoiceNumber?.toUpperCase() || '',
            requisitionNumber: refuelingHeader.requisitionNumber?.toUpperCase() || '',
            time: refuelingHeader.time || '', 
            plateSnapshot: snapshotData.plate,
            modelSnapshot: snapshotData.model,
            foremanSnapshot: snapshotData.foreman, 
            contractSnapshot: snapshotData.contract,
            municipalitySnapshot: snapshotData.municipality,
            observation: `[LANÇAMENTO CONSOLIDADO: ${cartItems.length} ITENS]`.toUpperCase()
        };

        await storageService.saveRefueling(newRefueling);
        await loadData();
        resetForms();
    } catch (err: any) { alert(`Erro ao salvar: ${err.message}`); } finally { setLoading(false); }
  };

  const handleEditRefueling = (refueling: RefuelingLog) => {
    if (isReadOnly) return;
    setRefuelingHeader({
        date: refueling.date,
        time: refueling.time || '',
        vehicleId: refueling.vehicleId,
        gasStationId: refueling.gasStationId,
        foremanSnapshot: refueling.foremanSnapshot || '',
        invoiceNumber: refueling.invoiceNumber || '',
        requisitionNumber: refueling.requisitionNumber || ''
    });
    setEditingRecordId(refueling.id);

    // Reconstroi o carrinho a partir dos itens ou do registro principal
    if (refueling.items && refueling.items.length > 0) {
        setCartItems(refueling.items.map(i => ({ ...i, id: crypto.randomUUID() })));
    } else {
        setCartItems([{ id: crypto.randomUUID(), fuelType: refueling.fuelType, liters: refueling.liters, totalCost: refueling.totalCost }]);
    }

    setIsExternal(refueling.vehicleId === 'EXTERNAL');
    setIsEditing(true);
    setShowForm(true);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const resetForms = () => {
    setShowForm(false); setIsEditing(false); setEditingRecordId(null);
    setRefuelingHeader({ date: getTodayLocal(), time: getCurrentTime(), vehicleId: '', gasStationId: '', foremanSnapshot: '', invoiceNumber: '', requisitionNumber: '' });
    setCartItems([]); setIsExternal(false);
  };

  const formatDate = (dateStr: string) => {
    if (!dateStr) return '-';
    const [y, m, d] = dateStr.split('-');
    return `${d}/${m}/${y}`;
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val || 0);
  };

  const confirmDelete = (id: string) => {
    if (isReadOnly) return;
    setItemToDelete(id);
    setShowDeleteModal(true);
  };

  const filteredRefuelings = refuelings.filter(r => {
      const rDate = new Date(r.date).getTime();
      const start = filterDateStart ? new Date(filterDateStart).getTime() : null;
      const end = filterDateEnd ? new Date(filterDateEnd).getTime() : null;
      const matchesDate = (!start || rDate >= start) && (!end || rDate <= end);
      const matchesPlate = filterPlate.length === 0 || filterPlate.includes(r.plateSnapshot);
      const matchesStation = filterStation.length === 0 || filterStation.includes(r.gasStationId);
      const matchesFuel = filterFuel.length === 0 || filterFuel.includes(r.fuelType) || (r.items && r.items.some(it => filterFuel.includes(it.fuelType)));
      return matchesDate && matchesPlate && matchesStation && matchesFuel;
  });

  const totalLitersCalculated = filteredRefuelings.reduce((acc, curr) => acc + getEffectiveValues(curr).liters, 0);
  const totalCostCalculated = filteredRefuelings.reduce((acc, curr) => acc + getEffectiveValues(curr).cost, 0);

  const paginatedRefuelings = filteredRefuelings.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()).slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE);

  return (
    <div className="space-y-6">
      <PrintHeader title="Relatório de Abastecimentos" details={<><span>Total Litros: {totalLitersCalculated.toFixed(2)} L</span><span>Total Valor: {formatCurrency(totalCostCalculated)}</span></>} />

      <div className="flex flex-col md:flex-row justify-between items-start gap-4 print:hidden">
        <div><h1 className="text-3xl font-bold text-slate-900 flex items-center gap-3"><Fuel className="text-blue-600" size={32} /> Abastecimento</h1></div>
        <button onClick={handlePrint} className="bg-white border border-slate-300 text-slate-700 px-4 py-2 rounded-lg font-medium flex items-center gap-2 shadow-sm"><Printer size={20} /> Imprimir</button>
      </div>

      <div className="flex bg-slate-100 p-1 rounded-lg w-fit print:hidden">
        <button onClick={() => setActiveTab('REFUELING')} className={`px-6 py-2 rounded-md text-sm font-bold transition-all ${activeTab === 'REFUELING' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>Registros</button>
        <button onClick={() => setActiveTab('STATIONS')} className={`px-6 py-2 rounded-md text-sm font-bold transition-all ${activeTab === 'STATIONS' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>Postos</button>
      </div>

      {activeTab === 'REFUELING' && (
        <div className="space-y-6">
            <div className="bg-white rounded-xl border border-slate-200 shadow-sm print:hidden p-4">
                <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                    <div><label className="block text-xs font-bold text-slate-500 mb-1">Data Início</label><input type="date" className="w-full border rounded p-2" value={filterDateStart} onChange={(e) => setFilterDateStart(e.target.value)} /></div>
                    <div><label className="block text-xs font-bold text-slate-500 mb-1">Data Final</label><input type="date" className="w-full border rounded p-2" value={filterDateEnd} onChange={(e) => setFilterDateEnd(e.target.value)} /></div>
                    <div className="md:col-span-2 flex items-end gap-2">
                        <MultiSelect label="Combustível" options={Object.values(FuelType).map(f => ({value: f, label: f}))} selected={filterFuel} onChange={setFilterFuel} placeholder="Todos" />
                        <button onClick={() => setShowForm(!showForm)} className="bg-blue-600 text-white px-4 py-2 rounded-lg font-bold flex items-center gap-2 h-[42px]"><Plus size={18} /> Novo</button>
                    </div>
                </div>
            </div>

            {showForm && !isReadOnly && (
                <div className="bg-white rounded-xl shadow-lg border p-6 animate-in slide-in-from-top-2 print:hidden">
                    <h3 className="font-bold text-lg mb-6 flex items-center gap-2"><Droplet className="text-blue-500" /> {isEditing ? 'Editar' : 'Novo'} Lançamento de Abastecimento</h3>

                    <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-8 bg-slate-50 p-4 rounded-lg">
                        <div className="md:col-span-4 flex items-center gap-2 mb-2">
                            <input type="checkbox" checked={isExternal} onChange={e => setIsExternal(e.target.checked)} id="ext" className="w-5 h-5 accent-blue-600" />
                            <label htmlFor="ext" className="text-sm font-bold text-slate-700">Equipamento Externo / Não Cadastrado</label>
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-slate-500 mb-1">Data</label>
                            <input type="date" value={refuelingHeader.date} onChange={e => setRefuelingHeader({...refuelingHeader, date: e.target.value})} className="w-full border rounded p-2" />
                        </div>
                        {isExternal ? (
                            <div className="md:col-span-2">
                                <label className="block text-xs font-bold text-slate-500 mb-1">Identificação</label>
                                <input type="text" placeholder="EX: GERADOR 01" value={externalData.identifier} onChange={e => setExternalData({...externalData, identifier: e.target.value.toUpperCase()})} className="w-full border rounded p-2" />
                            </div>
                        ) : (
                            <div className="md:col-span-2">
                                <SelectWithSearch label="Veículo" options={vehicles.map(v => ({value: v.id, label: v.plate}))} value={refuelingHeader.vehicleId} onChange={val => setRefuelingHeader({...refuelingHeader, vehicleId: val})} />
                            </div>
                        )}
                        <div className="md:col-span-1">
                            <SelectWithSearch label="Posto" options={stations.map(s => ({value: s.id, label: s.name}))} value={refuelingHeader.gasStationId} onChange={val => setRefuelingHeader({...refuelingHeader, gasStationId: val})} />
                        </div>
                    </div>

                    <div className="bg-blue-50 p-4 rounded-xl border border-blue-200 mb-6 grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
                        <div className="md:col-span-1">
                            <label className="block text-xs font-bold text-slate-500 mb-1">Produto / Combustível</label>
                            <select value={currentItem.fuelType || ''} onChange={e => setCurrentItem({...currentItem, fuelType: e.target.value as FuelType})} className="w-full border rounded p-2 bg-white h-[42px]">
                                <option value="">Selecione...</option>
                                <optgroup label="COMBUSTÍVEL">{FUEL_TYPES_LIST.map(f => <option key={f} value={f}>{f}</option>)}</optgroup>
                                <optgroup label="INSUMOS">{SUPPLY_TYPES_LIST.map(f => <option key={f} value={f}>{f}</option>)}</optgroup>
                            </select>
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-slate-500 mb-1">Qtd (Litros/Un)</label>
                            <input type="number" step="0.01" value={currentItem.liters || ''} onChange={e => setCurrentItem({...currentItem, liters: Number(e.target.value)})} className="w-full border rounded p-2" />
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-slate-500 mb-1">Valor Total (R$)</label>
                            <input type="number" step="0.01" value={currentItem.totalCost || ''} onChange={e => setCurrentItem({...currentItem, totalCost: Number(e.target.value)})} className="w-full border rounded p-2" />
                        </div>
                        <button type="button" onClick={handleAddItemToCart} className="bg-slate-800 text-white p-2.5 rounded-lg font-bold flex items-center justify-center gap-2 h-[42px] hover:bg-slate-900 transition-colors">
                            <Plus size={18} /> Adicionar Item
                        </button>
                    </div>

                    <div className="mb-6 border rounded-xl overflow-hidden shadow-sm">
                        <table className="w-full text-sm">
                            <thead className="bg-slate-100 font-bold border-b">
                                <tr>
                                    <th className="px-4 py-2 text-left">Item</th>
                                    <th className="px-4 py-2 text-center">Qtd</th>
                                    <th className="px-4 py-2 text-right">Valor Total</th>
                                    <th className="px-4 py-2 text-center w-16">Ações</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y">
                                {cartItems.length === 0 ? (
                                    <tr><td colSpan={4} className="px-4 py-8 text-center text-slate-400 italic">Nenhum item adicionado à lista.</td></tr>
                                ) : (
                                    cartItems.map(item => (
                                        <tr key={item.id} className="hover:bg-slate-50">
                                            <td className="px-4 py-2 font-bold text-slate-700">{item.fuelType}</td>
                                            <td className="px-4 py-2 text-center font-mono">{item.liters.toFixed(2)}</td>
                                            <td className="px-4 py-2 text-right font-bold text-green-700">{formatCurrency(item.totalCost)}</td>
                                            <td className="px-4 py-2 text-center">
                                                <button onClick={() => handleRemoveItemFromCart(item.id)} className="text-red-500 p-1 hover:bg-red-50 rounded"><Trash2 size={16} /></button>
                                            </td>
                                        </tr>
                                    ))
                                )}
                            </tbody>
                            {cartItems.length > 0 && (
                                <tfoot className="bg-slate-50 font-black border-t">
                                    <tr>
                                        <td colSpan={1} className="px-4 py-2 text-right text-slate-500">SOMA:</td>
                                        <td className="px-4 py-2 text-center text-blue-800">{cartItems.reduce((a,b) => a + b.liters, 0).toFixed(2)} L</td>
                                        <td className="px-4 py-2 text-right text-green-800">{formatCurrency(cartItems.reduce((a,b) => a + b.totalCost, 0))}</td>
                                        <td></td>
                                    </tr>
                                </tfoot>
                            )}
                        </table>
                    </div>

                    <div className="flex justify-end gap-3 pt-6 border-t">
                        <button type="button" onClick={resetForms} className="px-6 py-2.5 text-slate-600 font-medium hover:bg-slate-100 rounded-lg">Cancelar</button>
                        <button onClick={handleSaveRefueling} disabled={loading || cartItems.length === 0} className="bg-blue-800 text-white px-8 py-2.5 rounded-lg font-bold flex items-center gap-2 shadow-lg disabled:opacity-50 hover:bg-blue-900 transition-all transform active:scale-95">
                            {loading ? <Loader2 className="animate-spin" size={18}/> : <Save size={18} />} 
                            Salvar Registro Completo
                        </button>
                    </div>
                </div>
            )}

             <div className="grid grid-cols-1 md:grid-cols-3 gap-4 print:hidden">
                <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200">
                    <p className="text-xs font-bold text-slate-500 uppercase">Litros Totais do Período</p>
                    <p className="text-2xl font-black text-blue-800">{totalLitersCalculated.toFixed(2)} L</p>
                    {filterFuel.length > 0 && <p className="text-[10px] text-blue-600 font-bold uppercase mt-1">Filtro: {filterFuel.join(', ')}</p>}
                </div>
                <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200">
                    <p className="text-xs font-bold text-slate-500 uppercase">Valor Total (Todos Itens)</p>
                    <p className="text-2xl font-black text-green-700">{formatCurrency(totalCostCalculated)}</p>
                </div>
                <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200">
                    <p className="text-xs font-bold text-slate-500 uppercase">Operações Realizadas</p>
                    <p className="text-2xl font-black text-slate-800">{filteredRefuelings.length}</p>
                </div>
             </div>

            <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left">
                        <thead className="bg-slate-100 text-slate-600 font-bold uppercase text-xs border-b">
                            <tr>
                                <th className="px-6 py-3">Data</th>
                                <th className="px-6 py-3">Veículo</th>
                                <th className="px-6 py-3">Posto</th>
                                <th className="px-6 py-3">Produtos</th>
                                <th className="px-6 py-3">Litros Totais</th>
                                <th className="px-6 py-3">Valor Total</th>
                                <th className="px-6 py-3 text-center print:hidden">Ações</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {paginatedRefuelings.length === 0 ? (
                                <tr><td colSpan={7} className="px-6 py-12 text-center text-slate-400 italic">Nenhum registro encontrado para estes filtros.</td></tr>
                            ) : (
                                paginatedRefuelings.map(item => {
                                    const { liters, cost } = getEffectiveValues(item);
                                    const isMultiple = item.items && item.items.length > 1;
                                    const isPartial = filterFuel.length > 0 && isMultiple && liters < item.liters;

                                    return (
                                        <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                                            <td className="px-6 py-3 font-medium">{formatDate(item.date)}</td>
                                            <td className="px-6 py-3 font-bold text-slate-800">{item.plateSnapshot}</td>
                                            <td className="px-6 py-3 text-slate-600">{stations.find(s => s.id === item.gasStationId)?.name || 'N/A'}</td>
                                            <td className="px-6 py-3">
                                                <span className={`text-[10px] font-bold px-2 py-1 rounded border ${getFuelColor(item.fuelType)}`}>
                                                    {isMultiple ? `DIVERSOS (${item.items?.length})` : item.fuelType}
                                                </span>
                                            </td>
                                            <td className="px-6 py-3 font-mono font-bold text-blue-900">
                                                {liters.toFixed(2)} L
                                                {isPartial && <div className="text-[9px] text-slate-400 font-normal">de {item.liters.toFixed(2)}L (Filtro)</div>}
                                            </td>
                                            <td className="px-6 py-3 font-mono font-bold text-green-700">{formatCurrency(cost)}</td>
                                            <td className="px-6 py-3 print:hidden text-center">
                                                <div className="flex justify-center gap-1">
                                                    <button onClick={() => setSelectedTicket(item)} className="p-1.5 text-slate-600 hover:bg-slate-100 rounded" title="Ver Bilhete"><Receipt size={18} /></button>
                                                    {!isReadOnly && (
                                                        <>
                                                            <button onClick={() => handleEditRefueling(item)} className="p-1.5 text-blue-600 hover:bg-blue-50 rounded" title="Editar"><Edit2 size={18} /></button>
                                                            <button onClick={() => confirmDelete(item.id)} className="p-1.5 text-red-600 hover:bg-red-50 rounded" title="Excluir"><Trash2 size={18} /></button>
                                                        </>
                                                    )}
                                                </div>
                                            </td>
                                        </tr>
                                    );
                                })
                            )}
                        </tbody>
                        <tfoot className="bg-slate-50 font-bold text-slate-800 border-t border-slate-200">
                             <tr>
                                 <td colSpan={4} className="px-6 py-3 text-right uppercase text-xs">Total do Período {filterFuel.length > 0 ? '(Filtrado)' : ''}</td>
                                 <td className="px-6 py-3 text-blue-900">{totalLitersCalculated.toFixed(2)} L</td>
                                 <td className="px-6 py-3 text-green-800">{formatCurrency(totalCostCalculated)}</td>
                                 <td className="print:hidden"></td>
                             </tr>
                        </tfoot>
                    </table>
                </div>
            </div>
        </div>
      )}

      <PasswordModal isOpen={showDeleteModal} onClose={() => setShowDeleteModal(false)} onConfirm={() => { if (itemToDelete) { if (activeTab === 'STATIONS') storageService.deleteGasStation(itemToDelete).then(loadData); else storageService.deleteRefueling(itemToDelete).then(loadData); setShowDeleteModal(false); } }} title="Confirmar Exclusão" />
    </div>
  );
};

export default FuelManagement;

import React, { useState, useEffect } from 'react';
import { GasStation, RefuelingLog, Vehicle, FuelType, ContractType, UserRole, UserProfile, FUEL_TYPES_LIST, SUPPLY_TYPES_LIST, RefuelingItem } from '../types';
import { storageService } from '../services/storage';
import PasswordModal from './PasswordModal';
import { useAuth } from '../contexts/AuthContext';
import { 
  Fuel, Plus, Save, Trash2, Edit2, Droplet, Filter, X, Calendar, Printer, AlertCircle, Users, ChevronDown, ChevronUp, MapPin, Clock, ClipboardList, ChevronLeft, ChevronRight, Loader2, ShoppingCart, Package, DollarSign, Receipt
} from 'lucide-react';
import { PrintHeader } from './PrintHeader';
import MultiSelect, { MultiSelectOption } from './MultiSelect';
import SelectWithSearch from './SelectWithSearch';
import { ParisLogo } from './ParisLogo';

type TabType = 'REFUELING' | 'STATIONS';

const EXTERNAL_EQUIPMENT_TYPES = [
  'BARCO', 'BALSA', 'MOTO', 'CARRO', 'LANCHA', 'MOTOR DE POUPA', 'MOTOPODA', 'GERADOR', 'GALÃO', 'TAMBOR'
];

const ITEMS_PER_PAGE = 50;

interface RefuelingCartItem {
    id: string;
    fuelType: FuelType;
    liters: number;
    totalCost: number;
}

const FuelManagement: React.FC = () => {
  const { user } = useAuth();
  const isReadOnly = user?.role === UserRole.GERENCIA;

  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<TabType>('REFUELING');

  const [stations, setStations] = useState<GasStation[]>([]);
  const [refuelings, setRefuelings] = useState<RefuelingLog[]>([]);
  const [vehicles, setVehicles] = useState<Vehicle[]>([]);

  const [currentPage, setCurrentPage] = useState(1);

  const [filterDateStart, setFilterDateStart] = useState('');
  const [filterDateEnd, setFilterDateEnd] = useState('');
  const [filterPlate, setFilterPlate] = useState<string[]>([]);
  const [filterStation, setFilterStation] = useState<string[]>([]);
  const [filterContract, setFilterContract] = useState<string[]>([]);
  const [filterMunicipality, setFilterMunicipality] = useState<string[]>([]);
  const [filterFuel, setFilterFuel] = useState<string[]>([]);
  const [filterForeman, setFilterForeman] = useState<string[]>([]);

  const [showFilters, setShowFilters] = useState(false);

  const [uniquePlates, setUniquePlates] = useState<string[]>([]);
  const [uniqueContracts, setUniqueContracts] = useState<string[]>([]);
  const [uniqueMunicipalities, setUniqueMunicipalities] = useState<string[]>([]);
  const [uniqueForemen, setUniqueForemen] = useState<string[]>([]);

  const [showForm, setShowForm] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editingRecordId, setEditingRecordId] = useState<string | null>(null);

  const [currentStation, setCurrentStation] = useState<Partial<GasStation>>({});
  const [selectedTicket, setSelectedTicket] = useState<RefuelingLog | null>(null);

  const getTodayLocal = () => {
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const getCurrentTime = () => {
    const now = new Date();
    return now.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
  };

  const [refuelingHeader, setRefuelingHeader] = useState({
      date: getTodayLocal(),
      time: getCurrentTime(),
      vehicleId: '',
      gasStationId: '',
      foremanSnapshot: '',
      invoiceNumber: '',
      requisitionNumber: ''
  });

  const [cartItems, setCartItems] = useState<RefuelingCartItem[]>([]);
  const [currentItem, setCurrentItem] = useState<Partial<RefuelingCartItem>>({
      fuelType: '' as any,
      liters: 0,
      totalCost: 0
  });

  const [isExternal, setIsExternal] = useState(false);
  const [externalData, setExternalData] = useState({
    identifier: '', 
    model: '',
    contract: '',
    municipality: '',
    description: '' 
  });

  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    try {
      const [sData, rData, vData] = await Promise.all([
          storageService.getGasStations(),
          storageService.getRefuelings(),
          storageService.getVehicles()
      ]);

      setStations(sData);
      setRefuelings(rData);
      setVehicles(vData);

      const plates = Array.from(new Set(rData.map(r => r.plateSnapshot))).sort();
      const contracts = Array.from(new Set(rData.map(r => r.contractSnapshot))).sort();
      const cities = Array.from(new Set(rData.map(r => r.municipalitySnapshot))).sort();
      const vehicleTeams = Array.from(new Set(vData.map(v => v.foreman).filter(f => f && f.trim() !== ''))).sort();

      setUniquePlates(plates);
      setUniqueContracts(contracts);
      setUniqueMunicipalities(cities);
      setUniqueForemen(vehicleTeams);
    } catch (e) { console.error(e); } finally { setLoading(false); }
  };

  const handlePrint = () => { window.print(); };

  const getFuelColor = (fuelType: string) => {
    if (fuelType === FuelType.OUTROS || fuelType.includes('DIVERSOS')) return 'bg-purple-100 text-purple-800 border-purple-200';
    switch (fuelType) {
      case FuelType.GASOLINA: return 'bg-orange-100 text-orange-800 border-orange-200'; 
      case FuelType.ETANOL: return 'bg-green-100 text-green-800 border-green-200';
      case FuelType.DIESEL: return 'bg-yellow-100 text-yellow-800 border-yellow-200';
      case FuelType.DIESEL_S10: return 'bg-slate-100 text-slate-800 border-slate-200';
      default: return 'bg-gray-100 text-gray-800 border-gray-200';
    }
  };

  /**
   * FUNÇÃO CRÍTICA: getEffectiveValues
   * Retorna os valores reais (litros e custo) considerando filtros e itens internos.
   */
  const getEffectiveValues = (log: RefuelingLog) => {
      // Se houver array de itens detalhados, usamos eles como fonte primária
      if (log.items && log.items.length > 0) {
          const itemsToSum = filterFuel.length > 0 
              ? log.items.filter(it => filterFuel.includes(it.fuelType)) 
              : log.items;

          return {
              liters: itemsToSum.reduce((acc, it) => acc + Number(it.liters || 0), 0),
              cost: itemsToSum.reduce((acc, it) => acc + Number(it.totalCost || 0), 0)
          };
      }

      // Fallback para registros legados (sem array de itens)
      const matches = filterFuel.length === 0 || filterFuel.includes(log.fuelType);
      return {
          liters: matches ? (log.liters || 0) : 0,
          cost: matches ? (log.totalCost || 0) : 0
      };
  };

  const handleAddItemToCart = () => {
      if (!currentItem.fuelType) { alert("Selecione o produto."); return; }
      const qty = Number(currentItem.liters || 0);
      const cost = Number(currentItem.totalCost || 0);
      setCartItems(prev => [...prev, { id: crypto.randomUUID(), fuelType: currentItem.fuelType as FuelType, liters: qty, totalCost: cost }]);
      setCurrentItem({ fuelType: '' as any, liters: 0, totalCost: 0 });
  };

  const handleUpdateCartItem = (id: string, field: 'liters' | 'totalCost', value: string) => {
      const numValue = value === '' ? 0 : Number(value);
      setCartItems(prev => prev.map(item => item.id === id ? { ...item, [field]: numValue } : item));
  };

  const handleRemoveItemFromCart = (id: string) => { setCartItems(prev => prev.filter(item => item.id !== id)); };

  const handleSaveRefueling = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly || !refuelingHeader.gasStationId || cartItems.length === 0) return;

    let snapshotData = { plate: '', model: '', contract: '', municipality: '', foreman: refuelingHeader.foremanSnapshot || '' };
    let vehicleIdToSave = '';

    if (isExternal) {
        snapshotData.plate = externalData.identifier.toUpperCase();
        snapshotData.model = externalData.model.toUpperCase();
        snapshotData.contract = externalData.contract;
        snapshotData.municipality = externalData.municipality.toUpperCase();
        vehicleIdToSave = 'EXTERNAL';
    } else {
        const vehicle = vehicles.find(v => v.id === refuelingHeader.vehicleId);
        if (!vehicle) return;
        snapshotData.plate = vehicle.plate;
        snapshotData.model = vehicle.model || '';
        snapshotData.contract = vehicle.contract;
        snapshotData.municipality = vehicle.municipality;
        if (!snapshotData.foreman) snapshotData.foreman = vehicle.foreman;
        vehicleIdToSave = refuelingHeader.vehicleId;
    }

    setLoading(true);
    try {
        // SOMA DEFINITIVA DE TODOS OS ITENS
        const totalLiters = cartItems.reduce((acc, curr) => acc + Number(curr.liters || 0), 0);
        const totalCost = cartItems.reduce((acc, curr) => acc + Number(curr.totalCost || 0), 0);

        const mainFuelType = cartItems.length > 1 ? FuelType.OUTROS : cartItems[0].fuelType;

        const newRefueling: RefuelingLog = {
            id: editingRecordId || crypto.randomUUID(),
            date: refuelingHeader.date,
            vehicleId: vehicleIdToSave,
            gasStationId: refuelingHeader.gasStationId,
            fuelType: mainFuelType, 
            liters: Number(totalLiters.toFixed(2)), 
            totalCost: Number(totalCost.toFixed(2)), 
            items: cartItems.map(i => ({ fuelType: i.fuelType, liters: i.liters, totalCost: i.totalCost })),
            invoiceNumber: refuelingHeader.invoiceNumber?.toUpperCase() || '',
            requisitionNumber: refuelingHeader.requisitionNumber?.toUpperCase() || '',
            time: refuelingHeader.time || '', 
            plateSnapshot: snapshotData.plate,
            modelSnapshot: snapshotData.model,
            foremanSnapshot: snapshotData.foreman, 
            contractSnapshot: snapshotData.contract,
            municipalitySnapshot: snapshotData.municipality,
            observation: `[TOTAL ${cartItems.length} ITENS: ${totalLiters.toFixed(2)}L / R$ ${totalCost.toFixed(2)}]`.toUpperCase()
        };

        await storageService.saveRefueling(newRefueling);
        await loadData();
        resetForms();
        alert("Registro salvo com sucesso!");
    } catch (err: any) { alert(`Erro ao salvar: ${err.message}`); } finally { setLoading(false); }
  };

  const handleEditRefueling = (refueling: RefuelingLog) => {
    if (isReadOnly) return;
    setRefuelingHeader({
        date: refueling.date,
        time: refueling.time || '',
        vehicleId: refueling.vehicleId,
        gasStationId: refueling.gasStationId,
        foremanSnapshot: refueling.foremanSnapshot || '',
        invoiceNumber: refueling.invoiceNumber || '',
        requisitionNumber: refueling.requisitionNumber || ''
    });
    setEditingRecordId(refueling.id);

    if (refueling.items && refueling.items.length > 0) {
        setCartItems(refueling.items.map(i => ({ ...i, id: crypto.randomUUID() })));
    } else {
        setCartItems([{ id: crypto.randomUUID(), fuelType: refueling.fuelType, liters: refueling.liters, totalCost: refueling.totalCost }]);
    }

    setIsExternal(refueling.vehicleId === 'EXTERNAL');
    setIsEditing(true);
    setShowForm(true);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const resetForms = () => {
    setShowForm(false); setIsEditing(false); setEditingRecordId(null);
    setRefuelingHeader({ date: getTodayLocal(), time: getCurrentTime(), vehicleId: '', gasStationId: '', foremanSnapshot: '', invoiceNumber: '', requisitionNumber: '' });
    setCartItems([]); setIsExternal(false);
  };

  const formatDate = (dateStr: string) => {
    if (!dateStr) return '-';
    const [y, m, d] = dateStr.split('-');
    return `${d}/${m}/${y}`;
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val || 0);
  };

  const confirmDelete = (id: string) => {
    if (isReadOnly) return;
    setItemToDelete(id);
    setShowDeleteModal(true);
  };

  const filteredRefuelings = refuelings.filter(r => {
      const rDate = new Date(r.date).getTime();
      const start = filterDateStart ? new Date(filterDateStart).getTime() : null;
      const end = filterDateEnd ? new Date(filterDateEnd).getTime() : null;
      const matchesDate = (!start || rDate >= start) && (!end || rDate <= end);
      const matchesPlate = filterPlate.length === 0 || filterPlate.includes(r.plateSnapshot);
      const matchesStation = filterStation.length === 0 || filterStation.includes(r.gasStationId);
      const matchesContract = filterContract.length === 0 || filterContract.includes(r.contractSnapshot);
      const matchesCity = filterMunicipality.length === 0 || filterMunicipality.includes(r.municipalitySnapshot);

      const matchesFuel = filterFuel.length === 0 || 
                         filterFuel.includes(r.fuelType) || 
                         (r.items && r.items.some(it => filterFuel.includes(it.fuelType)));

      return matchesDate && matchesPlate && matchesStation && matchesFuel && matchesContract && matchesCity;
  });

  // TOTAIS DO PERÍODO USANDO getEffectiveValues (Para respeitar filtros se ativos)
  const totalLitersCalculated = filteredRefuelings.reduce((acc, curr) => acc + getEffectiveValues(curr).liters, 0);
  const totalCostCalculated = filteredRefuelings.reduce((acc, curr) => acc + getEffectiveValues(curr).cost, 0);

  const paginatedRefuelings = filteredRefuelings
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())
    .slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE);

  return (
    <div className="space-y-6">
      <PrintHeader title="Relatório de Abastecimentos" details={<><span>Total Litros: {totalLitersCalculated.toFixed(2)} L</span><span>Total Valor: {formatCurrency(totalCostCalculated)}</span></>} />

      <div className="flex flex-col md:flex-row justify-between items-start gap-4 print:hidden">
        <div>
            <h1 className="text-3xl font-bold text-slate-900 flex items-center gap-3">
                <Fuel className="text-blue-600" size={32} /> Abastecimento
            </h1>
            <p className="text-slate-500">Gestão de consumo e custos de frota.</p>
        </div>
        <button onClick={handlePrint} className="bg-white border border-slate-300 text-slate-700 px-4 py-2 rounded-lg font-medium flex items-center gap-2 shadow-sm hover:bg-slate-50 transition-colors"><Printer size={20} /> Imprimir Relatório</button>
      </div>

      <div className="flex bg-slate-200 p-1 rounded-lg w-fit print:hidden">
        <button onClick={() => {setActiveTab('REFUELING'); resetForms();}} className={`px-6 py-2 rounded-md text-sm font-bold transition-all ${activeTab === 'REFUELING' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>Registros</button>
        <button onClick={() => {setActiveTab('STATIONS'); resetForms();}} className={`px-6 py-2 rounded-md text-sm font-bold transition-all ${activeTab === 'STATIONS' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>Postos</button>
      </div>

      {activeTab === 'REFUELING' && (
        <div className="space-y-6">
            <div className="bg-white rounded-xl border border-slate-200 shadow-sm print:hidden p-4">
                <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                    <div>
                        <label className="block text-xs font-bold text-slate-500 mb-1">Data Início</label>
                        <input type="date" className="w-full border border-slate-300 rounded-lg p-2 outline-none focus:border-blue-500" value={filterDateStart} onChange={(e) => setFilterDateStart(e.target.value)} />
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-slate-500 mb-1">Data Final</label>
                        <input type="date" className="w-full border border-slate-300 rounded-lg p-2 outline-none focus:border-blue-500" value={filterDateEnd} onChange={(e) => setFilterDateEnd(e.target.value)} />
                    </div>
                    <div className="md:col-span-2 flex items-end gap-2">
                        <MultiSelect label="Produtos / Combustíveis" options={Object.values(FuelType).map(f => ({value: f, label: f}))} selected={filterFuel} onChange={setFilterFuel} placeholder="Todos os itens" />
                        <button onClick={() => {resetForms(); setShowForm(!showForm);}} className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-2 rounded-lg font-bold flex items-center gap-2 h-[42px] transition-colors"><Plus size={18} /> Novo</button>
                    </div>
                </div>
            </div>

            {showForm && !isReadOnly && (
                <div className="bg-white rounded-xl shadow-lg border-2 border-blue-100 p-6 animate-in slide-in-from-top-2 print:hidden">
                    <h3 className="font-bold text-lg mb-6 flex items-center gap-2 text-slate-800"><Droplet className="text-blue-500" /> {isEditing ? 'Editar' : 'Novo'} Registro de Abastecimento</h3>

                    <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-8 bg-slate-50 p-4 rounded-xl border border-slate-100">
                        <div className="md:col-span-4 flex items-center gap-2 mb-2">
                            <input type="checkbox" checked={isExternal} onChange={e => setIsExternal(e.target.checked)} id="ext" className="w-5 h-5 accent-blue-600 cursor-pointer" />
                            <label htmlFor="ext" className="text-sm font-bold text-slate-700 cursor-pointer">Equipamento Externo / Não Cadastrado</label>
                        </div>
                        <div>
                            <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Data</label>
                            <input type="date" value={refuelingHeader.date} onChange={e => setRefuelingHeader({...refuelingHeader, date: e.target.value})} className="w-full border border-slate-300 rounded-lg p-2.5" />
                        </div>
                        {isExternal ? (
                            <div className="md:col-span-2">
                                <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Identificação / Tipo</label>
                                <input type="text" placeholder="EX: GERADOR 01" value={externalData.identifier} onChange={e => setExternalData({...externalData, identifier: e.target.value.toUpperCase()})} className="w-full border border-slate-300 rounded-lg p-2.5" />
                            </div>
                        ) : (
                            <div className="md:col-span-2">
                                <SelectWithSearch label="Veículo da Frota" options={vehicles.map(v => ({value: v.id, label: `${v.plate} - ${v.driverName}`}))} value={refuelingHeader.vehicleId} onChange={val => setRefuelingHeader({...refuelingHeader, vehicleId: val})} />
                            </div>
                        )}
                        <div className="md:col-span-1">
                            <SelectWithSearch label="Posto Conveniado" options={stations.map(s => ({value: s.id, label: s.name}))} value={refuelingHeader.gasStationId} onChange={val => setRefuelingHeader({...refuelingHeader, gasStationId: val})} />
                        </div>
                    </div>

                    <div className="bg-blue-50 p-5 rounded-xl border-2 border-blue-200 mb-6 grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
                        <div className="md:col-span-1">
                            <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Produto / Insumo</label>
                            <select value={currentItem.fuelType || ''} onChange={e => setCurrentItem({...currentItem, fuelType: e.target.value as FuelType})} className="w-full border border-slate-300 rounded-lg p-2.5 bg-white h-[44px]">
                                <option value="">Selecione...</option>
                                <optgroup label="COMBUSTÍVEL">{FUEL_TYPES_LIST.map(f => <option key={f} value={f}>{f}</option>)}</optgroup>
                                <optgroup label="INSUMOS">{SUPPLY_TYPES_LIST.map(f => <option key={f} value={f}>{f}</option>)}</optgroup>
                            </select>
                        </div>
                        <div>
