                        <div className="flex justify-between py-0.5">
                            <span className="truncate mr-4">{selectedTicket.fuelType} x {selectedTicket.liters.toFixed(2)}{FUEL_TYPES_LIST.includes(selectedTicket.fuelType) ? 'L' : 'un'}</span>
