        <div className="p-4 bg-slate-950/50 border-t border-slate-800 backdrop-blur-sm">
          <div className="bg-slate-900/50 rounded-xl p-3 border border-slate-800 shadow-inner">
            <div className="flex items-center gap-3 mb-3">
