              </button>
              <button 
                  onClick={() => setActiveTab('FUEL')}
                  className={`flex-1 py-2.5 flex justify-center items-center gap-2 transition-all ${activeTab === 'FUEL' ? 'bg-orange-600 text-white shadow-inner' : 'text-slate-400 hover:bg-white/50'}`}
