                    className={`pb-3 px-2 text-sm font-bold transition-colors border-b-2 whitespace-nowrap ${activeTab === 'MANAGE_USERS' ? 'border-blue-600 text-blue-700' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
                >
