                                value={filterRequester}
                                onChange={(e) => setFilterRequester(e.target.value)}
                             >
                                 <option value="">Todos</option>
                                 {uniqueRequesters.map(req => (
                                     <option key={req} value={req}>{req}</option>
                                 ))}
                             </select>
                         </div>
                         <div className="flex items-end">
                             <button 
