    setIsEditing(false);
    setEditingRecordId(null);
    setRefuelingForm({
      date: getTodayLocal(),
      time: getCurrentTime(),
      vehicleId: '',
      gasStationId: '',
      foremanSnapshot: '',
      invoiceNumber: '',
      requisitionNumber: '',
      fuelType: '' as any,
      liters: 0,
      unitPrice: 0,
      totalCost: 0,
      municipality: ''
    });
    setIsExternal(false);
    setExternalData({ identifier: '', model: '', contract: '', municipality: '', description: '' });
  };

  const resetFilters = () => {
