                          // Fix: Use explicit Number conversion for comparison to avoid TypeScript broadening errors
                          className={`${inputClass} pr-8 ${
                              (Number(formData.maxSpeed) || 0) > currentSpeedLimit ? 'text-red-600 font-bold border-red-300 bg-red-50' : ''
                          }`}
                          />
                          <span className="absolute right-3 top-2.5 text-gray-400 text-xs font-medium">Km/h</span>
