                      </label>
                      <input
                          type="number"
                          name="speedingCount"
                          value={formData.speedingCount === undefined ? '' : formData.speedingCount}
                          onChange={handleChange}
                          min="0"
                          placeholder=""
                          // Fix: Use explicit Number conversion for comparison
                          disabled={(Number(formData.maxSpeed) || 0) <= currentSpeedLimit}
                          className={`${inputClass} ${(Number(formData.maxSpeed) || 0) <= currentSpeedLimit ? 'bg-slate-100 text-slate-400 cursor-not-allowed' : ''}`}
