                            <div className={`w-9 h-9 rounded-full flex-shrink-0 flex items-center justify-center font-black text-base shadow-sm border-2 ${
                                activeTab === 'FUEL' ? 'bg-orange-50 text-orange-600 border-orange-100' : 
