import React, { useState, useEffect } from 'react';
import { storageService } from '../services/storage';
import { DailyLog, RefuelingLog, Vehicle, ContractType } from '../types';
import { PrintHeader } from './PrintHeader';
import MultiSelect, { MultiSelectOption } from './MultiSelect';
import { BarChart3, Filter, Loader2, Printer, X, Search, Fuel, Gauge, TrendingUp, DollarSign, ArrowUpRight } from 'lucide-react';

interface ConsolidatedItem {
    plate: string;
    model: string;
    contract: string;
    foreman: string;
    kmTotal: number;
    hoursTotal: string;
    litersTotal: number;
    costTotal: number;
    averageKmPerL: number;
}

const ConsolidatedReports: React.FC = () => {
    const [loading, setLoading] = useState(true);
    const [data, setData] = useState<ConsolidatedItem[]>([]);
    const [filteredData, setFilteredData] = useState<ConsolidatedItem[]>([]);

    // Filtros
    const [dateRange, setDateRange] = useState({ 
        start: new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0], 
        end: new Date().toISOString().split('T')[0] 
    });
    const [filterContracts, setFilterContracts] = useState<string[]>([]);
    const [filterForeman, setFilterForeman] = useState<string[]>([]);
    const [uniqueForemen, setUniqueForemen] = useState<string[]>([]);

    useEffect(() => {
        loadConsolidatedData();
    }, [dateRange.start, dateRange.end]);

    const loadConsolidatedData = async () => {
        setLoading(true);
        try {
            const [logs, refuelings, vehicles] = await Promise.all([
                storageService.getLogs(),
                storageService.getRefuelings(),
                storageService.getVehicles()
            ]);

            setUniqueForemen(Array.from(new Set(vehicles.map(v => v.foreman).filter(f => f && f !== '-'))).sort());

            // Filtrar por período
            const periodLogs = logs.filter(l => l.date >= dateRange.start && l.date <= dateRange.end);
            const periodRefuelings = refuelings.filter(r => r.date >= dateRange.start && r.date <= dateRange.end);

            // Mapear veículos ativos e com histórico no período
            const plates = Array.from(new Set([
                ...vehicles.map(v => v.plate),
                ...periodLogs.map(l => l.historicalPlate || ''),
                ...periodRefuelings.map(r => r.plateSnapshot || '')
            ])).filter(p => p !== '');

            const consolidated: ConsolidatedItem[] = plates.map(plate => {
                const vehicle = vehicles.find(v => v.plate === plate);
                const vehicleLogs = periodLogs.filter(l => (l.historicalPlate || '') === plate || (vehicle && l.vehicleId === vehicle.id));
                const vehicleRefuelings = periodRefuelings.filter(r => (r.plateSnapshot || '') === plate || (vehicle && r.vehicleId === vehicle.id));

                const kmTotal = vehicleLogs.reduce((acc, log) => acc + (log.kmDriven || 0), 0);

                // Cálculo simplificado de horas de operação (considerando apenas registros válidos)
                let totalMin = 0;
                vehicleLogs.forEach(log => {
                    if (log.startTime && log.endTime) {
                        const [sH, sM] = log.startTime.split(':').map(Number);
                        const [eH, eM] = log.endTime.split(':').map(Number);
                        totalMin += (eH * 60 + eM) - (sH * 60 + sM);
                    }
                });
                const hoursTotal = `${Math.floor(totalMin / 60)}h ${totalMin % 60}m`;

                const litersTotal = vehicleRefuelings.reduce((acc, r) => acc + (r.liters || 0), 0);
                const costTotal = vehicleRefuelings.reduce((acc, r) => acc + (r.totalCost || 0), 0);
                const averageKmPerL = litersTotal > 0 ? kmTotal / litersTotal : 0;

                return {
                    plate,
                    model: vehicle?.model || vehicleLogs[0]?.historicalModel || '-',
                    contract: vehicle?.contract || vehicleLogs[0]?.historicalContract || '-',
                    foreman: vehicle?.foreman || '-',
                    kmTotal,
                    hoursTotal,
                    litersTotal,
                    costTotal,
                    averageKmPerL
                };
            });

            setData(consolidated);
            applyLocalFilters(consolidated);
        } catch (error) {
            console.error("Erro ao consolidar relatórios:", error);
        } finally {
            setLoading(false);
        }
    };

    const applyLocalFilters = (sourceData = data) => {
        const filtered = sourceData.filter(item => {
            const matchesContract = filterContracts.length === 0 || filterContracts.includes(item.contract);
            const matchesForeman = filterForeman.length === 0 || filterForeman.includes(item.foreman);
            return matchesContract && matchesForeman;
        });
        setFilteredData(filtered);
    };

    useEffect(() => {
        applyLocalFilters();
    }, [filterContracts, filterForeman, data]);

    const handlePrint = () => window.print();

    const totals = filteredData.reduce((acc, curr) => ({
        km: acc.km + curr.kmTotal,
        liters: acc.liters + curr.litersTotal,
        cost: acc.cost + curr.costTotal
    }), { km: 0, liters: 0, cost: 0 });

    const contractOptions: MultiSelectOption[] = Object.values(ContractType).map(c => ({ value: c, label: c }));
    const foremanOptions: MultiSelectOption[] = uniqueForemen.map(f => ({ value: f, label: f }));

    const formatCurrency = (val: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

    return (
        <div className="space-y-6">
            <PrintHeader 
                title="Relatório Consolidado de Frota"
                subtitle="Performance, Rodagem e Consumo"
                details={
