                        <span>Veículos Listados: {filteredData.length}</span>
                        <span>Custo Total: {formatCurrency(totals.cost)}</span>
                    </>
                }
            />

            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 print:hidden">
                <div>
                    <h1 className="text-3xl font-bold text-slate-900 flex items-center gap-3">
                        <BarChart3 className="text-rose-600" size={32} />
                        Relatórios Analíticos
                    </h1>
                    <p className="text-slate-500">Consolidação de rodagem e combustível por veículo.</p>
                </div>
                <button onClick={handlePrint} className="bg-white border border-slate-300 text-slate-700 px-4 py-2 rounded-lg font-bold flex items-center gap-2 hover:bg-slate-50 transition-colors shadow-sm">
                    <Printer size={20} /> Imprimir Consolidado
                </button>
            </div>

            {/* Filtros Analíticos */}
            <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-5 print:hidden">
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                    <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Início</label>
                        <input type="date" value={dateRange.start} onChange={e => setDateRange({ ...dateRange, start: e.target.value })} className="w-full rounded-lg border border-slate-300 p-2 text-sm focus:ring-2 focus:ring-rose-100 outline-none" />
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Fim</label>
                        <input type="date" value={dateRange.end} onChange={e => setDateRange({ ...dateRange, end: e.target.value })} className="w-full rounded-lg border border-slate-300 p-2 text-sm focus:ring-2 focus:ring-rose-100 outline-none" />
                    </div>
                    <div>
                        <MultiSelect label="Contratos" options={contractOptions} selected={filterContracts} onChange={setFilterContracts} placeholder="Todos" />
                    </div>
                    <div>
                        <MultiSelect label="Equipes" options={foremanOptions} selected={filterForeman} onChange={setFilterForeman} placeholder="Todas" />
                    </div>
                </div>
            </div>

            {/* Cards de Resumo */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4 print:hidden">
                <div className="bg-gradient-to-br from-blue-600 to-blue-700 p-5 rounded-2xl text-white shadow-lg">
                    <div className="flex justify-between items-start mb-2">
                        <div className="p-2 bg-white/20 rounded-lg"><Gauge size={24} /></div>
                        <ArrowUpRight size={20} className="opacity-50" />
                    </div>
                    <p className="text-blue-100 text-xs font-bold uppercase tracking-wider">Rodagem Total</p>
                    <p className="text-3xl font-black">{totals.km.toLocaleString()} <span className="text-lg font-normal">km</span></p>
                </div>
                <div className="bg-gradient-to-br from-orange-500 to-orange-600 p-5 rounded-2xl text-white shadow-lg">
                    <div className="flex justify-between items-start mb-2">
                        <div className="p-2 bg-white/20 rounded-lg"><Fuel size={24} /></div>
                        <TrendingUp size={20} className="opacity-50" />
                    </div>
                    <p className="text-orange-100 text-xs font-bold uppercase tracking-wider">Combustível Total</p>
                    <p className="text-3xl font-black">{totals.liters.toFixed(1)} <span className="text-lg font-normal">L</span></p>
                </div>
                <div className="bg-gradient-to-br from-emerald-600 to-emerald-700 p-5 rounded-2xl text-white shadow-lg">
                    <div className="flex justify-between items-start mb-2">
                        <div className="p-2 bg-white/20 rounded-lg"><DollarSign size={24} /></div>
                        <TrendingUp size={20} className="opacity-50" />
                    </div>
                    <p className="text-emerald-100 text-xs font-bold uppercase tracking-wider">Custo de Operação</p>
                    <p className="text-3xl font-black">{formatCurrency(totals.cost)}</p>
                </div>
            </div>

            {/* Tabela Consolidada */}
            <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden print:border-none print:shadow-none">
                <div className="p-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center print:hidden">
                    <h3 className="font-bold text-slate-700 flex items-center gap-2">
                        <Search size={18} className="text-slate-400" /> Tabela de Performance por Veículo
                    </h3>
                </div>
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left">
                        <thead className="bg-slate-100 text-slate-600 font-bold uppercase text-[10px] print:bg-slate-200 print:text-black">
                            <tr>
                                <th className="px-6 py-4">Placa / Modelo</th>
                                <th className="px-6 py-4">Contrato</th>
                                <th className="px-6 py-4 text-right">KM Rodados</th>
                                <th className="px-6 py-4 text-right">Horas Oper.</th>
                                <th className="px-6 py-4 text-right bg-orange-50/50 print:bg-transparent">Litros (L)</th>
                                <th className="px-6 py-4 text-right bg-emerald-50/50 print:bg-transparent">Custo (R$)</th>
                                <th className="px-6 py-4 text-center">Média (KM/L)</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {loading ? (
                                <tr><td colSpan={7} className="py-20 text-center"><Loader2 className="animate-spin mx-auto text-rose-600" size={32} /></td></tr>
                            ) : filteredData.length === 0 ? (
                                <tr><td colSpan={7} className="py-20 text-center text-slate-400 italic">Nenhum dado encontrado para os filtros aplicados.</td></tr>
                            ) : (
                                filteredData.map(item => (
                                    <tr key={item.plate} className="hover:bg-slate-50 transition-colors">
                                        <td className="px-6 py-4">
                                            <div className="font-bold text-slate-900">{item.plate}</div>
                                            <div className="text-[10px] text-slate-400 uppercase">{item.model}</div>
