import React, { useState, useEffect, useMemo } from 'react';
import { storageService } from '../services/storage';
import { DailyLog, RefuelingLog, Vehicle, ContractType } from '../types';
import { PrintHeader } from './PrintHeader';
import MultiSelect, { MultiSelectOption } from './MultiSelect';
import { BarChart3, Filter, Loader2, Printer, X, Search, Fuel, Gauge, TrendingUp, DollarSign, ArrowUpRight, ArrowUpDown, ChevronUp, ChevronDown } from 'lucide-react';

interface ConsolidatedItem {
    plate: string;
    model: string;
    contract: string;
    foreman: string;
    kmTotal: number;
    minutesTotal: number; // Para ordenação numérica precisa
    hoursTotal: string;
    litersTotal: number;
    costTotal: number;
    averageKmPerL: number;
}

type SortKey = 'plate' | 'foreman' | 'kmTotal' | 'minutesTotal' | 'litersTotal' | 'costTotal' | 'averageKmPerL';
type SortOrder = 'asc' | 'desc';

const ConsolidatedReports: React.FC = () => {
    const [loading, setLoading] = useState(true);
    const [data, setData] = useState<ConsolidatedItem[]>([]);
    const [filterContracts, setFilterContracts] = useState<string[]>([]);
    const [filterForeman, setFilterForeman] = useState<string[]>([]);
    const [uniqueForemen, setUniqueForemen] = useState<string[]>([]);

    // Estado de Ordenação
    const [sortConfig, setSortConfig] = useState<{ key: SortKey; order: SortOrder }>({ 
        key: 'kmTotal', 
        order: 'desc' 
    });

    // Filtros de Data
    const [dateRange, setDateRange] = useState({ 
        start: new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0], 
        end: new Date().toISOString().split('T')[0] 
    });

    useEffect(() => {
        loadConsolidatedData();
    }, [dateRange.start, dateRange.end]);

    const loadConsolidatedData = async () => {
        setLoading(true);
        try {
            const [logs, refuelings, vehicles] = await Promise.all([
                storageService.getLogs(),
                storageService.getRefuelings(),
                storageService.getVehicles()
            ]);

            setUniqueForemen(Array.from(new Set(vehicles.map(v => v.foreman).filter(f => f && f !== '-'))).sort());

            const periodLogs = logs.filter(l => l.date >= dateRange.start && l.date <= dateRange.end);
            const periodRefuelings = refuelings.filter(r => r.date >= dateRange.start && r.date <= dateRange.end);

            const plates = Array.from(new Set([
                ...vehicles.map(v => v.plate),
                ...periodLogs.map(l => l.historicalPlate || ''),
                ...periodRefuelings.map(r => r.plateSnapshot || '')
            ])).filter(p => p !== '');

            const consolidated: ConsolidatedItem[] = plates.map(plate => {
                const vehicle = vehicles.find(v => v.plate === plate);
                const vehicleLogs = periodLogs.filter(l => (l.historicalPlate || '') === plate || (vehicle && l.vehicleId === vehicle.id));
                const vehicleRefuelings = periodRefuelings.filter(r => (r.plateSnapshot || '') === plate || (vehicle && r.vehicleId === vehicle.id));

                const kmTotal = vehicleLogs.reduce((acc, log) => acc + (log.kmDriven || 0), 0);

                let totalMin = 0;
                vehicleLogs.forEach(log => {
                    if (log.startTime && log.endTime) {
                        const [sH, sM] = log.startTime.split(':').map(Number);
                        const [eH, eM] = log.endTime.split(':').map(Number);
                        totalMin += (eH * 60 + eM) - (sH * 60 + sM);
                    }
                });

                const hoursTotal = `${Math.floor(totalMin / 60)}h ${totalMin % 60}m`;
                const litersTotal = vehicleRefuelings.reduce((acc, r) => acc + (r.liters || 0), 0);
                const costTotal = vehicleRefuelings.reduce((acc, r) => acc + (r.totalCost || 0), 0);
                const averageKmPerL = litersTotal > 0 ? kmTotal / litersTotal : 0;

                return {
                    plate,
                    model: vehicle?.model || vehicleLogs[0]?.historicalModel || '-',
                    contract: vehicle?.contract || vehicleLogs[0]?.historicalContract || '-',
                    foreman: vehicle?.foreman || vehicleLogs[0]?.historicalDriver || '-',
                    kmTotal,
                    minutesTotal: totalMin,
                    hoursTotal,
                    litersTotal,
                    costTotal,
                    averageKmPerL
                };
            });

            setData(consolidated);
        } catch (error) {
            console.error("Erro ao consolidar relatórios:", error);
        } finally {
            setLoading(false);
        }
    };

    // Lógica de Filtro e Ordenação combinada
    const processedData = useMemo(() => {
        let filtered = data.filter(item => {
            const matchesContract = filterContracts.length === 0 || filterContracts.includes(item.contract);
            const matchesForeman = filterForeman.length === 0 || filterForeman.includes(item.foreman);
            return matchesContract && matchesForeman;
        });

        return filtered.sort((a, b) => {
            const aVal = a[sortConfig.key];
            const bVal = b[sortConfig.key];

            if (aVal < bVal) return sortConfig.order === 'asc' ? -1 : 1;
            if (aVal > bVal) return sortConfig.order === 'asc' ? 1 : -1;
            return 0;
        });
    }, [data, filterContracts, filterForeman, sortConfig]);

    const handleSort = (key: SortKey) => {
        setSortConfig(prev => ({
            key,
            order: prev.key === key && prev.order === 'desc' ? 'asc' : 'desc'
        }));
    };

    const totals = processedData.reduce((acc, curr) => ({
        km: acc.km + curr.kmTotal,
        liters: acc.liters + curr.litersTotal,
        cost: acc.cost + curr.costTotal
    }), { km: 0, liters: 0, cost: 0 });

    const contractOptions: MultiSelectOption[] = Object.values(ContractType).map(c => ({ value: c, label: c }));
    const foremanOptions: MultiSelectOption[] = uniqueForemen.map(f => ({ value: f, label: f }));

    const formatCurrency = (val: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

    const SortableHeader: React.FC<{ label: string; sortKey: SortKey; align?: 'left' | 'right' | 'center' }> = ({ label, sortKey, align = 'left' }) => {
        const isActive = sortConfig.key === sortKey;
        return (
            <th 
                className={`px-6 py-4 cursor-pointer hover:bg-slate-200 transition-colors group ${align === 'right' ? 'text-right' : align === 'center' ? 'text-center' : 'text-left'}`}
                onClick={() => handleSort(sortKey)}
            >
                <div className={`flex items-center gap-1 ${align === 'right' ? 'justify-end' : align === 'center' ? 'justify-center' : 'justify-start'}`}>
                    <span>{label}</span>
                    {isActive ? (
                        sortConfig.order === 'desc' ? <ChevronDown size={14} className="text-rose-600" /> : <ChevronUp size={14} className="text-rose-600" />
                    ) : (
                        <ArrowUpDown size={12} className="text-slate-300 opacity-0 group-hover:opacity-100 transition-opacity" />
                    )}
                </div>
            </th>
        );
    };

    return (
        <div className="space-y-6">
            <PrintHeader 
                title="Relatório Consolidado de Frota"
                subtitle="Performance, Rodagem e Consumo"
                details={
                    <>
                        <span>Período: {dateRange.start} até {dateRange.end}</span>
                        <span>Veículos Listados: {processedData.length}</span>
                        <span>Custo Total: {formatCurrency(totals.cost)}</span>
                    </>
                }
            />

            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 print:hidden">
                <div>
                    <h1 className="text-3xl font-bold text-slate-900 flex items-center gap-3">
                        <BarChart3 className="text-rose-600" size={32} />
                        Relatórios Analíticos
                    </h1>
                    <p className="text-slate-500">Consolidação de rodagem e combustível por veículo.</p>
                </div>
                <div className="flex items-center gap-2">
                    <button onClick={loadConsolidatedData} className="p-2 text-slate-500 hover:bg-slate-100 rounded-lg transition-colors" title="Atualizar Dados">
                         <Loader2 className={`${loading ? 'animate-spin' : ''}`} size={20} />
                    </button>
                    <button onClick={() => window.print()} className="bg-white border border-slate-300 text-slate-700 px-4 py-2 rounded-lg font-bold flex items-center gap-2 hover:bg-slate-50 transition-colors shadow-sm">
                        <Printer size={20} /> Imprimir Consolidado
                    </button>
                </div>
            </div>

            {/* Filtros Analíticos */}
            <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-5 print:hidden">
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                    <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Início</label>
                        <input type="date" value={dateRange.start} onChange={e => setDateRange({ ...dateRange, start: e.target.value })} className="w-full rounded-lg border border-slate-300 p-2 text-sm focus:ring-2 focus:ring-rose-100 outline-none" />
