                    <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Fim</label>
                        <input type="date" value={dateRange.end} onChange={e => setDateRange({ ...dateRange, end: e.target.value })} className="w-full rounded-lg border border-slate-300 p-2 text-sm focus:ring-2 focus:ring-rose-100 outline-none" />
