                                                    <td className="px-6 py-4 text-right font-mono font-bold text-emerald-700">{formatCurrency(item.cost)}</td>
                                                    <td className="px-6 py-4 text-right text-slate-500 font-mono text-xs">
                                                        {formatCurrency(item.cost / item.count)}
