                                     <td className="px-6 py-4 text-right font-mono">{formatCurrency(stationDetailData.records.reduce((acc, r) => acc + r.totalCost, 0))}</td>
                                     <td className="px-6 py-4"></td>
                                 </tr>
                            </tfoot>
                        </table>
                    </div>
                </div>
            </div>
        );
    }

    return (
