import React, { useState, useEffect, useRef } from 'react';
import { DailyLogReport, Vehicle, ContractType, VehicleType, UserRole, DailyLog } from '../types';
import { storageService } from '../services/storage';
import { calculateWorkHours } from '../utils/timeUtils';
import PasswordModal from './PasswordModal';
import MultiSelect, { MultiSelectOption } from './MultiSelect';
import { useAuth } from '../contexts/AuthContext';
import { Filter, FileText, Trash2, Edit3, Calendar, X, Save, Clock, AlertTriangle, Search, User, MapPin, Key, Ban, Settings, HardHat, Printer, Fuel, Droplet, MessageSquareText, Loader2, WifiOff, ChevronDown, ChevronUp, ChevronLeft, ChevronRight, Gauge, RefreshCw } from 'lucide-react';
import { PrintHeader } from './PrintHeader';
import SelectWithSearch from './SelectWithSearch';

const Reports: React.FC = () => {
  const { user } = useAuth();
  const isReadOnly = user?.role === UserRole.RH || user?.role === UserRole.GERENCIA;

  const [loading, setLoading] = useState(true);
  const [errorState, setErrorState] = useState<string | null>(null);
  const [logs, setLogs] = useState<DailyLogReport[]>([]);
  const [filteredLogs, setFilteredLogs] = useState<DailyLogReport[]>([]);
  const [vehicles, setVehicles] = useState<Vehicle[]>([]);

  const [uniqueDrivers, setUniqueDrivers] = useState<string[]>([]);
  const [uniqueMunicipalities, setUniqueMunicipalities] = useState<string[]>([]);
  const [uniqueForemen, setUniqueForemen] = useState<string[]>([]);

  const [dateRange, setDateRange] = useState({ start: '', end: '' });
  const [filterForeman, setFilterForeman] = useState<string[]>([]); 
  const [filterContract, setFilterContract] = useState<string[]>([]);
  const [filterVehicleId, setFilterVehicleId] = useState<string[]>([]);
  const [filterDriver, setFilterDriver] = useState<string[]>([]);
  const [filterMunicipality, setFilterMunicipality] = useState<string[]>([]);

  const [showFilters, setShowFilters] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [logToDelete, setLogToDelete] = useState<string | null>(null);
  const [showEditModal, setShowEditModal] = useState(false);
  const [editingLog, setEditingLog] = useState<Partial<DailyLogReport> | null>(null);
  const [obsModalData, setObsModalData] = useState<{content: string, date: string, plate: string} | null>(null);

  const [itemsPerPage, setItemsPerPage] = useState(25);
  const [currentPage, setCurrentPage] = useState(1);

  const startDateRef = useRef<HTMLInputElement>(null);
  const endDateRef = useRef<HTMLInputElement>(null);

  useEffect(() => { loadData(); }, []);

  useEffect(() => {
    setCurrentPage(1);
  }, [dateRange, filterForeman, filterContract, filterVehicleId, filterDriver, filterMunicipality, itemsPerPage]);

  const handlePrint = () => { window.print(); };

  const loadData = async () => {
    setLoading(true);
    setErrorState(null);
    try {
        const [rawLogs, vehiclesData, refuelingsData] = await Promise.all([
            storageService.getLogs(),
            storageService.getVehicles(),
            storageService.getRefuelings()
        ]);
        setVehicles(vehiclesData);
        const processed: DailyLogReport[] = rawLogs.map(log => {
            let vehicle = vehiclesData.find(v => v.id === log.vehicleId);
            if (!vehicle) {
                vehicle = {
                    id: log.vehicleId,
                    plate: log.historicalPlate || 'VEÍCULO EXCLUÍDO',
                    model: log.historicalModel || '-',
                    year: '-',
                    contract: (log.historicalContract as ContractType) || ContractType.ADM_MANAUS,
                    driverName: log.historicalDriver || 'N/A',
                    municipality: log.historicalMunicipality || 'N/A',
                    foreman: '-', 
                    type: VehicleType.PICK_UP, 
                    status: 'INATIVO'
                };
            }
            const relevantRefuelings = refuelingsData
                .filter(r => r.vehicleId === log.vehicleId && r.date <= log.date)
                .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

            let lastRefuelingInfo = undefined;
            if (relevantRefuelings.length > 0) {
                const lastRef = relevantRefuelings[0];
                const kmSince = rawLogs
                    .filter(l => l.vehicleId === log.vehicleId && l.date >= lastRef.date && l.date <= log.date)
                    .reduce((sum, l) => {
                        let dailyContribution = l.kmDriven || 0;
                        if (l.date === lastRef.date && l.kmBeforeRefueling !== undefined) {
                            dailyContribution = Math.max(0, dailyContribution - l.kmBeforeRefueling);
                        }
                        return sum + dailyContribution;
                    }, 0);
                lastRefuelingInfo = { date: lastRef.date, liters: lastRef.liters, kmSince: kmSince };
            }
            return {
                ...log,
                vehicle: vehicle,
                calculatedHours: calculateWorkHours(log.startTime, log.endTime, log.lunchStart, log.lunchEnd, log.extraTimeStart, log.extraTimeEnd),
                lastRefuelingInfo
            };
        });
        processed.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
        setLogs(processed);
        setFilteredLogs(processed);

        const uDrivers = new Set<string>();
        const uMunicipalities = new Set<string>();
        const uForemen = new Set<string>();
        processed.forEach(log => {
            const d = log.historicalDriver || log.vehicle.driverName;
            if (d) uDrivers.add(d);
            const m = log.historicalMunicipality || log.vehicle.municipality;
            if (m) uMunicipalities.add(m);
            if (log.vehicle.foreman) uForemen.add(log.vehicle.foreman);
        });
        setUniqueDrivers(Array.from(uDrivers).sort());
        setUniqueMunicipalities(Array.from(uMunicipalities).sort());
        setUniqueForemen(Array.from(uForemen).sort());
    } catch(e: any) {
        setErrorState(e.message || "Erro ao carregar dados.");
    } finally {
        setLoading(false);
    }
  };

  const handleFilter = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    const start = dateRange.start ? new Date(dateRange.start).getTime() : null;
    const end = dateRange.end ? new Date(dateRange.end).getTime() : null;
    const filtered = logs.filter(log => {
      const logDate = new Date(log.date).getTime();
      const matchesDate = (!start || logDate >= start) && (!end || logDate <= end);
      const logContract = log.historicalContract || log.vehicle.contract;
      const matchesContract = filterContract.length === 0 || filterContract.includes(logContract);
      const matchesVehicleId = filterVehicleId.length === 0 || filterVehicleId.includes(log.vehicle.id);
      const logForeman = log.vehicle.foreman || '';
      const matchesForeman = filterForeman.length === 0 || filterForeman.includes(logForeman);
      const logDriver = log.historicalDriver || log.vehicle.driverName || '';
      const matchesDriver = filterDriver.length === 0 || filterDriver.includes(logDriver);
      const logCity = log.historicalMunicipality || log.vehicle.municipality || '';
      const matchesMunicipality = filterMunicipality.length === 0 || filterMunicipality.includes(logCity);
      return matchesDate && matchesContract && matchesVehicleId && matchesForeman && matchesDriver && matchesMunicipality;
    });
    setFilteredLogs(filtered);
  };

  const calculateSummary = () => {
    let totalMinutes = 0;
    let totalKm = 0;
    let daysNoSignal = 0;
    let daysStopped = 0;
    filteredLogs.forEach(log => {
       if (log.nonOperatingReason) {
          if (log.nonOperatingReason === 'SEM SINAL') daysNoSignal++;
          if (['OFICINA', 'EM MANUTENÇÃO', 'GARAGEM'].includes(log.nonOperatingReason)) daysStopped++;
       } else {
          const [h, m] = log.calculatedHours.split(':').map(Number);
          totalMinutes += (h * 60) + m;
          totalKm += log.kmDriven || 0;
       }
    });
    const hours = Math.floor(totalMinutes / 60);
    const minutes = totalMinutes % 60;
    return { formattedTime: `${hours}h ${minutes}m`, totalKm, daysNoSignal, daysStopped };
  };

  const summary = calculateSummary();
  const paginatedLogs = filteredLogs.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage);

  const formatDateDisplay = (dateString: string) => {
    if (!dateString) return '-';
    const [year, month, day] = dateString.split('-');
    return `${day}/${month}/${year.slice(-2)}`;
  };

  const getContractColor = (contract: string) => {
    switch (contract) {
      case ContractType.MANUTENCAO: return 'bg-blue-100 text-blue-800 border-blue-200';
      case ContractType.LINHA_VIVA: return 'bg-red-100 text-red-800 border-red-200';
      case ContractType.PLPT: return 'bg-green-100 text-green-800 border-green-200';
      default: return 'bg-slate-100 text-slate-800 border-slate-200';
    }
  };

  return (
    <div className="space-y-6 print:space-y-4">

       <PrintHeader 
        title="Relatório Detalhado de Frota"
        subtitle="Controle de Diário de Bordo e Rodagem"
        details={
            <>
                <div className="flex flex-col"><span className="font-black text-slate-400">PERÍODO</span><span className="font-bold">{dateRange.start ? formatDateDisplay(dateRange.start) : 'INÍCIO'} - {dateRange.end ? formatDateDisplay(dateRange.end) : 'HOJE'}</span></div>
                <div className="flex flex-col"><span className="font-black text-slate-400">REGISTROS</span><span className="font-bold text-center">{filteredLogs.length}</span></div>
                <div className="flex flex-col"><span className="font-black text-slate-400">QUILOMETRAGEM</span><span className="font-bold text-center">{summary.totalKm} KM</span></div>
                <div className="flex flex-col"><span className="font-black text-slate-400">TEMPO TOTAL</span><span className="font-bold text-center">{summary.formattedTime}</span></div>
            </>
        }
      />

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 print:hidden">
        <div><h1 className="text-3xl font-bold text-slate-900">Registros</h1><p className="text-slate-500">Histórico de atividades da frota.</p></div>
        <button onClick={handlePrint} className="bg-white border border-slate-300 text-slate-700 px-4 py-2 rounded-lg font-bold flex items-center gap-2 hover:bg-slate-50 shadow-sm transition-all"><Printer size={20} /> Imprimir Relatório</button>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden print:border-none print:shadow-none relative z-0">
         <div className="overflow-x-auto print:overflow-visible">
           <table className="w-full text-base text-left whitespace-nowrap">
             <thead className="bg-slate-100 text-slate-600 font-bold uppercase tracking-wider text-sm print:bg-slate-200 print:text-slate-900">
               <tr>
                 <th className="px-4 py-3 border-b">Data</th>
                 <th className="px-4 py-3 border-b min-w-[150px]">Veículo / Condutor</th>
                 <th className="px-4 py-3 border-b">Horários</th>
                 <th className="px-4 py-3 border-b">Ligado</th>
                 <th className="px-4 py-3 border-b">KM</th>
                 <th className="px-4 py-3 border-b">Vel. Máx</th>
                 <th className="px-4 py-3 border-b min-w-[100px]">Abastec.</th>
                 {!isReadOnly && <th className="px-4 py-3 border-b no-print">Ações</th>}
               </tr>
             </thead>
             <tbody className="divide-y divide-slate-100">
               {paginatedLogs.length === 0 ? (
                 <tr><td colSpan={8} className="px-6 py-12 text-center text-slate-400">Nenhum registro encontrado.</td></tr>
               ) : (
                 paginatedLogs.map(log => {
                   const displayContract = log.historicalContract || log.vehicle.contract;
                   return (
                   <tr key={log.id} className="hover:bg-slate-50 transition-colors print:hover:bg-transparent">
                     <td className="px-4 py-3 font-bold text-slate-900 print:font-black">{formatDateDisplay(log.date)}</td>
                     <td className="px-4 py-3">
                        <div className="flex flex-col gap-0.5">
                           <div className="flex items-center gap-2 print:justify-center">
                              <span className="font-mono font-black text-slate-800 print:text-black">{log.vehicle.plate}</span>
                              <span className={`px-1.5 py-0.5 rounded text-[10px] font-bold border uppercase ${getContractColor(displayContract)} print:border-none print:p-0 print:text-black print:text-[8px]`}>{displayContract.substring(0,8)}</span>
                           </div>
                           <div className="text-slate-500 text-xs font-medium uppercase truncate print:text-black">{log.historicalDriver || log.vehicle.driverName}</div>
                        </div>
                     </td>

                     {log.nonOperatingReason ? (
                        <td colSpan={4} className="px-4 py-3 text-center print:bg-transparent">
                           <span className="font-black text-xs text-red-600 border border-red-200 px-2 py-1 rounded-md uppercase print:text-black print:border-black">{log.nonOperatingReason}</span>
                        </td>
                     ) : (
                       <>
                          <td className="px-4 py-3 font-medium text-slate-700 print:text-black">{log.startTime} - {log.endTime}</td>
                          <td className="px-4 py-3"><span className="font-black text-blue-700 text-sm print:text-black">{log.calculatedHours}h</span></td>
                          <td className="px-4 py-3 font-mono font-bold text-slate-700 print:text-black">{log.kmDriven}</td>
                          <td className="px-4 py-3"><span className={`${log.maxSpeed > 90 ? "text-red-600 font-black" : "text-slate-600"} font-mono print:text-black`}>{log.maxSpeed}</span></td>
                       </>
                     )}

                     <td className="px-4 py-3">
                        {log.lastRefuelingInfo ? (
                            <div className="flex flex-col text-[10px] leading-tight print:text-black">
                                <span className="font-black">{log.lastRefuelingInfo.liters.toFixed(1)} L</span>
                                <span className="text-slate-400 font-bold">{log.lastRefuelingInfo.date.split('-').slice(1).reverse().join('/')}</span>
                            </div>
                        ) : <span className="text-slate-300">-</span>}
                     </td>

                     {!isReadOnly && (
                      <td className="px-4 py-3 text-center no-print">
                        <div className="flex justify-center gap-1 opacity-70 hover:opacity-100"><Edit3 size={16} className="text-blue-600 cursor-pointer" /></div>
                      </td>
                     )}
                   </tr>
                 )})
               )}
             </tbody>
             <tfoot className="print:table-footer-group">
                <tr className="bg-slate-900 text-white font-black">
                    <td colSpan={2} className="px-4 py-3 text-right uppercase tracking-widest text-[11px] print:text-black">Totais Conferidos:</td>
                    <td className="px-4 py-3 text-center print:text-black">{summary.formattedTime}</td>
                    <td className="px-4 py-3 text-center print:text-black">LIG: {filteredLogs.length - summary.daysStopped - summary.daysNoSignal}</td>
                    <td className="px-4 py-3 text-center print:text-black">{summary.totalKm} KM</td>
                    <td colSpan={3} className="px-4 py-3 text-center print:text-black italic text-[9px] opacity-40">CONTROLE DE FROTA - PARIS ENGENHARIA</td>
                </tr>
             </tfoot>
           </table>
         </div>
      </div>
    </div>
  );
};

