import React, { useState, useEffect, useMemo } from 'react';
import { storageService } from '../services/storage';
import { DailyLog, RefuelingLog, Vehicle, ContractType, GasStation, FUEL_TYPES_LIST } from '../types';
import { PrintHeader } from './PrintHeader';
import MultiSelect, { MultiSelectOption } from './MultiSelect';
import { BarChart3, Filter, Loader2, Printer, X, Search, Fuel, Gauge, TrendingUp, DollarSign, ArrowUpRight, ArrowUpDown, ChevronUp, ChevronDown, Building2, Truck, ClipboardList, ArrowLeft, Eye, Receipt, Calendar } from 'lucide-react';

const ConsolidatedReports: React.FC = () => {
    const [loading, setLoading] = useState(true);
    const [activeTab, setActiveTab] = useState<'PERFORMANCE' | 'FUEL_ANALYSIS'>('PERFORMANCE');
    const [logs, setLogs] = useState<DailyLog[]>([]);
    const [refuelings, setRefuelings] = useState<RefuelingLog[]>([]);
    const [vehicles, setVehicles] = useState<Vehicle[]>([]);
    const [stations, setStations] = useState<GasStation[]>([]);
    const [dateRange, setDateRange] = useState({ 
        start: new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0], 
        end: new Date().toISOString().split('T')[0] 
    });

    useEffect(() => { loadAllData(); }, [dateRange.start, dateRange.end]);

    const loadAllData = async () => {
        setLoading(true);
        try {
            const [lData, rData, vData, sData] = await Promise.all([
                storageService.getLogs(),
                storageService.getRefuelings(),
                storageService.getVehicles(),
                storageService.getGasStations()
            ]);
            setLogs(lData);
            setRefuelings(rData);
            setVehicles(vData);
            setStations(sData);
        } catch (error) { console.error(error); } finally { setLoading(false); }
    };

    const performanceData = useMemo(() => {
        const periodLogs = logs.filter(l => l.date >= dateRange.start && l.date <= dateRange.end);
        const periodRefuelings = refuelings.filter(r => r.date >= dateRange.start && r.date <= dateRange.end);
        const plates = Array.from(new Set(vehicles.map(v => v.plate)));
        return plates.map(plate => {
            const vehicle = vehicles.find(v => v.plate === plate);
            const vLogs = periodLogs.filter(l => l.vehicleId === vehicle?.id);
            const vRefuelings = periodRefuelings.filter(r => r.vehicleId === vehicle?.id);
            const kmTotal = vLogs.reduce((acc, log) => acc + (log.kmDriven || 0), 0);
            const litersTotal = vRefuelings.reduce((acc, r) => acc + (r.liters || 0), 0);
            const costTotal = vRefuelings.reduce((acc, r) => acc + (r.totalCost || 0), 0);
            return { plate, model: vehicle?.model || '-', contract: vehicle?.contract || '-', kmTotal, litersTotal, costTotal, avg: litersTotal > 0 ? (kmTotal / litersTotal).toFixed(2) : '0' };
        }).filter(item => item.kmTotal > 0 || item.litersTotal > 0);
    }, [logs, refuelings, vehicles, dateRange]);

    const totals = useMemo(() => {
        return performanceData.reduce((acc, curr) => ({
            km: acc.km + curr.kmTotal, liters: acc.liters + curr.litersTotal, cost: acc.cost + curr.costTotal
        }), { km: 0, liters: 0, cost: 0 });
    }, [performanceData]);

    const formatCurrency = (val: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

    return (
        <div className="space-y-6">
            <PrintHeader 
                title="Consolidação de Performance Operacional"
                subtitle="Análise Comparativa de Rodagem e Consumo"
                details={
                    <>
                        <div className="flex flex-col"><span className="font-black text-slate-400">PERÍODO ANALISADO</span><span className="font-bold">{dateRange.start.split('-').reverse().join('/')} ATÉ {dateRange.end.split('-').reverse().join('/')}</span></div>
                        <div className="flex flex-col"><span className="font-black text-slate-400">QUILOMETRAGEM</span><span className="font-bold text-center">{totals.km.toLocaleString()} KM</span></div>
                        <div className="flex flex-col"><span className="font-black text-slate-400">VOLUME TOTAL</span><span className="font-bold text-center">{totals.liters.toFixed(1)} L</span></div>
                        <div className="flex flex-col"><span className="font-black text-slate-400">VALOR TOTAL</span><span className="font-bold text-center">{formatCurrency(totals.cost)}</span></div>
                    </>
                }
            />

            <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden print:border-none print:shadow-none">
                <table className="w-full text-sm text-left">
                    <thead className="bg-slate-100 text-slate-600 font-bold uppercase text-[10px] print:bg-slate-200 print:text-black">
                        <tr>
                            <th className="px-6 py-4">Veículo</th>
                            <th className="px-6 py-4">Contrato</th>
                            <th className="px-6 py-4 text-center">Rodagem (KM)</th>
                            <th className="px-6 py-4 text-center">Consumo (L)</th>
                            <th className="px-6 py-4 text-center">Custo (R$)</th>
                            <th className="px-6 py-4 text-center">Média (KM/L)</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {performanceData.map(item => (
                            <tr key={item.plate} className="hover:bg-slate-50 transition-colors print:hover:bg-transparent">
                                <td className="px-6 py-4"><div className="font-black text-slate-900">{item.plate}</div><div className="text-[10px] text-slate-400">{item.model}</div></td>
                                <td className="px-6 py-4 text-xs font-bold uppercase text-slate-500 print:text-black">{item.contract}</td>
                                <td className="px-6 py-4 text-center font-mono font-bold text-slate-700 print:text-black">{item.kmTotal.toLocaleString()}</td>
                                <td className="px-6 py-4 text-center font-mono font-bold text-blue-700 print:text-black">{item.litersTotal.toFixed(1)} L</td>
                                <td className="px-6 py-4 text-center font-mono font-bold text-emerald-700 print:text-black">{formatCurrency(item.costTotal)}</td>
                                <td className="px-6 py-4 text-center"><span className="px-2 py-1 rounded text-xs font-black bg-slate-100 text-slate-600 border border-slate-200 print:border-none print:p-0 print:bg-transparent print:text-black">{item.avg}</span></td>
                            </tr>
                        ))}
                    </tbody>
                    <tfoot className="bg-slate-100 text-black font-black">
                        <tr>
                            <td colSpan={2} className="px-6 py-5 text-right uppercase text-xs tracking-widest print:border-t-2 print:border-black">Totais Consolidados:</td>
                            <td className="px-6 py-5 text-center text-lg print:border-t-2 print:border-black">{totals.km.toLocaleString()} KM</td>
                            <td className="px-6 py-5 text-center text-lg print:border-t-2 print:border-black">{totals.liters.toFixed(1)} L</td>
                            <td className="px-6 py-5 text-center text-lg print:border-t-2 print:border-black">{formatCurrency(totals.cost)}</td>
                            <td className="px-6 py-5 print:border-t-2 print:border-black"></td>
                        </tr>
                    </tfoot>
                </table>
            </div>
        </div>
    );
};

