                                <span className="text-slate-400 font-bold print:text-black">{log.lastRefuelingInfo.date.substring(5).split('-').reverse().join('/')}</span>
                            </div>
                        ) : <span className="text-slate-300">-</span>}
                     </td>

                     <td className="px-4 py-3 no-print">
                        <div className="flex justify-center gap-1">
